INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('636e156e-117e-4506-8fcf-557bd5da97a4', '懷連上舊居', '懷連上旧居', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["閑思連上景難齊，樹繞仙鄉路繞溪。","明月夜舟漁父唱，春風平野鷓鴣啼。","城邊寄信歸雲外，花下傾杯到日西。","更憶海陽垂釣侶，昔年相遇草萋萋。"]', '["闲思連上景难齊，樹繞仙乡路繞溪。","明月夜舟漁父唱，春风平野鷓鴣啼。","城邊寄信归云外，花下傾杯到日西。","更憶海陽垂釣侶，昔年相遇草萋萋。"]', '诗', 'shi', '', NULL, '懷連上舊居 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e54d0343-a5ee-4079-9ea4-0b72082b8d29', '公子行', '公子行', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["錦衣紅奪彩霞明，侵曉春遊向野庭。","不識農夫辛苦力，驕驄蹋爛麥青青。"]', '["錦衣紅奪彩霞明，侵晓春游向野庭。","不識農夫辛苦力，驕驄蹋爛麦青青。"]', '诗', 'shi', '', NULL, '公子行 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f8808a-0eff-4a69-9e65-869fa764205a', '湘江亭', '湘江亭', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["獨宿大中年裏寺，樊籠得出事無心。","寒山夢覺一聲磬，霜葉滿林秋正深。"]', '["独宿大中年裏寺，樊籠得出事無心。","寒山梦覺一声磬，霜葉满林秋正深。"]', '诗', 'shi', '', NULL, '湘江亭 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d9ad8a-7895-4172-a864-9f116161aedf', '題梅仙館', '題梅仙館', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["仙界路遙雲縹渺，古壇風冷葉蕭騷。","後來豈合言淹滯，一尉昇騰道最高。"]', '["仙界路遙云縹渺，古壇风冷葉蕭騷。","後来豈合言淹滯，一尉昇腾道最高。"]', '诗', 'shi', '', NULL, '題梅仙館 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('399d9ce5-5158-4b93-a0cb-7730ca336576', '題顏氏亭宇', '題顏氏亭宇', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["園林蕭灑聞來久，欲訪因循二十秋。","今日開襟吟不盡，碧山重疊水長流。"]', '["园林蕭灑闻来久，欲訪因循二十秋。","今日开襟吟不尽，碧山重叠水长流。"]', '诗', 'shi', '', NULL, '題顏氏亭宇 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e8179bc-b010-43c5-8d11-02f308ad1c73', '晚眺', '晚眺', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["倚杖殘秋裏，吟中四顧頻。","西風天際雁，落日渡頭人。","草色衰平野，山陰歛暮塵。","却尋苔徑去，明月照村鄰。"]', '["倚杖殘秋裏，吟中四顧頻。","西风天際雁，落日渡头人。","草色衰平野，山陰歛暮塵。","却尋苔徑去，明月照村鄰。"]', '诗', 'shi', '', NULL, '晚眺 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df59a889-d5ba-43ce-bc33-c3da2e5f27e8', '獻主司', '獻主司', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["那堪雨後更聞蟬，溪隔重湖路七千。","憶昔故園楊柳岸，全家送上渡頭船。"]', '["那堪雨後更闻蟬，溪隔重湖路七千。","憶昔故园楊柳岸，全家送上渡头船。"]', '诗', 'shi', '', NULL, '獻主司 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('876d8255-63e4-488e-9c61-468bf7db08a0', '句', '句', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["遠樹連沙靜，閑舟入浦遲。","簾垂羣吏散，苔長訟庭閑。","去年曾折處，今日又垂條。","早知落處隨疎雨，悔得開時順暖風。","千家簾幕春空在，幾處樓臺月自明。","臘雪化爲流水去，春風吹出好山來。","昔日聲塵喧洛下，近年詩句滿江南。","匝地人家憑檻見，遠山秋色捲簾看。","蟾宮空手下，澤國更誰來。","水國二親應探榜，龍門三月又傷春。","仙鳥却回空說夢，清朝未達自嫌身。","失意從他桃李春，嵩陽經過歇行塵。","雲僧不見城中事，問是今年第幾人。","因逢日者教重應，忍被雲僧勸却歸。"]', '["远樹連沙静，闲舟入浦遲。","簾垂羣吏散，苔长訟庭闲。","去年曾折处，今日又垂條。","早知落处隨疎雨，悔得开时順暖风。","千家簾幕春空在，幾处楼台月自明。","臘雪化爲流水去，春风吹出好山来。","昔日声塵喧洛下，近年诗句满江南。","匝地人家憑檻见，远山秋色捲簾看。","蟾宮空手下，澤国更誰来。","水国二親應探榜，龙门三月又傷春。","仙鸟却回空说梦，清朝未達自嫌身。","失意從他桃李春，嵩陽經過歇行塵。","云僧不见城中事，问是今年第幾人。","因逢日者教重應，忍被云僧勸却归。"]', '诗', 'shi', '', NULL, '句 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c09f00a-7a12-472a-a44c-bdf98cd689c0', '九日陪董內召登高', '九日陪董內召登高', 'ed3c6be5-7336-4f5b-8c37-962f95bf6378', '唐', '["祝融峰下逢嘉節，相對那能不愴神。","煙裏共尋幽磵菊，樽前俱是異鄉人。","遙山帶日應連越，孤雁來時想別秦。","自古登高盡惆悵，茱萸休笑淚盈巾。"]', '["祝融峰下逢嘉節，相对那能不愴神。","煙裏共尋幽磵菊，樽前俱是異乡人。","遙山带日應連越，孤雁来时想別秦。","自古登高尽惆悵，茱萸休笑泪盈巾。"]', '诗', 'shi', '', NULL, '九日陪董內召登高 廖匡圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('980a7a70-83c5-46ab-bf62-1b8f93643d9f', '贈泉陵上人', '贈泉陵上人', 'ed3c6be5-7336-4f5b-8c37-962f95bf6378', '唐', '["暫把枯藤倚碧根，禪堂初創楚江濆。","直疑松小難留鶴，未信山低住得雲。","草接寺橋牛笛近，日銜村樹鳥行分。","每來共憶曾遊處，萬壑泉聲絕頂聞。"]', '["暫把枯藤倚碧根，禪堂初創楚江濆。","直疑松小难留鹤，未信山低住得云。","草接寺橋牛笛近，日銜村樹鸟行分。","每来共憶曾游处，万壑泉声絕頂闻。"]', '诗', 'shi', '', NULL, '贈泉陵上人 廖匡圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f7ae86-25dc-41c8-bf03-46e4b6ed191a', '和人贈沈彬', '和人贈沈彬', 'ed3c6be5-7336-4f5b-8c37-962f95bf6378', '唐', '["冥鴻跡在煙霞上，燕雀休誇大廈巢。","名利最爲浮世重，古今能有幾人拋。","逼真但使心無著，混俗何妨手強抄。","深喜卜居連岳色，水邊竹下得論交。"]', '["冥鴻跡在煙霞上，燕雀休誇大廈巢。","名利最爲浮世重，古今能有幾人拋。","逼真但使心無著，混俗何妨手強抄。","深喜卜居連岳色，水邊竹下得論交。"]', '诗', 'shi', '', NULL, '和人贈沈彬 廖匡圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f2c68f2-a84f-4c11-b91e-1e1a73c26ead', '松', '松', 'ed3c6be5-7336-4f5b-8c37-962f95bf6378', '唐', '["曾於西晉封中散，又向東吳作大夫。","濃翠自知千古在，清聲誰道四時無。","枝柯偃後龍蛇老，根脚盤來爪距粗。","直待素秋搖落日，始將凡木鬬榮枯。"]', '["曾於西晉封中散，又向东吳作大夫。","濃翠自知千古在，清声誰道四时無。","枝柯偃後龙蛇老，根脚盤来爪距粗。","直待素秋搖落日，始將凡木鬬榮枯。"]', '诗', 'shi', '', NULL, '松 廖匡圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d42db92-dffc-4404-b46b-5ccd9d7ef146', '句', '句', 'ed3c6be5-7336-4f5b-8c37-962f95bf6378', '唐', '["正悲世上事無限，細看水中塵更多。"]', '["正悲世上事無限，細看水中塵更多。"]', '诗', 'shi', '', NULL, '句 廖匡圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e27965a-bf4c-41ed-b300-3cf8542908a1', '中秋月', '中秋月', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["九十日秋色，今宵已半分。","孤光含列宿，四面絕纖雲。","衆木排疎影，寒流疊細紋。","遙遙望丹桂，心緒正紛紛。"]', '["九十日秋色，今宵已半分。","孤光含列宿，四面絕纖云。","衆木排疎影，寒流叠細紋。","遙遙望丹桂，心緒正紛紛。"]', '诗', 'shi', '', NULL, '中秋月 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ab1f77-9294-40b8-abae-4c9fe5d5a629', '聞蟬', '闻蟬', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["一聲初應侯，萬木已西風。","便感異鄉客，先於離塞鴻。","日斜金谷靜，雨過石城空。","此處不堪聽，蕭條千古同。"]', '["一声初應侯，万木已西风。","便感異乡客，先於離塞鴻。","日斜金谷静，雨過石城空。","此处不堪听，蕭條千古同。"]', '诗', 'shi', '', NULL, '聞蟬 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5de79c-5ecd-4b4a-b8ee-89d78d8912c1', '彭澤解印', '彭澤解印', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["五斗徒勞謾折腰，三年兩鬢爲誰焦。","今朝官滿重歸去，還挈來時舊酒瓢。"]', '["五斗徒勞謾折腰，三年兩鬢爲誰焦。","今朝官满重归去，還挈来时旧酒瓢。"]', '诗', 'shi', '', NULL, '彭澤解印 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d9c021-de1b-401d-ae24-f062567e1ab8', '句', '句', '702cbcfc-11e7-4fd8-9ce8-cebd8dccc088', '唐', '["滿汀漚不散，一局黑全輸。","獵回千帳雪，探密大河冰。","落盡最高樹，始知松柏青。","飯僧春嶺蕨，醒酒雪潭魚。","風清竹閣留僧宿，雨濕莎庭放吏衙。","紅躑躅繁金殿暖，碧芙蓉笑水宮秋。"]', '["满汀漚不散，一局黑全輸。","獵回千帳雪，探密大河冰。","落尽最高樹，始知松柏青。","飯僧春嶺蕨，醒酒雪潭鱼。","风清竹閣留僧宿，雨濕莎庭放吏衙。","紅躑躅繁金殿暖，碧芙蓉笑水宮秋。"]', '诗', 'shi', '', NULL, '句 廖凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a7551da-e569-4f7e-a343-e09bfed39750', '贈廖凝', '贈廖凝', 'b08583e7-aec0-475b-8de7-69e868a28b1f', '唐', '["君與白雲鄰，生涯久忍貧。","姓名高雅道，寰海許何人。","岳氣秋來早，亭寒果落新。","幾回吟石畔，孤鶴自相親。"]', '["君與白云鄰，生涯久忍貧。","姓名高雅道，寰海許何人。","岳氣秋来早，亭寒果落新。","幾回吟石畔，孤鹤自相親。"]', '诗', 'shi', '', NULL, '贈廖凝 韋鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb150aa-6df0-4757-8d17-47c2d8fc32e9', '寄廬山白上人', '寄廬山白上人', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["潦倒門前客，閑眠歲又殘。","連天數峰雪，終日與誰看。","萬丈高松古，千尋落水寒。","仍聞有新作，嬾寄入長安。"]', '["潦倒门前客，闲眠歲又殘。","連天數峰雪，終日與誰看。","万丈高松古，千尋落水寒。","仍闻有新作，嬾寄入长安。"]', '诗', 'shi', '', NULL, '寄廬山白上人 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e42a672-25b2-4aa5-875d-2adff751fa30', '寄韓侍郎', '寄韓侍郎', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["謀身謀隱兩無成，拙計深慙負耦耕。","漸老可堪懷故國，多愁翻覺厭浮生。","言詩幸遇明公許，守朴甘遭俗者輕。","今日況聞搜草澤，獨悲顦顇臥昇平。"]', '["謀身謀隐兩無成，拙計深慙負耦耕。","漸老可堪懷故国，多愁翻覺厭浮生。","言诗幸遇明公許，守朴甘遭俗者轻。","今日況闻搜草澤，独悲顦顇臥昇平。"]', '诗', 'shi', '', NULL, '寄韓侍郎 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e863be7b-16ee-49c9-83d0-90e388ec4ba3', '漢宮詞', '漢宮词', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["寒燭照清夜，笙歌隔蘚牆。","一從飛燕入，便不見君王。"]', '["寒燭照清夜，笙歌隔蘚牆。","一從飞燕入，便不见君王。"]', '诗', 'shi', '', NULL, '漢宮詞 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d8b5c7e-7adb-4067-9925-0ceb2bcb5f74', '送君去', '送君去', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["關河月未曉，行子心已急。","佳人無一言，獨背殘燈泣。"]', '["关河月未晓，行子心已急。","佳人無一言，独背殘灯泣。"]', '诗', 'shi', '', NULL, '送君去 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd329003-2ea6-4652-93ea-558cd723e270', '秋晚野望', '秋晚野望', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["倚筇聊一望，何處是秦川？草色初晴路，鴻聲欲暮天。"]', '["倚筇聊一望，何处是秦川？草色初晴路，鴻声欲暮天。"]', '诗', 'shi', '', NULL, '秋晚野望 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b06d609-c982-47e4-bc74-365915028465', '郊原晚望懷李秘書', '郊原晚望懷李秘书', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["歸鳥入平野，寒雲在遠村。","徒令睇望久，不復見王孫。"]', '["归鸟入平野，寒云在远村。","徒令睇望久，不复见王孫。"]', '诗', 'shi', '', NULL, '郊原晚望懷李秘書 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aecaff2-79e4-447b-932c-92f1af0f1a30', '言懷別同志', '言懷別同志', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["慚老將誰託，勞生每自慙。","何當重攜手，風雨滿江南。"]', '["慚老將誰託，勞生每自慙。","何當重携手，风雨满江南。"]', '诗', 'shi', '', NULL, '言懷別同志 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970c4e17-97b4-4465-bd1c-a3bbc609910a', '江上晚泊', '江上晚泊', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["寒雲淡淡天無際，片帆落處沙鷗起。","水闊風高日復斜，扁舟獨宿蘆花裏。"]', '["寒云淡淡天無際，片帆落处沙鷗起。","水闊风高日复斜，扁舟独宿蘆花裏。"]', '诗', 'shi', '', NULL, '江上晚泊 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60cea404-3830-4800-b1d0-e38385b967fc', '寄鑒上人', '寄鑒上人', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["一從攜手阻戈鋋，屈指如今已十年。","長記二林同宿夜，竹齋聽雨共忘眠。"]', '["一從携手阻戈鋋，屈指如今已十年。","长記二林同宿夜，竹斋听雨共忘眠。"]', '诗', 'shi', '', NULL, '寄鑒上人 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24e9ebdf-00a4-4ba7-b431-ffcf6a1ee786', '送人', '送人', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["一莖二莖華髮生，千枝萬枝梨花白。","春色江南獨未歸，今朝又送還鄉客。"]', '["一莖二莖华髮生，千枝万枝梨花白。","春色江南独未归，今朝又送還乡客。"]', '诗', 'shi', '', NULL, '送人 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b1a46b-d2cf-4a45-b40b-4e188810fa72', '句', '句', '71f1b242-f334-4f7f-af1c-1661804893f5', '唐', '["胡笳聞欲死，漢月望還生。","日華離碧海，雲影散青霄。"]', '["胡笳闻欲死，漢月望還生。","日华離碧海，云影散青霄。"]', '诗', 'shi', '', NULL, '句 左偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb04b93-228b-45a6-b419-ba486c4e909a', '景陽臺懷古', '景陽台懷古', 'a8506600-e0f6-4826-bfab-57f0ffaacd9b', '唐', '["景陽六朝地，運極自依依。","一會皆同是，到頭誰論非。","酒濃沈遠慮，花好失前機。","見此尤宜戒，正當家國肥。"]', '["景陽六朝地，運極自依依。","一會皆同是，到头誰論非。","酒濃沈远慮，花好失前機。","见此尤宜戒，正當家国肥。"]', '诗', 'shi', '', NULL, '景陽臺懷古 陳貺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f898059-c453-4067-98f2-44b1094e5eda', '石城懷古', '石城懷古', '1f0246d9-c998-4fca-ac9c-4ab4a384e3a9', '唐', '["石城古岸頭，一望思悠悠。","幾許六朝事，不禁江水流。"]', '["石城古岸头，一望思悠悠。","幾許六朝事，不禁江水流。"]', '诗', 'shi', '', NULL, '石城懷古 劉洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6321d8f2-241f-4b5d-98c0-7324d0798b9e', '句', '句', '1f0246d9-c998-4fca-ac9c-4ab4a384e3a9', '唐', '["千里長江皆渡馬，十年養士得何人。","翻憶潘郎章奏內，愔愔日暮好沾巾。","百骸同草木，萬象入心靈。"]', '["千里长江皆渡马，十年養士得何人。","翻憶潘郎章奏內，愔愔日暮好沾巾。","百骸同草木，万象入心靈。"]', '诗', 'shi', '', NULL, '句 劉洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a99fa6-e1df-4946-a4df-8a0b94891b3f', '旅懷', '旅懷', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["迢迢江漢路，秋色又堪驚。","半夜聞鴻雁，多年別弟兄。","高風雲影斷，微雨菊花明。","欲寄東歸信，裴回無限情。"]', '["迢迢江漢路，秋色又堪驚。","半夜闻鴻雁，多年別弟兄。","高风云影斷，微雨菊花明。","欲寄东归信，裴回無限情。"]', '诗', 'shi', '', NULL, '旅懷 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560e327d-3754-4136-84fe-2d0df565fc99', '江行', '江行', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["越信隔年稀，孤舟幾夢歸。","月寒花露重，江晚水煙微。","峰直帆相望，沙空鳥自飛。","何時洞庭上，春雨滿蓑衣。"]', '["越信隔年稀，孤舟幾梦归。","月寒花露重，江晚水煙微。","峰直帆相望，沙空鸟自飞。","何时洞庭上，春雨满蓑衣。"]', '诗', 'shi', '', NULL, '江行 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11ca31f-2354-4bf8-8be4-101c5e81c601', '登潤州城', '登潤州城', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["天末江城晚，登臨客望迷。","春潮平島嶼，殘雨隔虹霓。","鳥與孤帆遠，煙和獨樹低。","鄉山何處是，目斷廣陵西。"]', '["天末江城晚，登臨客望迷。","春潮平島嶼，殘雨隔虹霓。","鸟與孤帆远，煙和独樹低。","乡山何处是，目斷廣陵西。"]', '诗', 'shi', '', NULL, '登潤州城 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be02f3fe-eb71-419e-b365-b9976197bd7a', '岳陽樓', '岳陽楼', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["倚樓高望極，展轉念前途。","晚葉紅殘楚，秋江碧入吳。","雲中來雁急，天末去帆孤。","明月誰同我，悠悠上帝都。"]', '["倚楼高望極，展轉念前途。","晚葉紅殘楚，秋江碧入吳。","云中来雁急，天末去帆孤。","明月誰同我，悠悠上帝都。"]', '诗', 'shi', '', NULL, '岳陽樓 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f5de3b-419a-493d-9fd6-185ce3802149', '送客', '送客', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["明月孤舟遠，吟髭鑷更華。","天形圍澤國，秋色露人家。","水館螢交影，霜洲橘委花。","何當尋舊隱，泉石好生涯。"]', '["明月孤舟远，吟髭鑷更华。","天形圍澤国，秋色露人家。","水館螢交影，霜洲橘委花。","何當尋旧隐，泉石好生涯。"]', '诗', 'shi', '', NULL, '送客 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e31f81e-ea21-44d1-b963-faa4c784c7bd', '臨刑詩', '臨刑诗', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["街鼓侵人急，西傾日欲斜。","黃泉無旅店，今夜宿誰家。"]', '["街鼓侵人急，西傾日欲斜。","黄泉無旅店，今夜宿誰家。"]', '诗', 'shi', '', NULL, '臨刑詩 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('224881c4-99ea-440d-8d77-893e03e64dfd', '塞下曲', '塞下曲', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["萬里黃雲凍不飛，磧煙烽火夜深微。","胡兒移帳寒笳絕，雪路時聞探馬歸。"]', '["万里黄云凍不飞，磧煙烽火夜深微。","胡兒移帳寒笳絕，雪路时闻探马归。"]', '诗', 'shi', '', NULL, '塞下曲 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e25d0b2-5f9f-4e91-a639-c86d05561510', '隋堤柳', '隋堤柳', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["錦纜龍舟萬里來，醉鄉繁盛忽塵埃。","空餘兩岸千株柳，雨葉風花作恨媒。"]', '["錦纜龙舟万里来，醉乡繁盛忽塵埃。","空餘兩岸千株柳，雨葉风花作恨媒。"]', '诗', 'shi', '', NULL, '隋堤柳 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac15061-cff3-4487-b9e1-b96ddd64f800', '句', '句', '2c295e1d-037e-4c56-af87-f798cee2799b', '唐', '["吟登蕭寺旃檀閣，醉倚王家玳瑁筵。","遠遠朝宗出白雲，方圓隨處性長存。"]', '["吟登蕭寺旃檀閣，醉倚王家玳瑁筵。","远远朝宗出白云，方圓隨处性长存。"]', '诗', 'shi', '', NULL, '句 江爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3698adf0-0bcb-4e9f-8e97-6ef4de6e1205', '詠鷹', '詠鷹', '84bbd7aa-6484-4bcb-b87b-357a045080e6', '唐', '["雪爪星眸世所稀，摩天專待振毛衣。","虞人莫謾張羅網，未肯平原淺草飛。"]', '["雪爪星眸世所稀，摩天專待振毛衣。","虞人莫謾張羅網，未肯平原淺草飞。"]', '诗', 'shi', '', NULL, '詠鷹 高越 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2253630c-33f0-44c3-bd15-efb4562d4bcf', '惜花', '惜花', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["蝶散鶯啼尚數枝，日斜風定更離披。","看多記得傷心事，金谷樓前委地時。"]', '["蝶散鶯啼尚數枝，日斜风定更離披。","看多記得傷心事，金谷楼前委地时。"]', '诗', 'shi', '', NULL, '惜花 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afc2e6d6-e67f-4513-a6ab-82841d2f97cc', '寄人 一', '寄人 一', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["別夢依依到謝家，小廊迴合曲闌斜。","多情只有春庭月，猶爲離人照落花。"]', '["別梦依依到謝家，小廊迴合曲闌斜。","多情只有春庭月，猶爲離人照落花。"]', '诗', 'shi', '', NULL, '寄人 一 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d590059b-5af2-47e5-b5c1-302afda05bd7', '寄人 二', '寄人 二', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["酷憐風月爲多情，還到春時別恨生。","倚柱尋思倍惆悵，一場春夢不分明。"]', '["酷怜风月爲多情，還到春时別恨生。","倚柱尋思倍惆悵，一場春梦不分明。"]', '诗', 'shi', '', NULL, '寄人 二 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e58e1d3-e0f2-41b4-9592-f0d126835822', '邊上', '邊上', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["戍樓吹角起征鴻，獵獵寒旌背晚風。","千里暮煙愁不盡，一川秋草恨無窮。","山河慘澹關城閉，人物蕭條市井空。","只此旅魂招未得，更堪回首夕陽中。"]', '["戍楼吹角起征鴻，獵獵寒旌背晚风。","千里暮煙愁不尽，一川秋草恨無窮。","山河慘澹关城閉，人物蕭條市井空。","只此旅魂招未得，更堪回首夕陽中。"]', '诗', 'shi', '', NULL, '邊上 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c0c67f-eb61-4dfc-8685-a43c60f1e0e2', '長安道中早行', '长安道中早行', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["客離孤館一燈殘，牢落星河欲曙天。","雞唱未沈函谷月，鴈聲新度灞陵煙。","浮生已悟莊周蝶，壯志仍輸祖逖鞭。","何事悠悠策羸馬，此中辛苦過流年。"]', '["客離孤館一灯殘，牢落星河欲曙天。","雞唱未沈函谷月，鴈声新度灞陵煙。","浮生已悟莊周蝶，壯志仍輸祖逖鞭。","何事悠悠策羸马，此中辛苦過流年。"]', '诗', 'shi', '', NULL, '長安道中早行 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca299bb7-8032-49a5-98c1-2e5b1be183ed', '洞庭阻風', '洞庭阻风', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["空江浩蕩景蕭然，盡日菰蒲泊釣船。","青草浪高三月渡，綠楊花撲一溪煙。","情多莫舉傷春目，愁極兼無買酒錢。","猶有漁人數家住，不成村落夕陽邊。"]', '["空江浩蕩景蕭然，尽日菰蒲泊釣船。","青草浪高三月渡，綠楊花撲一溪煙。","情多莫舉傷春目，愁極兼無買酒錢。","猶有漁人數家住，不成村落夕陽邊。"]', '诗', 'shi', '', NULL, '洞庭阻風 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfcad900-d09c-4c60-8b65-d1bc4aa3ab16', '春日旅泊桂州', '春日旅泊桂州', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["暖風芳草竟芊綿，多病多愁負少年。","弱柳未勝寒食雨，好花爭奈夕陽天。","溪邊物色堪圖畫，林畔鶯聲似管弦。","獨有離人開淚眼，強憑杯酒亦澘然。"]', '["暖风芳草竟芊綿，多病多愁負少年。","弱柳未勝寒食雨，好花爭奈夕陽天。","溪邊物色堪圖畫，林畔鶯声似管弦。","独有離人开泪眼，強憑杯酒亦澘然。"]', '诗', 'shi', '', NULL, '春日旅泊桂州 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73467be0-bcdc-4a1d-a528-463192baaa52', '晚次（一作「歇」）湘源縣', '晚次（一作「歇」）湘源縣', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["煙郭遙聞向晚雞，水平舟靜浪聲齊。","高林帶雨楊梅熟，曲岸籠雲謝豹啼。","二女廟荒汀（一作「宫」）樹老，九疑山碧楚天低。","湘南自古多離怨，莫動哀吟易慘悽。"]', '["煙郭遙闻向晚雞，水平舟静浪声齊。","高林带雨楊梅熟，曲岸籠云謝豹啼。","二女廟荒汀（一作「宫」）樹老，九疑山碧楚天低。","湘南自古多離怨，莫动哀吟易慘悽。"]', '诗', 'shi', '', NULL, '晚次（一作「歇」）湘源縣 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3372012-3d57-4646-ae05-98b2f6b96cca', '惆悵吟', '惆悵吟', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["秋風丹葉動荒城，慘澹雲遮日半明。","晝夢却因惆悵得，晚愁多爲別離生。","江淹彩筆空留恨，莊叟玄譚未及情。","千古怨魂銷不得，一江寒浪若爲平。"]', '["秋风丹葉动荒城，慘澹云遮日半明。","晝梦却因惆悵得，晚愁多爲別離生。","江淹彩笔空留恨，莊叟玄譚未及情。","千古怨魂銷不得，一江寒浪若爲平。"]', '诗', 'shi', '', NULL, '惆悵吟 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce7ee03a-66cf-48f4-ab4d-b723df99e5ed', '秋晚過洞庭', '秋晚過洞庭', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["征帆初挂酒初酣，暮景離情兩不堪。","千里晚霞雲夢北，一洲霜橘洞庭南。","溪風送雨過秋寺，磵石驚龍落夜潭。","莫把羈魂弔湘魄，九疑愁絕銷煙嵐。"]', '["征帆初挂酒初酣，暮景離情兩不堪。","千里晚霞云梦北，一洲霜橘洞庭南。","溪风送雨過秋寺，磵石驚龙落夜潭。","莫把羈魂弔湘魄，九疑愁絕銷煙嵐。"]', '诗', 'shi', '', NULL, '秋晚過洞庭 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d0f6d82-728b-4eb1-b76b-654623b89bca', '題華嚴寺木塔', '題华嚴寺木塔', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["六街晴色動秋光，雨霽憑高只易傷。","一曲晚煙浮渭水，半橋斜日照咸陽。","休將世路悲塵事，莫指雲山認故鄉。","回首漢宮樓閣暮，數聲鐘鼓自微茫。"]', '["六街晴色动秋光，雨霽憑高只易傷。","一曲晚煙浮渭水，半橋斜日照咸陽。","休將世路悲塵事，莫指云山認故乡。","回首漢宮楼閣暮，數声鐘鼓自微茫。"]', '诗', 'shi', '', NULL, '題華嚴寺木塔 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe87cea-bd22-40d4-b6bc-894cddd62f7a', '經舊遊', '經旧游', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["暫到高唐曉又還，丁香結夢水潺潺。","不知雲雨歸何處，歷歷空留十二山。"]', '["暫到高唐晓又還，丁香結梦水潺潺。","不知云雨归何处，歷歷空留十二山。"]', '诗', 'shi', '', NULL, '經舊遊 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06e3198-2b51-47b8-a6f5-c247402453e7', '碧戶', '碧戶', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["碧戶扃魚鏁，蘭窗掩鏡臺。","落花疑悵望，歸燕自裴回。","詠絮知難敵，傷春不易裁。","恨從芳草起，愁爲晚風來。","衣惹湘雲薄，眉分楚岫開。","香濃眠舊枕，夢好醉春杯。","小障明金鳳，幽屏點翠苔。","寶箏橫塞鴈，怨笛落江梅。","卓氏仍多酒，相如正富才。","莫教琴上意，翻作鶴聲哀。"]', '["碧戶扃鱼鏁，蘭窗掩镜台。","落花疑悵望，归燕自裴回。","詠絮知难敵，傷春不易裁。","恨從芳草起，愁爲晚风来。","衣惹湘云薄，眉分楚岫开。","香濃眠旧枕，梦好醉春杯。","小障明金鳳，幽屏点翠苔。","寶箏橫塞鴈，怨笛落江梅。","卓氏仍多酒，相如正富才。","莫教琴上意，翻作鹤声哀。"]', '诗', 'shi', '', NULL, '碧戶 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f364b96e-c18c-4b10-afda-4e3fa15d810c', '芍藥', '芍藥', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["香清粉澹怨殘春，蝶翅蜂鬚戀蘂塵。","閑倚晚風生悵望，靜留遲日學因循。","休將薜荔爲青瑣，好與玫瑰作近鄰。","零落若教隨暮雨，又應愁殺別離人。"]', '["香清粉澹怨殘春，蝶翅蜂鬚戀蘂塵。","闲倚晚风生悵望，静留遲日学因循。","休將薜荔爲青瑣，好與玫瑰作近鄰。","零落若教隨暮雨，又應愁殺別離人。"]', '诗', 'shi', '', NULL, '芍藥 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7ad772-3ffa-475f-b711-3858e89a1541', '春晚謠', '春晚謠', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["雨微微，煙霏霏，小庭半拆紅薔薇。","鈿箏斜倚畫屏曲，零落幾行金鴈飛。","蕭關夢斷無尋處，萬疊春波起南浦。","凌亂楊花撲繡簾，晚窗時有流鶯語。"]', '["雨微微，煙霏霏，小庭半拆紅薔薇。","鈿箏斜倚畫屏曲，零落幾行金鴈飞。","蕭关梦斷無尋处，万叠春波起南浦。","凌亂楊花撲繡簾，晚窗时有流鶯語。"]', '诗', 'shi', '', NULL, '春晚謠 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95270121-f720-408d-a4bd-106f52bd5578', '所思', '所思', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["空塘水碧春雨微，東風散漫楊柳飛。","依依南浦夢猶在，脈脈高唐雲不歸。","江頭日暮多芳草，極目傷心煙悄悄。","隔江紅杏一枝明，似玉佳人俯清沼。","休向春臺更迴望，銷魂自古因惆悵。","銀河碧海共無情，兩處悠悠起風浪。"]', '["空塘水碧春雨微，东风散漫楊柳飞。","依依南浦梦猶在，脈脈高唐云不归。","江头日暮多芳草，極目傷心煙悄悄。","隔江紅杏一枝明，似玉佳人俯清沼。","休向春台更迴望，銷魂自古因惆悵。","銀河碧海共無情，兩处悠悠起风浪。"]', '诗', 'shi', '', NULL, '所思 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4e2ef26-9f13-4339-9e5e-c75ba95ccaa1', '春夕言懷', '春夕言懷', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["風透疎簾月滿庭，倚欄無事倍傷情。","煙垂柳帶纖腰軟，露滴花房怨臉明。","愁逐野雲銷不盡，情隨春浪去難平。","幽窗謾結相思夢，欲化西園蝶未成。"]', '["风透疎簾月满庭，倚欄無事倍傷情。","煙垂柳带纖腰軟，露滴花房怨臉明。","愁逐野云銷不尽，情隨春浪去难平。","幽窗謾結相思梦，欲化西园蝶未成。"]', '诗', 'shi', '', NULL, '春夕言懷 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2251bf3-1fd1-44ee-8d12-49180f52e8d5', '春江雨', '春江雨', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["雨溟溟，風泠泠，老松瘦竹臨煙汀。","空江冷落野雲重，村中鬼火微如星。","夜驚溪上漁人起，滴瀝篷聲滿愁耳。","子規叫斷獨未眠，罨岸春濤打船尾。"]', '["雨溟溟，风泠泠，老松瘦竹臨煙汀。","空江冷落野云重，村中鬼火微如星。","夜驚溪上漁人起，滴瀝篷声满愁耳。","子規叫斷独未眠，罨岸春濤打船尾。"]', '诗', 'shi', '', NULL, '春江雨 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d15acf8-4559-45ee-b860-f6f85d2bf6c1', '送容州中丞赴鎮', '送容州中丞赴鎮', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["交趾同星坐，龍泉佩斗文。","燒香翠羽帳，看舞鬱金裙。","鷁首衝瀧浪，犀渠拂嶺雲。","莫教銅柱北，祗說馬將軍。"]', '["交趾同星坐，龙泉佩斗文。","燒香翠羽帳，看舞鬱金裙。","鷁首衝瀧浪，犀渠拂嶺云。","莫教銅柱北，祗说马將軍。"]', '诗', 'shi', '', NULL, '送容州中丞赴鎮 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9ec1a3-a8f8-4dca-91c3-b9ac0f495747', '贈韓道士', '贈韓道士', '9dd49f54-7d4b-43e9-9fd7-d30a2912fd1d', '唐', '["日暮秋風吹野花，上清歸客意無涯。","桃源寂寂煙霞閉，天路悠悠星漢斜。","還似世人生白髮，定知仙骨變黃芽。","東城南陌頻相見，應是壺中別有家。"]', '["日暮秋风吹野花，上清归客意無涯。","桃源寂寂煙霞閉，天路悠悠星漢斜。","還似世人生白髮，定知仙骨变黄芽。","东城南陌頻相见，應是壺中別有家。"]', '诗', 'shi', '', NULL, '贈韓道士 張泌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbbd40ba-bf9d-40cc-9e41-b9c911858946', '甘露寺', '甘露寺', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["寒暄皆有景，孤絕畫難形。","地拱千尋嶮，天垂四面青。","晝燈籠鴈塔，夜磬徹漁汀。","最愛僧房好，波光滿戶庭。"]', '["寒暄皆有景，孤絕畫难形。","地拱千尋嶮，天垂四面青。","晝灯籠鴈塔，夜磬徹漁汀。","最愛僧房好，波光满戶庭。"]', '诗', 'shi', '', NULL, '甘露寺 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67bfae1b-6a28-47f5-a3d8-9c5c52c43b7e', '題金山寺', '題金山寺', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["萬古波心寺，金山名目新。","天多剩得月，地少不生塵。","過樐妨僧定，驚濤濺佛身。","誰言張處士，題後更無人。"]', '["万古波心寺，金山名目新。","天多剩得月，地少不生塵。","過樐妨僧定，驚濤濺佛身。","誰言張处士，題後更無人。"]', '诗', 'shi', '', NULL, '題金山寺 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8fa90ac-0893-4543-8d54-714b5b810fd9', '楊柳枝詞五首 一', '楊柳枝词五首 一', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["靈和風暖太昌春，舞線搖絲向昔人。","何似曉來江雨後，一行如畫隔遙津。"]', '["靈和风暖太昌春，舞線搖絲向昔人。","何似晓来江雨後，一行如畫隔遙津。"]', '诗', 'shi', '', NULL, '楊柳枝詞五首 一 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6008ef1c-8df1-43b9-9108-8f0ba028d032', '楊柳枝詞五首 二', '楊柳枝词五首 二', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["彭澤初栽五樹時，只應閑看一枝垂。","不知天意風流處，要與佳人學畫眉。"]', '["彭澤初栽五樹时，只應闲看一枝垂。","不知天意风流处，要與佳人学畫眉。"]', '诗', 'shi', '', NULL, '楊柳枝詞五首 二 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47439efa-8a39-41ff-8c99-d621e1e5d621', '楊柳枝詞五首 三', '楊柳枝词五首 三', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["暖傍離亭靜拂橋，入流穿檻綠陰搖。","不知落日誰相送，魂斷千條與萬條。"]', '["暖傍離亭静拂橋，入流穿檻綠陰搖。","不知落日誰相送，魂斷千條與万條。"]', '诗', 'shi', '', NULL, '楊柳枝詞五首 三 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fdaac82-19ca-43f0-95d2-2c978a405eaa', '楊柳枝詞五首 四', '楊柳枝词五首 四', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["春來綠樹遍天涯，未見垂楊未可誇。","晴日萬株煙一陣，閑坊兼是莫愁家。"]', '["春来綠樹遍天涯，未见垂楊未可誇。","晴日万株煙一陣，闲坊兼是莫愁家。"]', '诗', 'shi', '', NULL, '楊柳枝詞五首 四 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68ad0d3-e3e0-41de-9688-d7b4686f3e03', '楊柳枝詞五首 五', '楊柳枝词五首 五', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["十首當年有舊詞，唱青歌翠幾無遺。","未曾得向行人道，不謂離情莫折伊。"]', '["十首當年有旧词，唱青歌翠幾無遺。","未曾得向行人道，不謂離情莫折伊。"]', '诗', 'shi', '', NULL, '楊柳枝詞五首 五 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6ced2c-8a6c-4be4-b4d5-297a9cdd2b0d', '句', '句', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["遊子未歸去，野花愁破心。","劃多灰漸冷，坐久席成痕。","結宇孤峰上，安禪巨浪間。","分開朝海浪，留住過江雲。","劃多灰雜蒼虯跡，坐久煙消寶鴨香。"]', '["游子未归去，野花愁破心。","劃多灰漸冷，坐久席成痕。","結宇孤峰上，安禪巨浪间。","分开朝海浪，留住過江云。","劃多灰杂蒼虯跡，坐久煙消寶鴨香。"]', '诗', 'shi', '', NULL, '句 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5042001-bf58-4636-bfe6-0a99c4ee7920', '入塞二首 一', '入塞二首 一', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["欲爲皇王服遠戎，萬人金甲鼓鼙中。","陣雲黯塞三邊黑，兵血愁天一片紅。","半夜翻營旗攪月，深秋防戍劒磨風。","謗書未及明君爇，臥骨將軍已歿功。"]', '["欲爲皇王服远戎，万人金甲鼓鼙中。","陣云黯塞三邊黑，兵血愁天一片紅。","半夜翻營旗攪月，深秋防戍劒磨风。","謗书未及明君爇，臥骨將軍已歿功。"]', '诗', 'shi', '', NULL, '入塞二首 一 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('290c46a3-d66e-4a6c-be75-97cd9a91b7ec', '入塞二首 二', '入塞二首 二', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["苦戰沙門臥箭痕，戍樓閑上望星文。","生希國澤分偏將，死奪河源荅聖君。","鳶覰敗兵眠白草，馬驚邊鬼哭陰雲。","功多地遠無人紀，漢閣笙歌日又曛。"]', '["苦戰沙门臥箭痕，戍楼闲上望星文。","生希国澤分偏將，死奪河源荅聖君。","鳶覰敗兵眠白草，马驚邊鬼哭陰云。","功多地远無人紀，漢閣笙歌日又曛。"]', '诗', 'shi', '', NULL, '入塞二首 二 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20d2c7b0-1b43-450e-a5b5-ac0c58bf1d32', '塞下三首 一', '塞下三首 一', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["塞葉聲悲秋欲霜，寒山數點下牛羊。","映霞旅鴈隨疎雨，向磧行人帶夕陽。","邊騎不來沙路失，國恩深後海城荒。","胡兒向化新成長，猶自千回問漢王。"]', '["塞葉声悲秋欲霜，寒山數点下牛羊。","映霞旅鴈隨疎雨，向磧行人带夕陽。","邊騎不来沙路失，国恩深後海城荒。","胡兒向化新成长，猶自千回问漢王。"]', '诗', 'shi', '', NULL, '塞下三首 一 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bcb3149-2569-415c-9882-0e90c56a4198', '塞下三首 二', '塞下三首 二', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["貴主和親殺氣沉，燕山閑獵鼓鼙音。","旗分雪草偷邊馬，箭入寒雲落塞禽。","隴月盡牽鄉思動，戰衣誰寄淚痕深。","金釵謾作封侯別，劈破佳人萬里心。"]', '["貴主和親殺氣沉，燕山闲獵鼓鼙音。","旗分雪草偷邊马，箭入寒云落塞禽。","隴月尽牽乡思动，戰衣誰寄泪痕深。","金釵謾作封侯別，劈破佳人万里心。"]', '诗', 'shi', '', NULL, '塞下三首 二 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('157c973d-0652-41e7-84e4-39488103a905', '塞下三首 三', '塞下三首 三', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["月冷榆關過鴈行，將軍寒笛老思鄉。","貳師骨恨千夫壯，李廣魂飛一劒長。","戍角就沙催落日，陰雲分磧護飛霜。","誰知漢武輕中國，閑奪天山草木荒。"]', '["月冷榆关過鴈行，將軍寒笛老思乡。","貳師骨恨千夫壯，李廣魂飞一劒长。","戍角就沙催落日，陰云分磧護飞霜。","誰知漢武轻中国，闲奪天山草木荒。"]', '诗', 'shi', '', NULL, '塞下三首 三 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b152a308-22b9-4f18-86a5-975a93cf9a02', '秋日', '秋日', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["秋含砧杵擣斜陽，笛引西風顥氣涼。","薜荔惹煙籠蟋蟀，芰荷翻雨潑鴛鴦。","當年酒賤何妨醉，今日時難不易狂。","腸斷舊遊從一別，潘安惆悵滿頭霜。"]', '["秋含砧杵擣斜陽，笛引西风顥氣涼。","薜荔惹煙籠蟋蟀，芰荷翻雨潑鴛鴦。","當年酒賤何妨醉，今日时难不易狂。","腸斷旧游從一別，潘安惆悵满头霜。"]', '诗', 'shi', '', NULL, '秋日 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('086aff2d-11ac-4c35-abbb-99e446f6049b', '金陵雜題二首 一', '金陵杂題二首 一', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["王氣生秦四百年，晉元東渡浪花船。","正慙海內皆塗地，來保江南一片天。","古樹著行臨遠岸，暮山相亞出微煙。","千征萬戰英雄盡，落日牛羊食野田。"]', '["王氣生秦四百年，晉元东渡浪花船。","正慙海內皆塗地，来保江南一片天。","古樹著行臨远岸，暮山相亞出微煙。","千征万戰英雄尽，落日牛羊食野田。"]', '诗', 'shi', '', NULL, '金陵雜題二首 一 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ab6598-5092-4968-9701-cf8430fcd747', '金陵雜題二首 二', '金陵杂題二首 二', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["暮潮聲落草光沉，賈客來帆宿岸陰。","一笛月明何處酒，滿城秋色幾家砧。","時清曾惡桓溫盛，山翠長牽謝傅心。","今日到來何物在，碧煙和雨鎖寒林。"]', '["暮潮声落草光沉，賈客来帆宿岸陰。","一笛月明何处酒，满城秋色幾家砧。","时清曾惡桓溫盛，山翠长牽謝傅心。","今日到来何物在，碧煙和雨鎖寒林。"]', '诗', 'shi', '', NULL, '金陵雜題二首 二 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a78535e-067d-42b5-ac8c-e6259e6d9120', '麻姑山', '麻姑山', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["紺殿松蘿太古山，仙人曾此話桑田。","閑傾雲液十分日，已過浮生一萬年。","花洞路中逢鶴信，水簾巖底見龍眠。","我來遊禮酬心願，欲共怡神契自然。"]', '["紺殿松蘿太古山，仙人曾此話桑田。","闲傾云液十分日，已過浮生一万年。","花洞路中逢鹤信，水簾巖底见龙眠。","我来游禮酬心願，欲共怡神契自然。"]', '诗', 'shi', '', NULL, '麻姑山 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f570916f-2c46-439a-934b-1dd7fd6fe27d', '題蘇仙山', '題蘇仙山', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["眼穿林罅見郴州，井里交連側局揪。","味道不來閑處坐，勞生更欲幾時休。","蘇仙宅古煙霞老，義帝墳荒草木愁。","千古是非無處問，夕陽西去水東流。"]', '["眼穿林罅见郴州，井里交連側局揪。","味道不来闲处坐，勞生更欲幾时休。","蘇仙宅古煙霞老，義帝墳荒草木愁。","千古是非無处问，夕陽西去水东流。"]', '诗', 'shi', '', NULL, '題蘇仙山 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81bf6a5-7217-4d74-a255-3fd02f5b217b', '洪州解至長安初舉納省卷夢仙謠', '洪州解至长安初舉納省卷梦仙謠', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["□□□□□□□，□□□□□□□。","玉殿大開從客入，金桃爛熟沒人偷。","鳳驚寶扇頻翻翅，龍懼金鞭不轉頭。","□□□□□□□，□□□□□□□。"]', '["□□□□□□□，□□□□□□□。","玉殿大开從客入，金桃爛熟沒人偷。","鳳驚寶扇頻翻翅，龙懼金鞭不轉头。","□□□□□□□，□□□□□□□。"]', '诗', 'shi', '', NULL, '洪州解至長安初舉納省卷夢仙謠 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae03b7a3-56e4-42da-a842-7bc5b9dd0143', '憶仙謠', '憶仙謠', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["白榆風颯九天秋，王母朝迴宴玉樓。","日月漸長雙鳳睡，桑田欲變六鼇愁。","雲翻簫管相隨去，星觸旌幢各自流。","詩酒近來狂不得，騎龍却憶上清遊。"]', '["白榆风颯九天秋，王母朝迴宴玉楼。","日月漸长雙鳳睡，桑田欲变六鼇愁。","云翻簫管相隨去，星觸旌幢各自流。","诗酒近来狂不得，騎龙却憶上清游。"]', '诗', 'shi', '', NULL, '憶仙謠 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('863c7f41-2575-48f8-921a-f440ef000fd5', '納省卷贈爲首劉象', '納省卷贈爲首劉象', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["曾應大中天子舉，四朝風月鬢蕭疎。","不隨世祖重攜劒，却爲文皇再讀書。","十載戰塵銷舊業，滿城春雨壞貧居。","一枝何事於君借，仙桂年年幸有餘。"]', '["曾應大中天子舉，四朝风月鬢蕭疎。","不隨世祖重携劒，却爲文皇再读书。","十載戰塵銷旧業，满城春雨壞貧居。","一枝何事於君借，仙桂年年幸有餘。"]', '诗', 'shi', '', NULL, '納省卷贈爲首劉象 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7153f24-aa84-49ab-9465-882f218b4d47', '贈王定保', '贈王定保', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["仙桂曾攀第一枝，薄遊湘水阻佳期。","皋橋已失齊眉願，蕭寺行逢落髮師。","廢苑露寒蘭寂寞，丹山雲斷鳳參差。","聞公已有平生約，謝絕女蘿依兔絲。"]', '["仙桂曾攀第一枝，薄游湘水阻佳期。","皋橋已失齊眉願，蕭寺行逢落髮師。","廢苑露寒蘭寂寞，丹山云斷鳳參差。","闻公已有平生約，謝絕女蘿依兔絲。"]', '诗', 'shi', '', NULL, '贈王定保 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b68cd1b-481e-4221-b1ad-1dc2726a4444', '結客少年場行', '結客少年場行', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["重義輕生一劒知，白虹貫日報讎歸。","片心惆悵清平世，酒市無人問布衣。"]', '["重義轻生一劒知，白虹貫日報讎归。","片心惆悵清平世，酒市無人问布衣。"]', '诗', 'shi', '', NULL, '結客少年場行 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e75c94fe-9831-4e84-8ac9-d9f13fca6e7c', '陽朔碧蓮峰', '陽朔碧蓮峰', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["陶潛彭澤五株柳，潘岳河陽一縣花。","兩處爭如陽朔好，碧蓮峰裏住人家。"]', '["陶潛彭澤五株柳，潘岳河陽一縣花。","兩处爭如陽朔好，碧蓮峰裏住人家。"]', '诗', 'shi', '', NULL, '陽朔碧蓮峰 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aabb49fb-8b7b-4e18-94a6-432cef88809e', '再過金陵', '再過金陵', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["玉樹歌終王氣收，鴈行高送石城秋。","江山不管興亡事，一任斜陽伴客愁。"]', '["玉樹歌終王氣收，鴈行高送石城秋。","江山不管兴亡事，一任斜陽伴客愁。"]', '诗', 'shi', '', NULL, '再過金陵 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd457b7c-c294-4584-aeb5-0a9f6a9d0abc', '都門送別', '都门送別', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["岸柳蕭疎野荻秋，都門行客莫回頭。","一條灞水清如劒，不爲離人割斷愁。"]', '["岸柳蕭疎野荻秋，都门行客莫回头。","一條灞水清如劒，不爲離人割斷愁。"]', '诗', 'shi', '', NULL, '都門送別 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b70654da-93ab-49be-a55c-e6e1a448bc2f', '弔邊人', '弔邊人', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["殺聲沈後野風悲，漢月高時望不歸。","白骨已枯沙上草，家人猶自寄寒衣。"]', '["殺声沈後野风悲，漢月高时望不归。","白骨已枯沙上草，家人猶自寄寒衣。"]', '诗', 'shi', '', NULL, '弔邊人 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6bfc7d-4dba-4362-92ae-3f8b75f47e6a', '句', '句', '49d09d65-92ee-43dd-a9f1-1d23f75b9ff0', '唐', '["尺素隱清輝，一毫分險阻。","金翅動身摩日月，銀河轉浪洗乾坤。","須知手筆安排定，不怕山河整頓難。","九衢冠蓋暗爭路，四海干戈多異心。","地隈一水巡城轉，天約羣山附郭來。","數家魚網疎雲外，一岸殘陽細雨中。","松欹晚影離壇草，鍾撼秋聲入殿風。","壓低吳楚遙涵水，約破雲霞獨倚天。","半身落日離秦樹，一路平蕪入楚煙。","清占月中三峽水，麗偷雲外十洲春。","幽鳥喚人穿竹去，野猨尋果出雲來。"]', '["尺素隐清輝，一毫分險阻。","金翅动身摩日月，銀河轉浪洗乾坤。","須知手笔安排定，不怕山河整頓难。","九衢冠蓋暗爭路，四海干戈多異心。","地隈一水巡城轉，天約羣山附郭来。","數家鱼網疎云外，一岸殘陽細雨中。","松欹晚影離壇草，鍾撼秋声入殿风。","壓低吳楚遙涵水，約破云霞独倚天。","半身落日離秦樹，一路平蕪入楚煙。","清占月中三峽水，丽偷云外十洲春。","幽鸟喚人穿竹去，野猨尋果出云来。"]', '诗', 'shi', '', NULL, '句 沈彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f152091-a91d-48b6-bd6c-cbee22b0a6e1', '僻居謝何明府見訪', '僻居謝何明府见訪', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["公退琴堂動逸懷，閑披煙靄訪微才。","馬嘶窮巷蛙聲息，轍到衡門草色開。","風引柳花當坐起，日將林影入庭來。","滿齋塵土一牀蘚，多謝從容水飯回。"]', '["公退琴堂动逸懷，闲披煙靄訪微才。","马嘶窮巷蛙声息，轍到衡门草色开。","风引柳花當坐起，日將林影入庭来。","满斋塵土一牀蘚，多謝從容水飯回。"]', '诗', 'shi', '', NULL, '僻居謝何明府見訪 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7494a841-ad4c-4b1b-8f73-2ebd1e72c678', '冬日道中', '冬日道中', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["去去天涯無定期，瘦童羸馬共依依。","暮煙江口客來絕，寒葉嶺頭人住稀。","帶雪野風吹旅思，入雲山火照行衣。","釣臺吟閣滄洲在，應爲初心未得歸。"]', '["去去天涯無定期，瘦童羸马共依依。","暮煙江口客来絕，寒葉嶺头人住稀。","带雪野风吹旅思，入云山火照行衣。","釣台吟閣滄洲在，應爲初心未得归。"]', '诗', 'shi', '', NULL, '冬日道中 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c20f1cf3-7397-4688-bc15-69a3568e6a32', '僻居酬友人', '僻居酬友人', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["僻居雖愛近林泉，幽徑閑居碧蘚連。","向竹掩扉隨鶴息，就溪安石學僧禪。","古琴帶月音聲亮，山果經霜氣味全。","多謝故交憐朴野，隔雲時復寄佳篇。"]', '["僻居雖愛近林泉，幽徑闲居碧蘚連。","向竹掩扉隨鹤息，就溪安石学僧禪。","古琴带月音声亮，山果經霜氣味全。","多謝故交怜朴野，隔云时复寄佳篇。"]', '诗', 'shi', '', NULL, '僻居酬友人 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6f29aa5-cd84-4277-888f-aecc2564f287', '遊西山龍泉禪寺', '游西山龙泉禪寺', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["疊巘層峰坐可觀，枕門流水更潺湲。","曉鐘聲徹洞溪遠，夏木影籠軒檻寒。","幽徑乍尋衣屨潤，古堂頻宿夢魂安。","因嗟城郭營營事，不得長遊空鬢殘。"]', '["叠巘層峰坐可观，枕门流水更潺湲。","晓鐘声徹洞溪远，夏木影籠軒檻寒。","幽徑乍尋衣屨潤，古堂頻宿梦魂安。","因嗟城郭營營事，不得长游空鬢殘。"]', '诗', 'shi', '', NULL, '遊西山龍泉禪寺 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc225000-4487-4cdf-a286-1712d1430359', '宿灊山', '宿灊山', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["一入仙山萬慮寬，夜深寧厭倚虛欄。","鶴和雲影宿高木，人帶月光登古壇。","芝朮露濃溪塢白，薜蘿風起殿廊寒。","更陪羽客論真理，不覺初鐘叩曉殘。"]', '["一入仙山万慮寬，夜深寧厭倚虛欄。","鹤和云影宿高木，人带月光登古壇。","芝朮露濃溪塢白，薜蘿风起殿廊寒。","更陪羽客論真理，不覺初鐘叩晓殘。"]', '诗', 'shi', '', NULL, '宿灊山 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc7fef5-4f90-4815-983f-b9bcc6ec5319', '遊西禪', '游西禪', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["遠岫當軒列翠光，高僧一衲萬緣忘。","碧松影裏地長潤，白藕花中水亦香。","雲自雨前生淨石，鶴于鐘後宿長廊。","遊人戀此吟終日，盛暑樓臺早有涼。"]', '["远岫當軒列翠光，高僧一衲万緣忘。","碧松影裏地长潤，白藕花中水亦香。","云自雨前生淨石，鹤于鐘後宿长廊。","游人戀此吟終日，盛暑楼台早有涼。"]', '诗', 'shi', '', NULL, '遊西禪 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63cdc527-e8e1-4e86-9bef-b588b95c6a77', '寄史處士', '寄史处士', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["長羨閑居一水湄，吟情高古有誰知。","石樓待月橫琴久，漁浦經風下釣遲。","僻塢落花多掩徑，舊山殘燒幾侵籬。","松門別後無消息，早晚重應躡屐隨。"]', '["长羨闲居一水湄，吟情高古有誰知。","石楼待月橫琴久，漁浦經风下釣遲。","僻塢落花多掩徑，旧山殘燒幾侵籬。","松门別後無消息，早晚重應躡屐隨。"]', '诗', 'shi', '', NULL, '寄史處士 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b9cdc9-2df8-4f2d-ad6e-531b9195a2a6', '僻居秋思寄友人', '僻居秋思寄友人', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["門巷秋歸更寂寥，雨餘閑砌委蘭苗。","夢迴月夜蟲吟壁，病起茅齋藥滿瓢。","澤國舊遊關遠思，竹林前會負佳招。","身名未立猶辛苦，何許流年晚鬢凋。"]', '["门巷秋归更寂寥，雨餘闲砌委蘭苗。","梦迴月夜蟲吟壁，病起茅斋藥满瓢。","澤国旧游关远思，竹林前會負佳招。","身名未立猶辛苦，何許流年晚鬢凋。"]', '诗', 'shi', '', NULL, '僻居秋思寄友人 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('632d07c5-6525-4196-93e4-5b24454d8f56', '寄落星史虛白處士', '寄落星史虛白处士', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["白雲峰下古溪頭，曾與提壺爛熳遊。","登閣共看彭蠡水，圍爐相憶杜陵秋。","棊玄不厭通高品，句妙多容隔歲酬。","別後相思時一望，暮山空碧水空流。"]', '["白云峰下古溪头，曾與提壺爛熳游。","登閣共看彭蠡水，圍爐相憶杜陵秋。","棊玄不厭通高品，句妙多容隔歲酬。","別後相思时一望，暮山空碧水空流。"]', '诗', 'shi', '', NULL, '寄落星史虛白處士 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7dc655-f2b7-4d55-a22d-644d948029c2', '九江旅夜寄山中故人', '九江旅夜寄山中故人', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["弱柳風高遠漏沈，坐來難便息愁吟。","江城雪盡寒猶在，客舍燈孤夜正深。","塵土積年粘旅服，關山無處寄歸心。","此時遙羨閑眠侶，靜掩雲扉臥一林。"]', '["弱柳风高远漏沈，坐来难便息愁吟。","江城雪尽寒猶在，客舍灯孤夜正深。","塵土積年粘旅服，关山無处寄归心。","此时遙羨闲眠侶，静掩云扉臥一林。"]', '诗', 'shi', '', NULL, '九江旅夜寄山中故人 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62155306-fe70-407d-ac08-2899a415c685', '聞杜牧赴闕', '闻杜牧赴闕', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["舊隱匡廬一草堂，今聞攜策謁吾皇。","峽雲難卷從龍勢，古劒終騰出土光。","開翅定期歸碧落，濯纓寧肯問滄浪。","他時得意交知仰，莫忘裁詩寄釣鄉。"]', '["旧隐匡廬一草堂，今闻携策謁吾皇。","峽云难卷從龙勢，古劒終腾出土光。","开翅定期归碧落，濯纓寧肯问滄浪。","他时得意交知仰，莫忘裁诗寄釣乡。"]', '诗', 'shi', '', NULL, '聞杜牧赴闕 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9752ea-5b07-4abe-b122-9c9eec79018f', '題西林寺水閣', '題西林寺水閣', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["竹翠苔花遶檻濃，此亭幽致詎曾逢。","水分林下清泠派，山峙雲間峭峻峰。","怪石夜光寒射燭，老杉秋韻冷和鐘。","不知來往留題客，誰約重尋蓮社蹤。"]', '["竹翠苔花遶檻濃，此亭幽致詎曾逢。","水分林下清泠派，山峙云间峭峻峰。","怪石夜光寒射燭，老杉秋韻冷和鐘。","不知来往留題客，誰約重尋蓮社蹤。"]', '诗', 'shi', '', NULL, '題西林寺水閣 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767bfcd3-38a2-4389-9d28-1a2e7130c556', '林居喜崔三博遠至', '林居喜崔三博远至', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["幾日區區在遠程，晚煙林徑喜相迎。","姿容雖有塵中色，巾屨猶多嶽上清。","野石靜排爲坐榻，溪茶深煮當飛觥。","留連話與方經宿，又欲攜書別我行。"]', '["幾日區區在远程，晚煙林徑喜相迎。","姿容雖有塵中色，巾屨猶多嶽上清。","野石静排爲坐榻，溪茶深煮當飞觥。","留連話與方經宿，又欲携书別我行。"]', '诗', 'shi', '', NULL, '林居喜崔三博遠至 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b5384ea-655c-42e8-8c10-8c23b1052adb', '觀華夷圖', '观华夷圖', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["別手應難及此精，須知攢簇自心靈。","始於毫末分諸國，漸見圖中列四溟。","關路欲伸通楚勢，蜀山俄聳入秦青。","筆端盡現寰區事，堪把長懸在戶庭。"]', '["別手應难及此精，須知攢簇自心靈。","始於毫末分諸国，漸见圖中列四溟。","关路欲伸通楚勢，蜀山俄聳入秦青。","笔端尽現寰區事，堪把长懸在戶庭。"]', '诗', 'shi', '', NULL, '觀華夷圖 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11e8ffc-4319-444f-82a5-2c25278313b0', '廬山書堂送祝秀才還鄉', '廬山书堂送祝秀才還乡', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["束書辭我下重巔，相送同臨楚岸邊。","歸思幾隨千里水，離情空寄一枝蟬。","園林到日酒初熟，庭戶開時月正圓。","莫使蹉跎戀疎野，男兒酬志在當年。"]', '["束书辞我下重巔，相送同臨楚岸邊。","归思幾隨千里水，離情空寄一枝蟬。","园林到日酒初熟，庭戶开时月正圓。","莫使蹉跎戀疎野，男兒酬志在當年。"]', '诗', 'shi', '', NULL, '廬山書堂送祝秀才還鄉 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41bbb2a-034f-49f4-ac90-8d28ee950dff', '暮冬送何秀才毘陵', '暮冬送何秀才毘陵', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["匹馬嘶風去思長，素琴孤劒稱戎裝。","路塗多是過殘歲，杯酒無辭到醉鄉。","雲傍水村凝冷片，雪連山驛積寒光。","毘陵城下饒嘉景，回日新詩應滿堂。"]', '["匹马嘶风去思长，素琴孤劒稱戎裝。","路塗多是過殘歲，杯酒無辞到醉乡。","云傍水村凝冷片，雪連山驛積寒光。","毘陵城下饒嘉景，回日新诗應满堂。"]', '诗', 'shi', '', NULL, '暮冬送何秀才毘陵 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e0f6a68-3de1-43d9-9082-5b22105d6ce4', '龍潭張道者', '龙潭張道者', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["碧洞幽巖獨息心，時人何路得相尋。","養生不說憑諸藥，適意惟聞在一琴。","石徑掃稀山蘚合，竹軒開晚野雲深。","他年功就期飛去，應笑吾徒多苦吟。"]', '["碧洞幽巖独息心，时人何路得相尋。","養生不说憑諸藥，適意惟闻在一琴。","石徑掃稀山蘚合，竹軒开晚野云深。","他年功就期飞去，應笑吾徒多苦吟。"]', '诗', 'shi', '', NULL, '龍潭張道者 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bf81790-cdb7-4594-80e0-6c44f5b207a6', '晚秋同何秀才溪上', '晚秋同何秀才溪上', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["閑步秋光思杳然，荷藜因共過林煙。","期收野藥尋幽路，欲採溪菱上小船。","雲吐晚陰藏霽岫，柳含餘靄咽殘蟬。","倒尊盡日忘歸處，山磬數聲敲暝天。"]', '["闲步秋光思杳然，荷藜因共過林煙。","期收野藥尋幽路，欲採溪菱上小船。","云吐晚陰藏霽岫，柳含餘靄咽殘蟬。","倒尊尽日忘归处，山磬數声敲暝天。"]', '诗', 'shi', '', NULL, '晚秋同何秀才溪上 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c844e4d-97d3-46e3-897a-602b2563f7cb', '送江少府授延陵後寄', '送江少府授延陵後寄', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["五老雲中勤學者，遇時能不困風塵。","束書西上謁明主，捧檄南歸慰老親。","別館友朋留醉久，去程煙月入吟新。","莫因官小慵之任，自古鸞棲有異人。"]', '["五老云中勤学者，遇时能不困风塵。","束书西上謁明主，捧檄南归慰老親。","別館友朋留醉久，去程煙月入吟新。","莫因官小慵之任，自古鸾棲有異人。"]', '诗', 'shi', '', NULL, '送江少府授延陵後寄 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db3c7284-fb92-4162-b328-c52150776aff', '觀山水障子', '观山水障子', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["功績精妍世少倫，圖時應倍用心神。","不知草木承何異，但見江山長帶春。","雲勢似離巖底石，浪花如動岸邊蘋。","更疑獨泛漁舟者，便是其中舊隱人。"]', '["功績精妍世少倫，圖时應倍用心神。","不知草木承何異，但见江山长带春。","云勢似離巖底石，浪花如动岸邊蘋。","更疑独泛漁舟者，便是其中旧隐人。"]', '诗', 'shi', '', NULL, '觀山水障子 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22250f74-1f08-4851-8b93-f51fb76ff0c6', '寄張學士洎', '寄張学士洎', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["不知何處好消憂，公退攜壺即上樓。","職事久參侯伯幕，夢魂長遶帝王州。","黃山向晚盈軒翠，黟水含春繞檻流。","遙想玉堂多暇日，花時誰伴出城遊。"]', '["不知何处好消憂，公退携壺即上楼。","職事久參侯伯幕，梦魂长遶帝王州。","黄山向晚盈軒翠，黟水含春繞檻流。","遙想玉堂多暇日，花时誰伴出城游。"]', '诗', 'shi', '', NULL, '寄張學士洎 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95aa7d67-4586-43af-ae6c-939e063eb174', '句', '句', '10182945-84a9-465f-a38f-31cc0162d01e', '唐', '["積靄沈諸壑，微陽在半峰。"]', '["積靄沈諸壑，微陽在半峰。"]', '诗', 'shi', '', NULL, '句 伍喬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7998713e-9c69-45f3-8ff0-4f71075ec528', '塞下曲 一', '塞下曲 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["邊頭能走馬，猨臂李將軍。","射虎羣胡伏，開弓絕塞聞。","海山諳向背，攻守別風雲。","只爲坑降罪，輕車未轉勳。"]', '["邊头能走马，猨臂李將軍。","射虎羣胡伏，开弓絕塞闻。","海山諳向背，攻守別风云。","只爲坑降罪，轻车未轉勳。"]', '诗', 'shi', '', NULL, '塞下曲 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4f9ad57-baa9-46d9-b5b4-afd8387fe3f2', '塞下曲 二', '塞下曲 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["望湖關下戰，雜虜喪全師。","鳥啄豺狼將，沙埋日月旗。","牛羊奔赤狄，部落散燕耆。","都護凌晨出，銘功瘞死屍。"]', '["望湖关下戰，杂虜喪全師。","鸟啄豺狼將，沙埋日月旗。","牛羊奔赤狄，部落散燕耆。","都護凌晨出，銘功瘞死屍。"]', '诗', 'shi', '', NULL, '塞下曲 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('583c83e5-adde-43cf-b506-cf121cab2702', '胡無人行', '胡無人行', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["十萬羽林兒，臨洮破郅支。","殺添胡地骨，降足漢營旗。","塞闊牛羊散，兵休帳幕移。","空流隴頭水，嗚咽向人悲。"]', '["十万羽林兒，臨洮破郅支。","殺添胡地骨，降足漢營旗。","塞闊牛羊散，兵休帳幕移。","空流隴头水，嗚咽向人悲。"]', '诗', 'shi', '', NULL, '胡無人行 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dc3008f-956b-4769-987a-6eea6c4a5772', '悲哉行', '悲哉行', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["中嶽仇先生，遺余餌松方。","服之一千日，肢體生異香。","步履如風旋，天涯不齎糧。","仍云爲地仙，不得朝虛皇。","狡兔有三穴，人生又何常。","悲哉二廉士，餓死於首陽。"]', '["中嶽仇先生，遺余餌松方。","服之一千日，肢體生異香。","步履如风旋，天涯不齎糧。","仍云爲地仙，不得朝虛皇。","狡兔有三穴，人生又何常。","悲哉二廉士，餓死於首陽。"]', '诗', 'shi', '', NULL, '悲哉行 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e71ad9-545c-4fc2-916c-452c9a7c9044', '塗山懷古', '塗山懷古', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["落拓書劍晚，清秋鷹正籠。","塗山間來上，敬愛如登龍。","覽古覺神王，翛然天地空。","東南更何有，一醉先王風。","惟昔放勳世，陰晦徹成洪。","皇圖化魚鱉，天道漂無蹤。","帝乃命舟檝，掇芳儒素中。","高陳九州力，百道驅歸東。","舊物復光明，洪爐再埏鎔。","經門不私子，足知天下公。","亮曰那並生，唐虞禪華蟲。","茲山朝萬國，一賦寰海同。","十載有區宇，秋豪皆帝功。","垂衣不驕德，子桀如何聾。","握髮聞禮賢，葺茅見卑宮。","凡夫色難事，神聖安能恭。","道隱三千年，遺芳播笙鏞。","當時執圭處，佳氣仍童童。","海嶼儼清廟，天人盛祇供。","玄恩及花木，丹讖名崆峒。","異代草澤臣，何由樹勳庸。","堯階未曾識，誰信平生忠。","恨不當際會，預爲執鞭僮。","勞歌下山去，懷德心無窮。"]', '["落拓书劍晚，清秋鷹正籠。","塗山间来上，敬愛如登龙。","覽古覺神王，翛然天地空。","东南更何有，一醉先王风。","惟昔放勳世，陰晦徹成洪。","皇圖化鱼鱉，天道漂無蹤。","帝乃命舟檝，掇芳儒素中。","高陳九州力，百道驱归东。","旧物复光明，洪爐再埏鎔。","經门不私子，足知天下公。","亮曰那並生，唐虞禪华蟲。","茲山朝万国，一賦寰海同。","十載有區宇，秋豪皆帝功。","垂衣不驕德，子桀如何聾。","握髮闻禮賢，葺茅见卑宮。","凡夫色难事，神聖安能恭。","道隐三千年，遺芳播笙鏞。","當时執圭处，佳氣仍童童。","海嶼儼清廟，天人盛祇供。","玄恩及花木，丹讖名崆峒。","異代草澤臣，何由樹勳庸。","堯階未曾識，誰信平生忠。","恨不當際會，預爲執鞭僮。","勞歌下山去，懷德心無窮。"]', '诗', 'shi', '', NULL, '塗山懷古 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9eb4794-629c-4a16-bf0a-df0a2fe122cc', '遊子吟', '游子吟', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["栖烏喜林曙，驚蓬傷歲闌。","關河三尺雪，何處是天山？","朔風無重衣，僕馬飢且寒。","慘慼別妻子，遲回出門難。","男兒值休明，豈是長泥蟠。","何者爲木偶，何人侍金鑾。","鬱鬱守貧賤，悠悠亦無端。","進不圖功名，退不處巖巒。","窮通在何日，光景如跳丸。","富貴苦不早，令人摧心肝。","誓期春之陽，一振摩霄翰。"]', '["栖烏喜林曙，驚蓬傷歲闌。","关河三尺雪，何处是天山？","朔风無重衣，僕马飢且寒。","慘慼別妻子，遲回出门难。","男兒值休明，豈是长泥蟠。","何者爲木偶，何人侍金鑾。","鬱鬱守貧賤，悠悠亦無端。","進不圖功名，退不处巖巒。","窮通在何日，光景如跳丸。","富貴苦不早，令人摧心肝。","誓期春之陽，一振摩霄翰。"]', '诗', 'shi', '', NULL, '遊子吟 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd11e3a-cbd2-4a8f-a783-14b1235efce9', '懷仙吟二首 一', '懷仙吟二首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["丹陵五牙客，昨日羅浮歸。","赤斧尋不得，煙霞空滿衣。","試於華陽問，果遇三茅知。","採藥向十洲，同行牧羊兒。","十洲隔八海，浩渺不可期。","留空雙白鶴，巢在長松枝。"]', '["丹陵五牙客，昨日羅浮归。","赤斧尋不得，煙霞空满衣。","試於华陽问，果遇三茅知。","採藥向十洲，同行牧羊兒。","十洲隔八海，浩渺不可期。","留空雙白鹤，巢在长松枝。"]', '诗', 'shi', '', NULL, '懷仙吟二首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93942fe1-3ef2-4b0b-ab0d-37321c495221', '懷仙吟二首 二', '懷仙吟二首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["雲溪古流水，春晚桃花香。","憶與我師別，片帆歸滄浪。","滄浪在何許，相思淚如雨。","黃鶴不復來，雲深難別處。","石渠泉泠泠，三見菖蒲生。","日夜勞夢魂，隨波注東溟。","空懷別時惠，長讀消魔經。"]', '["云溪古流水，春晚桃花香。","憶與我師別，片帆归滄浪。","滄浪在何許，相思泪如雨。","黄鹤不复来，云深难別处。","石渠泉泠泠，三见菖蒲生。","日夜勞梦魂，隨波注东溟。","空懷別时惠，长读消魔經。"]', '诗', 'shi', '', NULL, '懷仙吟二首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d086f658-6b6c-47c3-bbb7-52e0423bd1fb', '海昌望月', '海昌望月', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["何處無今夕，豈期在海頭。","賈客不愛月，嬋娟閑滄洲。","浩然傷歲華，獨望湖邊樓。","煙島青歷歷，藍田白悠悠。","誰無破鏡期，繄我信虛舟。","誰無桂枝念，繄我方摧輈。","始見彎環春，又逢團圓秋。","莫厭綾扇夕，百年多銀鉤。","今盤誰雕鐫，玉窟難冥搜。","重輪運時節，三五不自由。","疑拋雲上鍋，欲摟天邊毬。","孀居應寒冷，擣藥青冥愁。","兔子樹下蹲，蝦𢋙池中遊。","如何名金波，不共水東流。","天花辟膻腥，野雲無邊陬。","蚌蛤乘大運，含珠相對醻。","夜鵲思南鄉，露華清東甌。","百寶安可覰，老龍鎖深湫。","究究如情人，盜者即仇讎。","海涯上皎潔，九門更清幽。","亭亭勸金尊，夜久喘吳牛。","夷俗皆輕擲，北山思今遊。","鴈聲故鄉來，客淚墮南洲。","平生煙霞志，讀書覓封侯。","四海尚白身，豈無故鄉羞。","壈坎何足歎，壯如水中虬。","獵獵谷底蘭，搖搖波上鷗。","中途喪資斧，兩地生繁憂。","一杯太陰君，鷦鷯豈無求。","明日將片葉，三山東南浮。"]', '["何处無今夕，豈期在海头。","賈客不愛月，嬋娟闲滄洲。","浩然傷歲华，独望湖邊楼。","煙島青歷歷，藍田白悠悠。","誰無破镜期，繄我信虛舟。","誰無桂枝念，繄我方摧輈。","始见彎环春，又逢團圓秋。","莫厭綾扇夕，百年多銀鉤。","今盤誰雕鐫，玉窟难冥搜。","重輪運时節，三五不自由。","疑拋云上鍋，欲摟天邊毬。","孀居應寒冷，擣藥青冥愁。","兔子樹下蹲，蝦𢋙池中游。","如何名金波，不共水东流。","天花辟膻腥，野云無邊陬。","蚌蛤乘大運，含珠相对醻。","夜鵲思南乡，露华清东甌。","百寶安可覰，老龙鎖深湫。","究究如情人，盜者即仇讎。","海涯上皎潔，九门更清幽。","亭亭勸金尊，夜久喘吳牛。","夷俗皆轻擲，北山思今游。","鴈声故乡来，客泪墮南洲。","平生煙霞志，读书覓封侯。","四海尚白身，豈無故乡羞。","壈坎何足歎，壯如水中虬。","獵獵谷底蘭，搖搖波上鷗。","中途喪資斧，兩地生繁憂。","一杯太陰君，鷦鷯豈無求。","明日將片葉，三山东南浮。"]', '诗', 'shi', '', NULL, '海昌望月 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('019b5d9c-e3f9-4677-bb1a-4b3fe4fd566f', '蒲門戍觀海作', '蒲门戍观海作', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["廓落溟漲曉，蒲門鬱蒼蒼。","登樓禮東君，旭日生扶桑。","毫釐見蓬瀛，含吐金銀光。","草木露未晞，蜃樓氣若藏。","欲遊蟠桃國，慮涉魑魅鄉。","徐市惑秦朝，何人在巖廊。","惜哉千童子，葬骨於眇茫。","恭聞槎客言，東池接天潢。","即此聘牛女，曰祈長壽方。","靈津水清淺，余亦慕脩航。"]', '["廓落溟漲晓，蒲门鬱蒼蒼。","登楼禮东君，旭日生扶桑。","毫釐见蓬瀛，含吐金銀光。","草木露未晞，蜃楼氣若藏。","欲游蟠桃国，慮涉魑魅乡。","徐市惑秦朝，何人在巖廊。","惜哉千童子，葬骨於眇茫。","恭闻槎客言，东池接天潢。","即此聘牛女，曰祈长壽方。","靈津水清淺，余亦慕脩航。"]', '诗', 'shi', '', NULL, '蒲門戍觀海作 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a5a849-e231-4a45-bbf2-7c9a0f2fb800', '番禺道中作', '番禺道中作', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["博羅程遠近，海塞愁先入。","瘴雨出虹蝀，蠻江渡山急。","常聞島夷俗，犀象滿城邑。","鴈至草猶春，潮迴檣半濕。","丹丘鳳皇隱，水廟蛟龍集。","何處樹能言，幾鄉珠是泣。","千年趙佗國，霸氣委原隰。","齷齪笑終軍，長纓禍先及。"]', '["博羅程远近，海塞愁先入。","瘴雨出虹蝀，蠻江渡山急。","常闻島夷俗，犀象满城邑。","鴈至草猶春，潮迴檣半濕。","丹丘鳳皇隐，水廟蛟龙集。","何处樹能言，幾乡珠是泣。","千年趙佗国，霸氣委原隰。","齷齪笑終軍，长纓禍先及。"]', '诗', 'shi', '', NULL, '番禺道中作 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648892e4-0445-43b7-875c-2a74ac94f4fe', '贈江西周大夫', '贈江西周大夫', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["否極生大賢，九元降靈氣。","獨立正始風，蔚然中興瑞。","淵倫照三古，磊落涵涇渭。","真貌月懸秋，雄詞雷出地。","具瞻先皇寵，欲踐東華貴。","咫尺時不來，千秋鼎湖淚。","因分三輔職，進領南平位。","報政黃霸慙，提兵呂蒙醉。","歲星臨斗牛，水國嘉祥至。","不獨蒼生蘇，仍兼六騶喜。","恭聞廟堂畧，欲斷匈奴臂。","剗釋自宸衷，平戍在連帥。","時康簪笏宂，世梗忠良議。","丘壑非無人，松香有私志。","三朝倚天劍，十萬浮雲騎。","可使河曲清，羣公信兒戲。","滄溟用謙德，百谷走童稚。","禦衆付深人，參籌須偉器。","他年蓬蓽賤，願附鵷鸞翅。"]', '["否極生大賢，九元降靈氣。","独立正始风，蔚然中兴瑞。","淵倫照三古，磊落涵涇渭。","真貌月懸秋，雄词雷出地。","具瞻先皇寵，欲踐东华貴。","咫尺时不来，千秋鼎湖泪。","因分三輔職，進領南平位。","報政黄霸慙，提兵呂蒙醉。","歲星臨斗牛，水国嘉祥至。","不独蒼生蘇，仍兼六騶喜。","恭闻廟堂畧，欲斷匈奴臂。","剗釋自宸衷，平戍在連帥。","时康簪笏宂，世梗忠良議。","丘壑非無人，松香有私志。","三朝倚天劍，十万浮云騎。","可使河曲清，羣公信兒戲。","滄溟用謙德，百谷走童稚。","禦衆付深人，參籌須偉器。","他年蓬蓽賤，願附鵷鸾翅。"]', '诗', 'shi', '', NULL, '贈江西周大夫 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbed85c7-6651-4656-9717-439f3e143008', '旅次銅山途中先寄溫州韓使君', '旅次銅山途中先寄溫州韓使君', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["亂山滄海曲，中有橫陽道。","束馬過銅梁，苕華坐堪老。","鳩鳴高崖裂，熊鬬深樹倒。","絕壑無坤維，重林失蒼昊。","躋攀寡儔侶，扶接念輿皁。","俛仰慄嵌空，無因掇靈草。","梯窮聞戍鼓，魂續賴丘禱。","敞豁天地歸，縈紆村落好。","悠悠思蔣徑，擾擾愧商皓。","馳想永嘉侯，應傷此懷抱。"]', '["亂山滄海曲，中有橫陽道。","束马過銅梁，苕华坐堪老。","鳩鳴高崖裂，熊鬬深樹倒。","絕壑無坤維，重林失蒼昊。","躋攀寡儔侶，扶接念輿皁。","俛仰慄嵌空，無因掇靈草。","梯窮闻戍鼓，魂續賴丘禱。","敞豁天地归，縈紆村落好。","悠悠思蔣徑，擾擾愧商皓。","驰想永嘉侯，應傷此懷抱。"]', '诗', 'shi', '', NULL, '旅次銅山途中先寄溫州韓使君 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048c5e95-a0ed-4bd8-a606-22b5583063eb', '種蘭', '種蘭', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["種蘭幽谷底，四遠聞馨香。","春風長養深，枝葉趁人長。","智水潤其根，仁鋤護其芳。","蒿藜不生地，惡鳥弓已藏。","椒桂夾四隅，茅茨居中央。","左鄰桃花塢，右接蓮子塘。","一月薰手足，兩月薰衣裳。","三月薰肌骨，四月薰心腸。","幽人飢如何，採蘭充餱糧。","幽人渴如何，醞蘭爲酒漿。","地無青苗租，白日如散王。","不嘗仙人藥，端坐紅霞房。","日夕望美人，佩花正煌煌。","美人久不來，佩花徒生光。","刈穫及葳蕤，無令見雪霜。","清芬信神鬼，一葉豈可忘。","舉頭愧青天，鼓腹詠時康。","下有賢公卿，上有聖明王。","無階荅風雨，願獻蘭一筐。"]', '["種蘭幽谷底，四远闻馨香。","春风长養深，枝葉趁人长。","智水潤其根，仁鋤護其芳。","蒿藜不生地，惡鸟弓已藏。","椒桂夾四隅，茅茨居中央。","左鄰桃花塢，右接蓮子塘。","一月薰手足，兩月薰衣裳。","三月薰肌骨，四月薰心腸。","幽人飢如何，採蘭充餱糧。","幽人渴如何，醞蘭爲酒漿。","地無青苗租，白日如散王。","不嘗仙人藥，端坐紅霞房。","日夕望美人，佩花正煌煌。","美人久不来，佩花徒生光。","刈穫及葳蕤，無令见雪霜。","清芬信神鬼，一葉豈可忘。","舉头愧青天，鼓腹詠时康。","下有賢公卿，上有聖明王。","無階荅风雨，願獻蘭一筐。"]', '诗', 'shi', '', NULL, '種蘭 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c97e5b6d-627f-437a-8306-fb8fdb5daa00', '草木言', '草木言', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["何生我蒼蒼，何育我黃黃。","草木無知識，幸君同三光。","始自受姓名，葳蕤立衣裳。","山河既分麗，齊首乳青陽。","甘辛各有榮，好醜不相防。","常憂刀斧劫，竊慕仁壽鄉。","願天雨無暴，怨地風無狂。","雨足因衰憊，風多因夭傷。","在山不爲桂，徒辱君高岡。","在水不爲蓮，徒占君深塘。","勿輕培塿阜，或有奇棟梁。","勿輕蒙朧澤，或有奇馨香。","涓毫可蔍差，朝菌壽爲長。","擁腫若無取，大椿命爲傷。","婆娑不材生，苒苒向秋荒。","幸遭薰風日，有得皆簸揚。","所愧雨露恩，願效幽微芳。","希君頻採擇，勿使枯雪霜。"]', '["何生我蒼蒼，何育我黄黄。","草木無知識，幸君同三光。","始自受姓名，葳蕤立衣裳。","山河既分丽，齊首乳青陽。","甘辛各有榮，好醜不相防。","常憂刀斧劫，竊慕仁壽乡。","願天雨無暴，怨地风無狂。","雨足因衰憊，风多因夭傷。","在山不爲桂，徒辱君高岡。","在水不爲蓮，徒占君深塘。","勿轻培塿阜，或有奇棟梁。","勿轻蒙朧澤，或有奇馨香。","涓毫可蔍差，朝菌壽爲长。","擁腫若無取，大椿命爲傷。","婆娑不材生，苒苒向秋荒。","幸遭薰风日，有得皆簸揚。","所愧雨露恩，願效幽微芳。","希君頻採擇，勿使枯雪霜。"]', '诗', 'shi', '', NULL, '草木言 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476c46a7-0017-4e5e-8fb0-f181122b0a85', '題僧院紫竹', '題僧院紫竹', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["喜遊蛟井寺，復見炎州竹。","杳靄萬丈間，嘯風清獨速。","江南正霜霰，吐秀弄顓頊。","似瑞驚堅貞，如魔試金粟。","笋非孝子泣，文異湘靈哭。","金碧誰與鄰，蕭森自成族。","新聞赤帝種，子落毛人谷。","遠祖賜鷦鵬，遺芳遍南陸。","對煙蘇麻醜，夾澗篔簹伏。","美譽動丹青，瓌姿豔秦蜀。","因緣鹿苑識，想像虵丘斸。","幾葉別黃茅，何年依白足。","龍樹蟄一花，砌瑤掃雲屋。","色靜曼仙花，名高給孤獨。","青蔥太子樹，灑落觀音目。","法雨每霑濡，玉毫時照燭。","離居鸞節變，住冷金顏縮。","豈念葛陂榮，幸無祖父辱。","光搖水精串，影送蓮花軸。","江鶩日相尋，野鶚時寄宿。","幽香入茶竈，靜翠直碁局。","肯羨垣上蒿，自多籬下菊。","從來道生一，況伴龜藏六。","棲託詎星迴，檀欒已雲矗。","霞杯傳縹葉，羽管吹紫玉。","久絕釣竿歌，聊裁竹枝曲。","媿生黃金地，千秋爲師綠。"]', '["喜游蛟井寺，复见炎州竹。","杳靄万丈间，嘯风清独速。","江南正霜霰，吐秀弄顓頊。","似瑞驚堅貞，如魔試金粟。","笋非孝子泣，文異湘靈哭。","金碧誰與鄰，蕭森自成族。","新闻赤帝種，子落毛人谷。","远祖賜鷦鵬，遺芳遍南陸。","对煙蘇麻醜，夾澗篔簹伏。","美譽动丹青，瓌姿豔秦蜀。","因緣鹿苑識，想像虵丘斸。","幾葉別黄茅，何年依白足。","龙樹蟄一花，砌瑤掃云屋。","色静曼仙花，名高給孤独。","青蔥太子樹，灑落观音目。","法雨每霑濡，玉毫时照燭。","離居鸾節变，住冷金顏縮。","豈念葛陂榮，幸無祖父辱。","光搖水精串，影送蓮花軸。","江鶩日相尋，野鶚时寄宿。","幽香入茶竈，静翠直碁局。","肯羨垣上蒿，自多籬下菊。","從来道生一，況伴龟藏六。","棲託詎星迴，檀欒已云矗。","霞杯傳縹葉，羽管吹紫玉。","久絕釣竿歌，聊裁竹枝曲。","媿生黄金地，千秋爲師綠。"]', '诗', 'shi', '', NULL, '題僧院紫竹 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a167b83-dfad-444e-aa45-5bf87970c26f', '早發始興', '早發始兴', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["雲裏山已曙，舟中火初爇。","綠浦待行橈，玄猨催落月。","沿流信多美，況復秋風發。","挂席借前期，晨雞莫嘲异常。"]', '["云裏山已曙，舟中火初爇。","綠浦待行橈，玄猨催落月。","沿流信多美，況复秋风發。","挂席借前期，晨雞莫嘲异常。"]', '诗', 'shi', '', NULL, '早發始興 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09cdbdb6-a239-4e77-ad7a-32ae4e670d71', '寄元孚道人', '寄元孚道人', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["梵宇章句客，佩蘭三十年。","長乘碧雲馬，時策翰林鞭。","曩事五岳遊，金衣曳祥煙。","高攀桐君手，左倚鸑鷟肩。","哭玉秋雨中，摘星春風前。","橫輈截洪偃，憑几見廣宣。","爾來寤華胥，石壁孤雲眠。","龍降始得偈，龜老方巢蓮。","內殿無文僧，驅虞誰能牽。","因之問楚水，弔屈幾潺湲。"]', '["梵宇章句客，佩蘭三十年。","长乘碧云马，时策翰林鞭。","曩事五岳游，金衣曳祥煙。","高攀桐君手，左倚鸑鷟肩。","哭玉秋雨中，摘星春风前。","橫輈截洪偃，憑几见廣宣。","爾来寤华胥，石壁孤云眠。","龙降始得偈，龟老方巢蓮。","內殿無文僧，驱虞誰能牽。","因之问楚水，弔屈幾潺湲。"]', '诗', 'shi', '', NULL, '寄元孚道人 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0d24ebf-a86c-4b4a-b7df-064d65a758d3', '和西江李助副使早登開元寺閣', '和西江李助副使早登开元寺閣', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["虛豁登寶閣，三休極層構。","獨立天地間，煙雲滿襟袖。","鰲荒初落日，劍野呈綺繡。","秋檻祝融微，陰軒九江湊。","拂簷皇姑舍，錯落白榆秀。","倚砌天竺祠，蛟龍蟠古甃。","翛然觀六合，一指齊宇宙。","書劍忽若□，青雲日方晝。","南朝空蒼莽，楚澤稀耕耨。","萬事溺頹波，一航安可涭。","徒云寄麟泣，六五終難就。","資斧念餘生，湖光隱圭竇。","早聞羣黃鶴，飄舉此江岫。","陵谷空靄然，人樵已雛𪆪。","燕宮豸冠客，憑覽發清奏。","珠玉難嗣音，摐轅愧孤陋。"]', '["虛豁登寶閣，三休極層構。","独立天地间，煙云满襟袖。","鰲荒初落日，劍野呈綺繡。","秋檻祝融微，陰軒九江湊。","拂簷皇姑舍，錯落白榆秀。","倚砌天竺祠，蛟龙蟠古甃。","翛然观六合，一指齊宇宙。","书劍忽若□，青云日方晝。","南朝空蒼莽，楚澤稀耕耨。","万事溺頹波，一航安可涭。","徒云寄麟泣，六五終难就。","資斧念餘生，湖光隐圭竇。","早闻羣黄鹤，飄舉此江岫。","陵谷空靄然，人樵已雛𪆪。","燕宮豸冠客，憑覽發清奏。","珠玉难嗣音，摐轅愧孤陋。"]', '诗', 'shi', '', NULL, '和西江李助副使早登開元寺閣 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f862ecfb-744f-4c1b-bc6b-6205f0abf0d0', '將歸鍾陵留贈南海李尚書', '將归鍾陵留贈南海李尚书', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["楚國有田舍，炎州長夢歸。","懷恩似秋燕，屢遶玉堂飛。","越酒豈不甘，海魚寧無肥。","山裘醉歌舞，事與初心違。","曄曄文昌公，英靈世間稀。","長江浩無際，龍蜃皆歸依。","賤子感一言，草茅發光輝。","從來雞鳧質，得假鳳皇威。","常欲討玄珠，青雲報巍巍。","龍門竟多故，雙淚別旍旂。"]', '["楚国有田舍，炎州长梦归。","懷恩似秋燕，屢遶玉堂飞。","越酒豈不甘，海鱼寧無肥。","山裘醉歌舞，事與初心違。","曄曄文昌公，英靈世间稀。","长江浩無際，龙蜃皆归依。","賤子感一言，草茅發光輝。","從来雞鳧質，得假鳳皇威。","常欲討玄珠，青云報巍巍。","龙门竟多故，雙泪別旍旂。"]', '诗', 'shi', '', NULL, '將歸鍾陵留贈南海李尚書 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330789f9-0bba-41a8-b252-b393eb087e30', '宿島徑夷山舍', '宿島徑夷山舍', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["百里遵鳥徑，蓬征信邅迴。","暝依漁樵宿，似過黃金臺。","缺齧心未理，寥寥夜猨哀。","山深石牀冷，海近腥氣來。","主人意不淺，屢獻流霞杯。","對月撫長劍，愁襟紛莫開。","九衢平如水，胡爲涉崔崽。","一飯未遑飽，鵬圖信悠哉。","山濤謔細君，吾豈厭蓬萊。","明發又驅馬，客思一裴回。"]', '["百里遵鸟徑，蓬征信邅迴。","暝依漁樵宿，似過黄金台。","缺齧心未理，寥寥夜猨哀。","山深石牀冷，海近腥氣来。","主人意不淺，屢獻流霞杯。","对月撫长劍，愁襟紛莫开。","九衢平如水，胡爲涉崔崽。","一飯未遑飽，鵬圖信悠哉。","山濤謔細君，吾豈厭蓬萊。","明發又驱马，客思一裴回。"]', '诗', 'shi', '', NULL, '宿島徑夷山舍 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7cbadbd-992a-4775-8904-704dbce0472c', '避世翁', '避世翁', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["海上一蓑笠，終年垂釣絲。","滄洲有深意，冠盡何由知。","直鉤不營魚，蝸室無妻兒。","渴飲寒泉水，飢飡紫朮芝。","鶴髮披兩肩，高懷如澄陂。","曾聞仙老言，云是古鴟夷。","石竇閟雷雨，金潭養蛟螭。","乘槎上玉津，騎鹿遊峨嵋。","以人爲語默，與世爲雄雌。","茲焉乃磻溪，豹變應須時。","自古隱淪客，無非王者師。"]', '["海上一蓑笠，終年垂釣絲。","滄洲有深意，冠尽何由知。","直鉤不營鱼，蝸室無妻兒。","渴饮寒泉水，飢飡紫朮芝。","鹤髮披兩肩，高懷如澄陂。","曾闻仙老言，云是古鴟夷。","石竇閟雷雨，金潭養蛟螭。","乘槎上玉津，騎鹿游峨嵋。","以人爲語默，與世爲雄雌。","茲焉乃磻溪，豹变應須时。","自古隐淪客，無非王者師。"]', '诗', 'shi', '', NULL, '避世翁 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4536fdf-0f9c-4143-a815-799ddbea5616', '冬夜吟', '冬夜吟', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["黑夜天寒愁散玉，東皇海上張仙燭。","侯家歌舞按梨園，石氏賓寮醉金谷。","魯家襜褕闇披水，雪花燈下甘垂翅。","散帙高編折桂枝，披紗密甃青雲地。","霜白溪松轉斜盡，銅龍喚曙咽聲細。","八埏螻蟻厭寒栖，早晚青旗引春帝。","展轉城烏啼紫天，曈曚千騎衙樓前。"]', '["黑夜天寒愁散玉，东皇海上張仙燭。","侯家歌舞按梨园，石氏賓寮醉金谷。","魯家襜褕闇披水，雪花灯下甘垂翅。","散帙高編折桂枝，披紗密甃青云地。","霜白溪松轉斜尽，銅龙喚曙咽声細。","八埏螻蟻厭寒栖，早晚青旗引春帝。","展轉城烏啼紫天，曈曚千騎衙楼前。"]', '诗', 'shi', '', NULL, '冬夜吟 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bcf0682-f605-4338-aeb8-8a7b8fbb3ea7', '西川座上聽金五雲唱歌', '西川座上听金五云唱歌', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["蜀王殿上華筵開，五雲歌從天上來。","滿堂羅綺悄無語，喉音止駐雲裴回。","管弦金石還依轉，不隨歌出靈和殿。","白雲飄颻席上聞，貫珠歷歷聲中見。","舊樣釵箆淺澹衣，元和梳洗青黛眉。","低叢小鬢膩䰀鬌，碧牙鏤掌山參差。","曲終暫起更衣過，還向南行座頭坐。","低眉欲語謝貴侯，檀臉雙雙淚穿破。","自言本是宮中嬪，武皇改號承恩新。","中丞御史不足比，水殿一聲愁殺人。","武皇鑄鼎登真籙，嬪御蒙恩免幽辱。","茂陵弓劍不得親，嫁與卑官到西蜀。","卑官到官年未周，堂衡祿罷東西遊。","蜀江水急駐不得，復此萍蓬二十秋。","今朝得侍王侯宴，不覺途中妾身賤。","願持巵酒更唱歌，歌是伊州第三遍。","唱著右丞征戍詞，更聞閨月添相思。","如今聲韻尚如在，何況宮中年少時。","五雲處處可憐許，明朝道向襃中去。","須臾宴罷各東西，雨散雲飛莫知處。"]', '["蜀王殿上华筵开，五云歌從天上来。","满堂羅綺悄無語，喉音止駐云裴回。","管弦金石還依轉，不隨歌出靈和殿。","白云飄颻席上闻，貫珠歷歷声中见。","旧樣釵箆淺澹衣，元和梳洗青黛眉。","低叢小鬢膩䰀鬌，碧牙鏤掌山參差。","曲終暫起更衣過，還向南行座头坐。","低眉欲語謝貴侯，檀臉雙雙泪穿破。","自言本是宮中嬪，武皇改號承恩新。","中丞御史不足比，水殿一声愁殺人。","武皇鑄鼎登真籙，嬪御蒙恩免幽辱。","茂陵弓劍不得親，嫁與卑官到西蜀。","卑官到官年未周，堂衡祿罷东西游。","蜀江水急駐不得，复此萍蓬二十秋。","今朝得侍王侯宴，不覺途中妾身賤。","願持巵酒更唱歌，歌是伊州第三遍。","唱著右丞征戍词，更闻閨月添相思。","如今声韻尚如在，何況宮中年少时。","五云处处可怜許，明朝道向襃中去。","須臾宴罷各东西，雨散云飞莫知处。"]', '诗', 'shi', '', NULL, '西川座上聽金五雲唱歌 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974f6f40-7fe3-443d-afde-d7bc58518c4d', '飛龍引', '飞龙引', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["有熊之君好神仙，飡霞鍊石三千年。","一旦黃龍下九天，騎龍枿枿昇紫煙。","萬姓攀髯髯墮地，啼呼弓劍飄寒水。","紫鸞八九墮玉笙，金鏡空留照魑魅。","羽幢䙰褷銀漢秋，六宮望斷芙蓉愁。","應龍下揮中園笑，泓泓水遶青苔洲。","瑞風颯遝天光淺，瑤闕峨峨橫露苑。","沆瀣樓頭紫鳳歌，三株樹下青牛飯。","鴻朧九闕相玉皇，鈞天樂引金華郎。","散花童子鶴衣短，投壺姹女蛾眉長。","彤庭侍宴瑤池席，老兔春高桂宮白。","蓬萊下國賜分珪，阿母金桃容小摘。","仙流萬緘蟲篆春，三十六洞交風雲。","千年小兆一蟬蛻，丹臺職亞扶桑君。","金烏試浴青門水，下界蜉蝣幾迴死。"]', '["有熊之君好神仙，飡霞鍊石三千年。","一旦黄龙下九天，騎龙枿枿昇紫煙。","万姓攀髯髯墮地，啼呼弓劍飄寒水。","紫鸾八九墮玉笙，金镜空留照魑魅。","羽幢䙰褷銀漢秋，六宮望斷芙蓉愁。","應龙下揮中园笑，泓泓水遶青苔洲。","瑞风颯遝天光淺，瑤闕峨峨橫露苑。","沆瀣楼头紫鳳歌，三株樹下青牛飯。","鴻朧九闕相玉皇，鈞天乐引金华郎。","散花童子鹤衣短，投壺姹女蛾眉长。","彤庭侍宴瑤池席，老兔春高桂宮白。","蓬萊下国賜分珪，阿母金桃容小摘。","仙流万緘蟲篆春，三十六洞交风云。","千年小兆一蟬蛻，丹台職亞扶桑君。","金烏試浴青门水，下界蜉蝣幾迴死。"]', '诗', 'shi', '', NULL, '飛龍引 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4206d8e7-8082-4dbf-81bd-f2a24ee5ff65', '謫仙詞', '謫仙词', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["牧龍丈人病高秋，羣童擊節星漢愁。","瑤臺鳳輦不勝恨，太古一聲龍白頭。","玉氣蘭光久摧折，上清雞犬音書絕。","蜺旌失手遠於天，三島空雲對秋月。","人間磊磊浮漚客，鸑鷟蜻蜓飛自隔。","不應冠蓋逐黃埃，長夢真君舊恩澤。"]', '["牧龙丈人病高秋，羣童擊節星漢愁。","瑤台鳳輦不勝恨，太古一声龙白头。","玉氣蘭光久摧折，上清雞犬音书絕。","蜺旌失手远於天，三島空云对秋月。","人间磊磊浮漚客，鸑鷟蜻蜓飞自隔。","不應冠蓋逐黄埃，长梦真君旧恩澤。"]', '诗', 'shi', '', NULL, '謫仙詞 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c96eac3-db45-4401-b970-5a705cd7ccf1', '步虛引', '步虛引', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["小隱山人十洲客，莓苔爲衣雙耳白。","青編爲我忽降書，暮雨虹蜺一千尺。","赤城門閉六丁直，曉日已燒東海色。","朝天半夜聞玉雞，星斗離離礙龍翼。"]', '["小隐山人十洲客，莓苔爲衣雙耳白。","青編爲我忽降书，暮雨虹蜺一千尺。","赤城门閉六丁直，晓日已燒东海色。","朝天半夜闻玉雞，星斗離離礙龙翼。"]', '诗', 'shi', '', NULL, '步虛引 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fbb78a0-756c-4dc0-9737-0e7ca0b3b23b', '獨搖手', '独搖手', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["漢宮新燕矜蛾眉，春臺豔妝蓮一枝。","迎春侍宴瑤華池，游龍七盤嬌欲飛。","冶袖鶯鸞拂朝曦，摩煙褭雪金碧遺。","愁鴻連翾蠶曳絲，颯遝明珠掌中移。","仙人龍鳳雲雨吹，朝哀暮愁引啞吚。","鴛鴦翡翠承宴私，南山一笑君無辭。","仙蛾泣月清露垂，六宮燒燭愁風欷。"]', '["漢宮新燕矜蛾眉，春台豔妝蓮一枝。","迎春侍宴瑤华池，游龙七盤嬌欲飞。","冶袖鶯鸾拂朝曦，摩煙褭雪金碧遺。","愁鴻連翾蠶曳絲，颯遝明珠掌中移。","仙人龙鳳云雨吹，朝哀暮愁引啞吚。","鴛鴦翡翠承宴私，南山一笑君無辞。","仙蛾泣月清露垂，六宮燒燭愁风欷。"]', '诗', 'shi', '', NULL, '獨搖手 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b0950e-f1b5-4df6-8bb5-f85d3b225ba9', '空城雀', '空城雀', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["古城濛濛花覆水，昔日住人今住鬼。","野雀荒臺遺子孫，千年飲啄枯桑根。","不隨海燕栢梁去，應無玉環銜報恩。","近村紅栗香壓枝，嗷嗷黃口訴朝飢。","生來未見鳳皇語，欲飛常怕蜘蛛絲。","斷腸四隅天四絕，清泉綠蒿無恐疑。"]', '["古城濛濛花覆水，昔日住人今住鬼。","野雀荒台遺子孫，千年饮啄枯桑根。","不隨海燕栢梁去，應無玉环銜報恩。","近村紅栗香壓枝，嗷嗷黄口訴朝飢。","生来未见鳳皇語，欲飞常怕蜘蛛絲。","斷腸四隅天四絕，清泉綠蒿無恐疑。"]', '诗', 'shi', '', NULL, '空城雀 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14b13d2d-52e5-4bd5-81b8-bfbc66d473c1', '雞鳴曲', '雞鳴曲', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["雞聲春曉上林中，一聲驚落蝦蟆宮。","二聲喚破枕邊夢，三聲行人煙海紅。","平旦慵將百雛語，蓬鬆錦繡當陽處。","媿君飲食長相呼，爲君晝鳴下高樹。"]', '["雞声春晓上林中，一声驚落蝦蟆宮。","二声喚破枕邊梦，三声行人煙海紅。","平旦慵將百雛語，蓬鬆錦繡當陽处。","媿君饮食长相呼，爲君晝鳴下高樹。"]', '诗', 'shi', '', NULL, '雞鳴曲 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ebe2384-902c-4ca0-8b57-9be9810a3ee8', '小笛弄', '小笛弄', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["一尺玲瓏握中翠，僊娥月浦呼龍子。","五夜流珠粲夢卿，九青鸞倚洪崖醉。","丹穴飢兒笑風雨，媧皇碧玉星星語。","蛇蝎愁聞骨髓寒，江山恨老眠秋霧。","綺席鴛鴦冷朱翠，星流露泫誰驅使。","江南一曲罷伶倫，芙蓉水殿春風起。"]', '["一尺玲瓏握中翠，僊娥月浦呼龙子。","五夜流珠粲梦卿，九青鸾倚洪崖醉。","丹穴飢兒笑风雨，媧皇碧玉星星語。","蛇蝎愁闻骨髓寒，江山恨老眠秋霧。","綺席鴛鴦冷朱翠，星流露泫誰驱使。","江南一曲罷伶倫，芙蓉水殿春风起。"]', '诗', 'shi', '', NULL, '小笛弄 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5e8694b-fcaa-405b-9aee-7f349acb85ba', '將進酒', '將進酒', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["金尊莫倚青春健，齷齪浮生如走電。","琴瑟盤傾從世珠，黃泥局瀉流年箭。","麻姑爪禿瞳子昏，東皇肉角生魚鱗。","靈鼇柱骨半枯朽，驪龍德悔愁耕人。","周孔蓍龜久淪沒，黃蒿誰認賢愚骨。","兔苑詞才去不還，蘭亭水石空明月。","姮娥弄簫香雨收，江濱迸瑟魚龍愁。","靈芝九折楚蓮醉，翾風一歎梁庭秋。","醁亞蠻觥奉君壽，玉山三獻春紅透。","銀鴨金鵝言待誰，隋家嶽瀆皇家有。","珊瑚座上凌香雲，鳳𦢙龍炙猩猩脣。","芝蘭此日不傾倒，南山白石皆賢人。","文康調笑麒麟起，一曲飛龍壽天地。"]', '["金尊莫倚青春健，齷齪浮生如走電。","琴瑟盤傾從世珠，黄泥局瀉流年箭。","麻姑爪禿瞳子昏，东皇肉角生鱼鱗。","靈鼇柱骨半枯朽，驪龙德悔愁耕人。","周孔蓍龟久淪沒，黄蒿誰認賢愚骨。","兔苑词才去不還，蘭亭水石空明月。","姮娥弄簫香雨收，江濱迸瑟鱼龙愁。","靈芝九折楚蓮醉，翾风一歎梁庭秋。","醁亞蠻觥奉君壽，玉山三獻春紅透。","銀鴨金鵝言待誰，隋家嶽瀆皇家有。","珊瑚座上凌香云，鳳𦢙龙炙猩猩脣。","芝蘭此日不傾倒，南山白石皆賢人。","文康調笑麒麟起，一曲飞龙壽天地。"]', '诗', 'shi', '', NULL, '將進酒 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27fbe408-088e-4920-9d5f-f2299cf6e406', '錢塘對酒曲', '錢塘对酒曲', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["風天鴈悲西陵愁，使君紅旗弄濤頭。","東海神魚騎未得，江天大笑閑悠悠。","嵯峨吳山莫誇碧，河陽經年一宵白。","南州彩鳳爲君生，古獄愁蛇待恩澤。","三清羽童來何遲，十二玉樓胡蝶飛。","炎荒翡翠九門去，遼東白鶴無歸期。","鴟夷公子休悲悄，六鼇如鏡天始老。","尊前事去月團圓，琥珀無情憶蘇小。"]', '["风天鴈悲西陵愁，使君紅旗弄濤头。","东海神鱼騎未得，江天大笑闲悠悠。","嵯峨吳山莫誇碧，河陽經年一宵白。","南州彩鳳爲君生，古獄愁蛇待恩澤。","三清羽童来何遲，十二玉楼胡蝶飞。","炎荒翡翠九门去，遼东白鹤無归期。","鴟夷公子休悲悄，六鼇如镜天始老。","尊前事去月團圓，琥珀無情憶蘇小。"]', '诗', 'shi', '', NULL, '錢塘對酒曲 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70033607-8695-4ddf-8415-95e397a912a1', '巫山高', '巫山高', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["玉峰青雲十二枝，金母和雲賜瑤姬。","花宮磊砢楚宮外，列仙八面星斗垂。","秀色無雙怨三峽，春風幾夢襄王獵。","青鸞不在嬾吹簫，斑竹題詩寄江妾。","飄颻絲散巴子天，苔裳玉轡紅霞幡。","歸時白帝掩青瑣，瓊枝草草遺湘煙。"]', '["玉峰青云十二枝，金母和云賜瑤姬。","花宮磊砢楚宮外，列仙八面星斗垂。","秀色無雙怨三峽，春风幾梦襄王獵。","青鸾不在嬾吹簫，斑竹題诗寄江妾。","飄颻絲散巴子天，苔裳玉轡紅霞幡。","归时白帝掩青瑣，瓊枝草草遺湘煙。"]', '诗', 'shi', '', NULL, '巫山高 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f81e2fb-0bcb-4365-9d36-999534046f0c', '贈別離', '贈別離', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["碧玉飛天星墜地，玉劍分風交合水。","楊柳聽歌莫向隅，雞鳴一石留髠醉。","蹄輪送客溝水東，月娥揮手崦嵫峰。","蠻天列嶂儼相待，風官掃道迎遊龍。","天姥翦霞鋪曉空，漴漴大帝開明宮。","文鯨掉尾四海通，分明瀑布收靈桐。","山妖水魅騎旋風，魘夢齧魂黃瘴中。","借君郎鑒入崆峒，靈光草照閑花紅。"]', '["碧玉飞天星墜地，玉劍分风交合水。","楊柳听歌莫向隅，雞鳴一石留髠醉。","蹄輪送客溝水东，月娥揮手崦嵫峰。","蠻天列嶂儼相待，风官掃道迎游龙。","天姥翦霞鋪晓空，漴漴大帝开明宮。","文鯨掉尾四海通，分明瀑布收靈桐。","山妖水魅騎旋风，魘梦齧魂黄瘴中。","借君郎鑒入崆峒，靈光草照闲花紅。"]', '诗', 'shi', '', NULL, '贈別離 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe49f210-ed7f-439c-a8df-756ba2227f9d', '關山月', '关山月', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["昔年嫖姚護羌月，今照嫖姚雙鬢雪。","青塚曾無尺寸歸，錦書多記窮荒骨。","百戰金瘡體沙磧，鄉心一片懸秋碧。","漢城應期破鏡時，胡塵萬里嬋娟隔。","度磧衝雲朔風起，邊笳欲晚生青珥。","隴上橫吹霜色刀，何年斷得匈奴臂。"]', '["昔年嫖姚護羌月，今照嫖姚雙鬢雪。","青塚曾無尺寸归，錦书多記窮荒骨。","百戰金瘡體沙磧，乡心一片懸秋碧。","漢城應期破镜时，胡塵万里嬋娟隔。","度磧衝云朔风起，邊笳欲晚生青珥。","隴上橫吹霜色刀，何年斷得匈奴臂。"]', '诗', 'shi', '', NULL, '關山月 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6feada2f-0a48-43fd-a7d9-7fb596c168ac', '殿前生桂樹', '殿前生桂樹', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["僊娥玉宮秋夜明，桂枝拂檻參差瓊。","香風下天漏丁丁，牛渚翠梁橫淺清羽帳不眠恨吹笙。","棲烏暗驚僊子落，步月鬃雲墮金雀。","蕙樓涼簟翠波空，銀縷香寒鳳皇薄。","東海即爲郎斟酌，綺疏長懸七星杓。"]', '["僊娥玉宮秋夜明，桂枝拂檻參差瓊。","香风下天漏丁丁，牛渚翠梁橫淺清羽帳不眠恨吹笙。","棲烏暗驚僊子落，步月鬃云墮金雀。","蕙楼涼簟翠波空，銀縷香寒鳳皇薄。","东海即爲郎斟酌，綺疏长懸七星杓。"]', '诗', 'shi', '', NULL, '殿前生桂樹 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc9f6be9-9e5a-4d3d-ad56-c238bfadf182', '古鏡篇', '古镜篇', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["紫皇玉鏡蟾蜍字，墮地千年光不死。","發匣身沈古井寒，懸臺日照愁成水。","海戶山窗幾梳綰，菱花開落何人見。","野老曾耕太白星，神狐夜哭秋天片。","下國青銅旋磨滅，迴鸞萬影成枯骨。","會待搏風雨泬寥，長恐莓苔蝕明月。"]', '["紫皇玉镜蟾蜍字，墮地千年光不死。","發匣身沈古井寒，懸台日照愁成水。","海戶山窗幾梳綰，菱花开落何人见。","野老曾耕太白星，神狐夜哭秋天片。","下国青銅旋磨滅，迴鸾万影成枯骨。","會待搏风雨泬寥，长恐莓苔蝕明月。"]', '诗', 'shi', '', NULL, '古鏡篇 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea14f72-3f11-4539-b96e-29d929795c5c', '自歸山', '自归山', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["海嶽南歸遠，天門北望深。","暫爲青瑣客，難換白雲心。","富貴老閑事，猨猱思舊林。","清平無樂志，尊酒有瑤琴。"]', '["海嶽南归远，天门北望深。","暫爲青瑣客，难換白云心。","富貴老闲事，猨猱思旧林。","清平無乐志，尊酒有瑤琴。"]', '诗', 'shi', '', NULL, '自歸山 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed947551-41bc-4ba5-8f98-6af180c94e30', '渡浙江', '渡浙江', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["適越一輕艘，凌兢截鷺濤。","曙光金海近，晴雪玉峰高。","靜寇思投筆，傷時欲釣鼇。","壯心殊未展，登涉漫勞勞。"]', '["適越一轻艘，凌兢截鷺濤。","曙光金海近，晴雪玉峰高。","静寇思投笔，傷时欲釣鼇。","壯心殊未展，登涉漫勞勞。"]', '诗', 'shi', '', NULL, '渡浙江 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac47d94a-9419-47aa-8c99-8f2576f26014', '清源途中旅思', '清源途中旅思', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["古木閩州道，驅羸落照間。","投村礙野水，問店隔荒山。","身事幾時了，蓬飄何日閑。","看花滯南國，鄉月十灣環。"]', '["古木閩州道，驱羸落照间。","投村礙野水，问店隔荒山。","身事幾时了，蓬飄何日闲。","看花滯南国，乡月十灣环。"]', '诗', 'shi', '', NULL, '清源途中旅思 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be10b6ed-de06-41a1-9b2c-d1ac2d0cf030', '南海送韋七使君赴象州任', '南海送韋七使君赴象州任', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["一鶚韋公子，新恩頒郡符。","島夷通荔浦，龍節過蒼梧。","地理金城近，天涯玉樹孤。","聖朝朱紱貴，從此展雄圖。"]', '["一鶚韋公子，新恩頒郡符。","島夷通荔浦，龙節過蒼梧。","地理金城近，天涯玉樹孤。","聖朝朱紱貴，從此展雄圖。"]', '诗', 'shi', '', NULL, '南海送韋七使君赴象州任 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308ad3c5-3e00-486c-977a-3d4d8856a491', '送沈次魯南遊', '送沈次魯南游', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["高臺贈君別，滿握軒轅風。","落日一揮手，金鵝雲雨空。","鼇洲石梁外，劍浦羅浮東。","茲興不可接，翛翛煙際鴻。"]', '["高台贈君別，满握軒轅风。","落日一揮手，金鵝云雨空。","鼇洲石梁外，劍浦羅浮东。","茲兴不可接，翛翛煙際鴻。"]', '诗', 'shi', '', NULL, '送沈次魯南遊 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7867e8-e871-47cb-ac71-74353002129b', '南海石門戍懷古', '南海石门戍懷古', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["漢家征百越，落地喪貔貅。","大野朱旗沒，長江赤血流。","鬼神尋覆族，宮廟變荒丘。","唯有朝臺月，千年照戍樓。"]', '["漢家征百越，落地喪貔貅。","大野朱旗沒，长江赤血流。","鬼神尋覆族，宮廟变荒丘。","唯有朝台月，千年照戍楼。"]', '诗', 'shi', '', NULL, '南海石門戍懷古 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9be23822-1874-4fe2-9cce-1c6c3b575e78', '賦得池塘生春草', '賦得池塘生春草', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["謝公遺詠處，池水夾通津。","古往人何在，年來草自春。","色宜波際綠，香異雨中新。","今日青青意，空悲行路人。"]', '["謝公遺詠处，池水夾通津。","古往人何在，年来草自春。","色宜波際綠，香異雨中新。","今日青青意，空悲行路人。"]', '诗', 'shi', '', NULL, '賦得池塘生春草 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3744ebb-4ad3-4d3b-a14d-2ee08c8a64c6', '題居上人法華新院', '題居上人法华新院', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["浮名深般若，方寺設蓮華。","鐘唄成僧國，湖山稱法家。","一塵多寶塔，千佛大牛車。","能誘泥犂客，超然識聚沙。"]', '["浮名深般若，方寺設蓮华。","鐘唄成僧国，湖山稱法家。","一塵多寶塔，千佛大牛车。","能誘泥犂客，超然識聚沙。"]', '诗', 'shi', '', NULL, '題居上人法華新院 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0202807d-de46-42fb-8ad2-c96e39c68cf1', '送秦鍊師', '送秦鍊師', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["紫府靜沈沈，松軒思別吟。","水流寧有意，雲泛本無心。","錦洞桃花遠，青山竹葉深。","不因時賣藥，何路更相尋。"]', '["紫府静沈沈，松軒思別吟。","水流寧有意，云泛本無心。","錦洞桃花远，青山竹葉深。","不因时賣藥，何路更相尋。"]', '诗', 'shi', '', NULL, '送秦鍊師 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad27ccb-c4fd-42f9-aa46-32af21b13e67', '哭寶月三藏大禪師', '哭寶月三藏大禪師', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["五峰習聖罷，乾竺化身歸。","帝子傳真印，門人哭寶衣。","一囊窮海沒，三藏故園稀。","無復天花落，悲風滿鐵圍。"]', '["五峰習聖罷，乾竺化身归。","帝子傳真印，门人哭寶衣。","一囊窮海沒，三藏故园稀。","無复天花落，悲风满鐵圍。"]', '诗', 'shi', '', NULL, '哭寶月三藏大禪師 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c303e3cb-470e-47b7-8655-dffbbed2344a', '湓城贈別', '湓城贈別', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["楚岸青楓樹，長隨送遠心。","九江春水闊，三峽暮雲深。","氣調桓伊笛，才華蔡琰琴。","迢迢嫁湘漢，誰不重黃金。"]', '["楚岸青楓樹，长隨送远心。","九江春水闊，三峽暮云深。","氣調桓伊笛，才华蔡琰琴。","迢迢嫁湘漢，誰不重黄金。"]', '诗', 'shi', '', NULL, '湓城贈別 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76117075-1764-4768-a954-869643d0add0', '贈別', '贈別', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["海國一尺綺，冰壺萬縷絲。","以君西攀桂，贈此金蓮枝。","高鳥思茂林，窮魚樂洿池。","平生握中寶，無使歲寒移。"]', '["海国一尺綺，冰壺万縷絲。","以君西攀桂，贈此金蓮枝。","高鸟思茂林，窮鱼乐洿池。","平生握中寶，無使歲寒移。"]', '诗', 'shi', '', NULL, '贈別 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d679efa3-fd35-4eca-b0a9-a3e00a012f3d', '贈溫州韓使君', '贈溫州韓使君', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["康樂風流五百年，永嘉鈴閣又登賢。","嚴城鼓動魚驚海，華屋尊開月下天。","內使筆鋒光案牘，鄢陵詩句滿山川。","今來誰似韓家貴，越絕髦幢鴈影連。"]', '["康乐风流五百年，永嘉鈴閣又登賢。","嚴城鼓动鱼驚海，华屋尊开月下天。","內使笔鋒光案牘，鄢陵诗句满山川。","今来誰似韓家貴，越絕髦幢鴈影連。"]', '诗', 'shi', '', NULL, '贈溫州韓使君 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('909587dd-d2cc-462f-a880-a95a0247ca46', '閑居寄太學盧景博士', '闲居寄太学盧景博士', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["無路青冥奪錦袍，恥隨黃雀住蓬蒿。","碧雲夢後山風起，珠樹詩成海月高。","久滯鼎書求羽翼，未忘龍闕致波濤。","閑來長得留侯癖，羅列樝梨校六韜。"]', '["無路青冥奪錦袍，恥隨黄雀住蓬蒿。","碧云梦後山风起，珠樹诗成海月高。","久滯鼎书求羽翼，未忘龙闕致波濤。","闲来长得留侯癖，羅列樝梨校六韜。"]', '诗', 'shi', '', NULL, '閑居寄太學盧景博士 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf6d2fe-ad76-4adb-a3c7-864af3ecca48', '贈漳州張怡使君', '贈漳州張怡使君', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["舊德徐方天下聞，當年熊軾繼清芬。","井田異政光蠻竹，符節深恩隔瘴雲。","已見嘉祥生北戶，嘗嫌夷貊蠹南薰。","幾時徴拜征西越，學著縵胡從使君。"]', '["旧德徐方天下闻，當年熊軾繼清芬。","井田異政光蠻竹，符節深恩隔瘴云。","已见嘉祥生北戶，嘗嫌夷貊蠹南薰。","幾时徴拜征西越，学著縵胡從使君。"]', '诗', 'shi', '', NULL, '贈漳州張怡使君 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4869ee5f-5e0b-4655-a719-a6fc23c3e51a', '贈容南韋中丞', '贈容南韋中丞', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["普寧都護軍威重，九驛梯航壓要津。","十二銅魚尊畫戟，三千犀甲擁朱輪。","風雲已靜西山寇，閭井全移上國春。","不獨來蘇發歌詠，天涯半是泣珠人。"]', '["普寧都護軍威重，九驛梯航壓要津。","十二銅鱼尊畫戟，三千犀甲擁朱輪。","风云已静西山寇，閭井全移上国春。","不独来蘇發歌詠，天涯半是泣珠人。"]', '诗', 'shi', '', NULL, '贈容南韋中丞 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a69282d-59c4-4f42-9e3e-b10f9eddfded', '投贈福建路羅中丞', '投贈福建路羅中丞', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["越豔聽謠不厭聽，樓船高臥靜南溟。","未聞建水窺龍劍，應喜家山接女星。","三捷楷模光典策，一生封爵笑丹青。","皇恩幾日西歸去，玉樹扶疎正滿庭。"]', '["越豔听謠不厭听，楼船高臥静南溟。","未闻建水窺龙劍，應喜家山接女星。","三捷楷模光典策，一生封爵笑丹青。","皇恩幾日西归去，玉樹扶疎正满庭。"]', '诗', 'shi', '', NULL, '投贈福建路羅中丞 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ec0ef0-0965-40a5-803c-ab1df0cdf3e1', '贈江南李偕副使', '贈江南李偕副使', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["世祿三朝壓鳳池，杜陵公子漢庭知。","雷封始賀堂溪劍，花府尋邀玉樹枝。","幾日坐談誅叛逆，列城歸美見歌詩。","從軍莫厭千場醉，即是金鑾寵命時。"]', '["世祿三朝壓鳳池，杜陵公子漢庭知。","雷封始賀堂溪劍，花府尋邀玉樹枝。","幾日坐談誅叛逆，列城归美见歌诗。","從軍莫厭千場醉，即是金鑾寵命时。"]', '诗', 'shi', '', NULL, '贈江南李偕副使 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb20e9e2-d9b8-4e4c-a395-9196d6445b5e', '賀容府韋中丞大府賢兄新除黔南經略', '賀容府韋中丞大府賢兄新除黔南經略', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["蓬瀛簪笏舊聯行，紫極差池降寵章。","列國山河分鴈字，一門金玉盡龍驤。","耿家符節朝中美，袁氏芝蘭閫外香。","烽戍悠悠限巴越，佇聽歌詠兩甘棠。"]', '["蓬瀛簪笏旧聯行，紫極差池降寵章。","列国山河分鴈字，一门金玉尽龙驤。","耿家符節朝中美，袁氏芝蘭閫外香。","烽戍悠悠限巴越，佇听歌詠兩甘棠。"]', '诗', 'shi', '', NULL, '賀容府韋中丞大府賢兄新除黔南經略 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1020f0-280a-4b1d-a130-38f6fea786e4', '和容南韋中丞題瑞亭白燕白鼠六眸龜嘉蓮', '和容南韋中丞題瑞亭白燕白鼠六眸龟嘉蓮', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["伏波恩行動南夷，交趾喧傳四瑞詩。","燕鼠孕靈褒上德，龜蓮增耀荅無私。","迴翔雪侶窺簷處，照映紅巢出水時。","盡寫流傳在軒檻，嘉祥從此百年知。"]', '["伏波恩行动南夷，交趾喧傳四瑞诗。","燕鼠孕靈褒上德，龟蓮增耀荅無私。","迴翔雪侶窺簷处，照映紅巢出水时。","尽寫流傳在軒檻，嘉祥從此百年知。"]', '诗', 'shi', '', NULL, '和容南韋中丞題瑞亭白燕白鼠六眸龜嘉蓮 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9c851de-5244-47ea-a802-4ed7a00b1373', '題豫章西山香城寺', '題豫章西山香城寺', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["十地嚴宮禮竺皇，栴檀樓閣半天香。","祇園樹老梵聲小，雪嶺花香燈影長。","霄漢落泉供月界，蓬壺靈鳥侍雲房。","何年七七金人降，金錫珠壇滿上方。"]', '["十地嚴宮禮竺皇，栴檀楼閣半天香。","祇园樹老梵声小，雪嶺花香灯影长。","霄漢落泉供月界，蓬壺靈鸟侍云房。","何年七七金人降，金錫珠壇满上方。"]', '诗', 'shi', '', NULL, '題豫章西山香城寺 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f877d66f-07d9-47ba-b345-28a0562320bf', '送江西周尚書赴滑臺', '送江西周尚书赴滑台', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["楚謠襦袴整三千，喉舌新恩下九天。","天角雄都分節鉞，蛟龍舊國罷樓船。","崑河已在兵鈐內，棠樹空留鶴嶺前。","多病無因酬一顧，鄢陵千騎去翩翩。"]', '["楚謠襦袴整三千，喉舌新恩下九天。","天角雄都分節鉞，蛟龙旧国罷楼船。","崑河已在兵鈐內，棠樹空留鹤嶺前。","多病無因酬一顧，鄢陵千騎去翩翩。"]', '诗', 'shi', '', NULL, '送江西周尚書赴滑臺 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b763fd08-f084-4e54-814b-f5f553efa039', '閩中送任畹端公還京', '閩中送任畹端公還京', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["燕臺下榻玉爲人，月桂曾輸次第春。","幾日酬恩坐炎瘴，九秋高駕拂星辰。","漢庭鳳進鵷行喜，隋國珠還水府貧。","多少嘉謨奏風俗，斗牛孤劍在平津。"]', '["燕台下榻玉爲人，月桂曾輸次第春。","幾日酬恩坐炎瘴，九秋高駕拂星辰。","漢庭鳳進鵷行喜，隋国珠還水府貧。","多少嘉謨奏风俗，斗牛孤劍在平津。"]', '诗', 'shi', '', NULL, '閩中送任畹端公還京 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa551a8f-8244-4f17-baee-6a36e92debd7', '豫章江樓望西山有懷', '豫章江楼望西山有懷', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["水護星壇列太虛，煙霓十八上仙居。","時人未識遼東鶴，吾祖曾傳寶鼎書。","終日章江催白鬢，何年丹竈見紅蕖。","桃花谷口春深淺，欲訪仙生赤鯉魚。"]', '["水護星壇列太虛，煙霓十八上仙居。","时人未識遼东鹤，吾祖曾傳寶鼎书。","終日章江催白鬢，何年丹竈见紅蕖。","桃花谷口春深淺，欲訪仙生赤鯉鱼。"]', '诗', 'shi', '', NULL, '豫章江樓望西山有懷 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e224b97a-15a6-4e61-9877-c49ec52b017d', '經徐穉墓', '經徐穉墓', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["郟鄏妖興炎漢衰，先生南國臥明夷。","鳳皇屢降玄纁禮，瓊石終藏烈火詩。","禁掖衣冠加宋鵲，湖山耕釣沒堯時。","千年壠樹何人哭，寂寞蒼苔內史碑。"]', '["郟鄏妖兴炎漢衰，先生南国臥明夷。","鳳皇屢降玄纁禮，瓊石終藏烈火诗。","禁掖衣冠加宋鵲，湖山耕釣沒堯时。","千年壠樹何人哭，寂寞蒼苔內史碑。"]', '诗', 'shi', '', NULL, '經徐穉墓 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e8c19b-9c04-4505-be11-3f6aff8d5dab', '鍾陵道中作', '鍾陵道中作', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["原隰經霜蕙草黃，塞鴻消息怨流芳。","秋山落照見麋鹿，南國異花開雪霜。","煙火近通槃瓠俗，水雲深入武陵鄉。","曾逢齧缺話東海，長憶蕭家青玉牀。"]', '["原隰經霜蕙草黄，塞鴻消息怨流芳。","秋山落照见麋鹿，南国異花开雪霜。","煙火近通槃瓠俗，水云深入武陵乡。","曾逢齧缺話东海，长憶蕭家青玉牀。"]', '诗', 'shi', '', NULL, '鍾陵道中作 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b133f02f-3ce8-4101-9fc6-1fa2ab75cb8e', '旅泊塗江', '旅泊塗江', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["煙雨南江一葉微，松潭漁父夜相依。","斷沙鴈起金精出，孤嶺猨愁木客歸。","楚國柑橙勞夢想，丹陵霞鶴間音徽。","無因得似滄溟叟，始憶離巢已倦飛。"]', '["煙雨南江一葉微，松潭漁父夜相依。","斷沙鴈起金精出，孤嶺猨愁木客归。","楚国柑橙勞梦想，丹陵霞鹤间音徽。","無因得似滄溟叟，始憶離巢已倦飞。"]', '诗', 'shi', '', NULL, '旅泊塗江 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3349da10-4e46-4f99-bbdd-d1da751c4885', '上建溪', '上建溪', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["崆垌一派瀉蒼煙，長揖丹丘逐水仙。","雲樹杳冥通上界，峰巒迴合下閩川。","侵星愁過蛟龍國，採碧時逢婺女船。","已判猨催鬢先白，幾重灘瀨在秋天。"]', '["崆垌一派瀉蒼煙，长揖丹丘逐水仙。","云樹杳冥通上界，峰巒迴合下閩川。","侵星愁過蛟龙国，採碧时逢婺女船。","已判猨催鬢先白，幾重灘瀨在秋天。"]', '诗', 'shi', '', NULL, '上建溪 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57ef90df-c659-45db-b20d-f5f6d83b8d88', '冬日暮旅泊廬陵', '冬日暮旅泊廬陵', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["螺亭倚棹哭飄蓬，白浪欺船自向東。","楚國蕙蘭增悵望，番禺筐篚旅虛空。","江城雪落千家夢，汀渚冰生一夕風。","棄置侯鯖任羇束，不勞龜瓦問窮通。"]', '["螺亭倚棹哭飄蓬，白浪欺船自向东。","楚国蕙蘭增悵望，番禺筐篚旅虛空。","江城雪落千家梦，汀渚冰生一夕风。","棄置侯鯖任羇束，不勞龟瓦问窮通。"]', '诗', 'shi', '', NULL, '冬日暮旅泊廬陵 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bade2217-9882-453c-82a6-6c3990f29c07', '登寶曆寺閣', '登寶曆寺閣', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["金碧高層世界空，憑蜺長嘯八鑾風。","橫軒水壯蛟龍府，倚棟星開牛斗宮。","三楚故墟殘景北，六朝荒苑斷山東。","不堪懷古勞悲笑，安得鵬摶顥氣中。"]', '["金碧高層世界空，憑蜺长嘯八鑾风。","橫軒水壯蛟龙府，倚棟星开牛斗宮。","三楚故墟殘景北，六朝荒苑斷山东。","不堪懷古勞悲笑，安得鵬摶顥氣中。"]', '诗', 'shi', '', NULL, '登寶曆寺閣 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8192d135-ab8a-4c70-94c3-c7c2c91e6a04', '寄兵部任畹郎中', '寄兵部任畹郎中', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["常思劍浦越清塵，荳蔻花紅十二春。","崑玉已成廊廟器，澗松猶是薜蘿身。","雖同橘柚依南土，終媿魁罡近北辰。","好向昌時薦遺逸，莫教千古弔靈均。"]', '["常思劍浦越清塵，荳蔻花紅十二春。","崑玉已成廊廟器，澗松猶是薜蘿身。","雖同橘柚依南土，終媿魁罡近北辰。","好向昌时薦遺逸，莫教千古弔靈均。"]', '诗', 'shi', '', NULL, '寄兵部任畹郎中 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb61665-75ea-4fdb-83b8-230e99a1a337', '贈江南從事張侍郎', '贈江南從事張侍郎', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["平南門館鳳皇毛，二十華軒立最高。","幾處談天致雲雨，早時文海得鯨鼇。","姻聯紫府蕭窗貴，職稱青錢繡服豪。","江徼無虞才不展，銜杯終日詠離騷。"]', '["平南门館鳳皇毛，二十华軒立最高。","幾处談天致云雨，早时文海得鯨鼇。","姻聯紫府蕭窗貴，職稱青錢繡服豪。","江徼無虞才不展，銜杯終日詠離騷。"]', '诗', 'shi', '', NULL, '贈江南從事張侍郎 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e472f7a2-a62b-4dbd-9ea2-61a1e2e6796e', '劍池', '劍池', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["秦帝南巡厭火精，蒼黃埋劍故豐城。","霸圖繚戾金龍螫，坤道扶搖紫氣生。","星斗臥來閑窟穴，雌雄飛去變澄泓。","永懷惆悵中宵作，不見春雷發匣聲。"]', '["秦帝南巡厭火精，蒼黄埋劍故豐城。","霸圖繚戾金龙螫，坤道扶搖紫氣生。","星斗臥来闲窟穴，雌雄飞去变澄泓。","永懷惆悵中宵作，不见春雷發匣声。"]', '诗', 'shi', '', NULL, '劍池 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6bfe501-f496-4ddb-a5a5-798774a3b308', '洛城見賀自真飛昇', '洛城见賀自真飞昇', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["子晉鸞飛古洛川，金桃再熟賀郎仙。","三清樂奏嵩丘下，五色雲屯御苑前。","朱頂舞低迎絳節，青鬟歌對駐香軿。","誰能白晝相悲泣，太極光陰億萬年。"]', '["子晉鸾飞古洛川，金桃再熟賀郎仙。","三清乐奏嵩丘下，五色云屯御苑前。","朱頂舞低迎絳節，青鬟歌对駐香軿。","誰能白晝相悲泣，太極光陰億万年。"]', '诗', 'shi', '', NULL, '洛城見賀自真飛昇 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3069b13-ab5c-4804-a913-2effef02da1c', '謫仙吟贈趙道士', '謫仙吟贈趙道士', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["汗漫東遊黃鶴雛，縉雲仙子住清都。","三元麟鳳推高座，六甲風雷閟小壺。","日月暗資靈壽藥，山河擬作化生符。","若爲失意居蓬島，鼇足塵飛桑樹枯。"]', '["汗漫东游黄鹤雛，縉云仙子住清都。","三元麟鳳推高座，六甲风雷閟小壺。","日月暗資靈壽藥，山河擬作化生符。","若爲失意居蓬島，鼇足塵飞桑樹枯。"]', '诗', 'shi', '', NULL, '謫仙吟贈趙道士 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8e18db0-a45a-4b71-8049-4bdcd39f3ebb', '夜別溫商梓州', '夜別溫商梓州', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["鳳皇城裏花時別，玄武江邊月下逢。","客舍莫辭先買酒，相門曾忝舊登龍。","迎風騷屑千家竹，隔水悠揚午夜鐘。","明日又行西蜀去，不堪天際遠山重。"]', '["鳳皇城裏花时別，玄武江邊月下逢。","客舍莫辞先買酒，相门曾忝旧登龙。","迎风騷屑千家竹，隔水悠揚午夜鐘。","明日又行西蜀去，不堪天際远山重。"]', '诗', 'shi', '', NULL, '夜別溫商梓州 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b4ff908-f093-4ae2-9b02-281c0a276aba', '題贈高閑上人', '題贈高闲上人', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["簷蔔花間客，軒轅席上珍。","筆江秋菡萏，僧國瑞麒麟。","內殿初招隱，曹溪得後塵。","龍蛇驚粉署，花雨對金輪。","白馬方依漢，朱星又入秦。","劇談凌鑿齒，清論倒波旬。","拂石先天古，降龍舊國春。","珠還合浦老，龍去玉州貧。","鴛鷺輸黃絹，場壇遶白萍。","鼎湖閑入夢，金閣靜通神。","海氣成方丈，山泉落淨巾。","獼猴深愛月，鷗鳥不猜人。","拂岳蕭蕭竹，垂空澹澹津。","漢珠難覓對，荆璞本來真。","伊傅多聯壁，劉雷競買鄰。","江邊有國寶，時爲劚星辰。"]', '["簷蔔花间客，軒轅席上珍。","笔江秋菡萏，僧国瑞麒麟。","內殿初招隐，曹溪得後塵。","龙蛇驚粉署，花雨对金輪。","白马方依漢，朱星又入秦。","劇談凌鑿齒，清論倒波旬。","拂石先天古，降龙旧国春。","珠還合浦老，龙去玉州貧。","鴛鷺輸黄絹，場壇遶白萍。","鼎湖闲入梦，金閣静通神。","海氣成方丈，山泉落淨巾。","獼猴深愛月，鷗鸟不猜人。","拂岳蕭蕭竹，垂空澹澹津。","漢珠难覓对，荆璞本来真。","伊傅多聯壁，劉雷競買鄰。","江邊有国寶，时爲劚星辰。"]', '诗', 'shi', '', NULL, '題贈高閑上人 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397074bf-946f-46a2-9fde-29f95206e3a4', '哭王贊府', '哭王贊府', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["白水流今古，青山送死生。","驅馳三楚掾，倏忽一空名。","金玉埋臯壤，芝蘭哭弟兄。","龍頭孤後進，鵬翅失前程。","愁變風雲色，悲連鼓角聲。","落星辭聖代，寒夢閉佳城。","伊昔來江邑，從容副國英。","德踰棲棘美，公亞飲冰清。","大廈亡孤直，羣儒憶老成。","白駒悲里巷，梁木慟簪纓。","隴遂添新草，珠還滿舊籝。","蒼蒼難可問，原上晚煙橫。"]', '["白水流今古，青山送死生。","驱驰三楚掾，倏忽一空名。","金玉埋臯壤，芝蘭哭弟兄。","龙头孤後進，鵬翅失前程。","愁变风云色，悲連鼓角声。","落星辞聖代，寒梦閉佳城。","伊昔来江邑，從容副国英。","德踰棲棘美，公亞饮冰清。","大廈亡孤直，羣儒憶老成。","白駒悲里巷，梁木慟簪纓。","隴遂添新草，珠還满旧籝。","蒼蒼难可问，原上晚煙橫。"]', '诗', 'shi', '', NULL, '哭王贊府 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df825dfe-e82c-475c-b6eb-56a5e9b4d22c', '聖帝撃壤歌四十聲', '聖帝撃壤歌四十声', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["百六承堯緒，艱難土運昌。","太虛橫彗孛，中野鬬豺狼。","帝曰更吾嗣，時哉憶聖唐。","英星垂將校，神嶽誕忠良。","鍊石醫元氣，屠鼇正昊蒼。","掃原鋪一德，驅祲立三光。","大道重蘇息，真風再發揚。","芟夷踰舊跡，神聖掩前王。","郊酒酣寥廓，鴻恩受渺茫。","地圖龜負出，天誥鳳銜將。","雜貢來山峙，羣夷入鴈行。","紫泥搜海岱，鴻筆富巖廊。","鷹象敷宸極，寰瀛作瑞坊。","泥丸封八表，金鏡照中央。","構殿基麟趾，開藩表鳳翔。","鑾輿親稼穡，朱幌務蠶桑。","戎羯輸天馬，靈仙侍玉房。","宮儀水蒐甲，門衛綠沈槍。","陶鑄超三古，車書混萬方。","時巡望虞舜，蒐狩法殷湯。","化合謳謠滿，年豐鬼蜮藏。","政源歸牧馬，宮法付神羊。","寶鼎無靈應，金甌肯破傷。","封山昭茂績，祠執荅嘉祥。","在昔宮闈僭，仍罹羿浞殃。","牝雞何譈䜕，猘犬漫劻勷。","苗禱三靈怒，桓偷九族亡。","鯨鯢尋挂網，魑魅旋投荒。","松栢霜逾翠，芝蘭露更香。","聖謨流祚遠，仙系發源長。","島嶼征徭薄，漪瀾汎稻涼。","鳧魚饜飡啖，荷薜足衣裳。","寤寐華胥國，嬉遊太素鄉。","鷹鸇飛接翼，忠孝住連牆。","有叟能調鼎，無媒隱釣璜。","乾坤資識量，江海入文章。","野鶴思蓬闕，山麋憶廟堂。","泥沙空淬礪，星斗屢低昂。","歷草何因見，衢尊豈暫忘。","終隨嘉橘賦，霄漢謁羲皇。"]', '["百六承堯緒，艱难土運昌。","太虛橫彗孛，中野鬬豺狼。","帝曰更吾嗣，时哉憶聖唐。","英星垂將校，神嶽誕忠良。","鍊石醫元氣，屠鼇正昊蒼。","掃原鋪一德，驱祲立三光。","大道重蘇息，真风再發揚。","芟夷踰旧跡，神聖掩前王。","郊酒酣寥廓，鴻恩受渺茫。","地圖龟負出，天誥鳳銜將。","杂貢来山峙，羣夷入鴈行。","紫泥搜海岱，鴻笔富巖廊。","鷹象敷宸極，寰瀛作瑞坊。","泥丸封八表，金镜照中央。","構殿基麟趾，开藩表鳳翔。","鑾輿親稼穡，朱幌務蠶桑。","戎羯輸天马，靈仙侍玉房。","宮儀水蒐甲，门衛綠沈槍。","陶鑄超三古，车书混万方。","时巡望虞舜，蒐狩法殷湯。","化合謳謠满，年豐鬼蜮藏。","政源归牧马，宮法付神羊。","寶鼎無靈應，金甌肯破傷。","封山昭茂績，祠執荅嘉祥。","在昔宮闈僭，仍罹羿浞殃。","牝雞何譈䜕，猘犬漫劻勷。","苗禱三靈怒，桓偷九族亡。","鯨鯢尋挂網，魑魅旋投荒。","松栢霜逾翠，芝蘭露更香。","聖謨流祚远，仙系發源长。","島嶼征徭薄，漪瀾汎稻涼。","鳧鱼饜飡啖，荷薜足衣裳。","寤寐华胥国，嬉游太素乡。","鷹鸇飞接翼，忠孝住連牆。","有叟能調鼎，無媒隐釣璜。","乾坤資識量，江海入文章。","野鹤思蓬闕，山麋憶廟堂。","泥沙空淬礪，星斗屢低昂。","歷草何因见，衢尊豈暫忘。","終隨嘉橘賦，霄漢謁羲皇。"]', '诗', 'shi', '', NULL, '聖帝撃壤歌四十聲 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58108e36-179c-458c-a56c-5eac25ca1361', '續古二十九首 一', '續古二十九首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["大堯登寶位，麟鳳煥宸居。","海曲霑恩澤，還生比目魚。"]', '["大堯登寶位，麟鳳煥宸居。","海曲霑恩澤，還生比目鱼。"]', '诗', 'shi', '', NULL, '續古二十九首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3dab92e-971c-4b58-aa57-8a9056565911', '續古二十九首 二', '續古二十九首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["生值揖遜曆，長歌東南春。","釣鼇年三十，未見天子巡。"]', '["生值揖遜曆，长歌东南春。","釣鼇年三十，未见天子巡。"]', '诗', 'shi', '', NULL, '續古二十九首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1221ddba-00e2-481b-96cc-2b4a4c3ee725', '續古二十九首 三', '續古二十九首 三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["軒轅承化日，羣鳳戲池臺。","大樸衰喪後，仲尼生不來。"]', '["軒轅承化日，羣鳳戲池台。","大樸衰喪後，仲尼生不来。"]', '诗', 'shi', '', NULL, '續古二十九首 三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5646c461-6390-4cd9-9336-a7f85075989b', '續古二十九首 四', '續古二十九首 四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["大道歸孟門，蕭蘭日爭長。","想得巢居時，碧江應無浪。"]', '["大道归孟门，蕭蘭日爭长。","想得巢居时，碧江應無浪。"]', '诗', 'shi', '', NULL, '續古二十九首 四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1401ae10-7e8f-4628-b28f-d0e7340a7aa5', '續古二十九首 五', '續古二十九首 五', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["矻矻蓬舍下，慕君麒麟閣。","笑殺王子喬，寥天乘白鶴。"]', '["矻矻蓬舍下，慕君麒麟閣。","笑殺王子喬，寥天乘白鹤。"]', '诗', 'shi', '', NULL, '續古二十九首 五 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c7ece0-7291-41e7-b35b-42f4836b2a61', '續古二十九首 六', '續古二十九首 六', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["杳杳巫峽雲，悠悠漢江水。","愁殺幾少年，春風相憶地。"]', '["杳杳巫峽云，悠悠漢江水。","愁殺幾少年，春风相憶地。"]', '诗', 'shi', '', NULL, '續古二十九首 六 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa29b562-619a-4fe1-9cfa-9bf42a9e67b0', '續古二十九首 七', '續古二十九首 七', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["吳洲采芳客，桂棹木蘭船。","日晚欲有寄，裴回春風前。"]', '["吳洲采芳客，桂棹木蘭船。","日晚欲有寄，裴回春风前。"]', '诗', 'shi', '', NULL, '續古二十九首 七 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('accf07a9-0972-44a2-9564-bb805856dd7e', '續古二十九首 八', '續古二十九首 八', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["仙家風景晏，浮世年華速。","邂逅漢武時，蟠桃海東熟。"]', '["仙家风景晏，浮世年华速。","邂逅漢武时，蟠桃海东熟。"]', '诗', 'shi', '', NULL, '續古二十九首 八 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2954cdd9-cfc5-42e9-92b8-7cb2415c795b', '續古二十九首 九', '續古二十九首 九', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["南國珊瑚樹，好裁天馬鞭。","魚龍不解語，海曲空嬋娟。"]', '["南国珊瑚樹，好裁天马鞭。","鱼龙不解語，海曲空嬋娟。"]', '诗', 'shi', '', NULL, '續古二十九首 九 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0616c55-b4a7-45f5-a73c-76e59fe5c4d7', '續古二十九首 十', '續古二十九首 十', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["周穆恣遊幸，橫天驅八龍。","寧知泰山下，日日望登封。"]', '["周穆恣游幸，橫天驱八龙。","寧知泰山下，日日望登封。"]', '诗', 'shi', '', NULL, '續古二十九首 十 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('645dd081-d41b-432a-a627-45725c4d729f', '續古二十九首 十一', '續古二十九首 十一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["秦國饒羅網，中原絕麟鳳。","萬乘巡海回，鮑魚空相送。"]', '["秦国饒羅網，中原絕麟鳳。","万乘巡海回，鲍鱼空相送。"]', '诗', 'shi', '', NULL, '續古二十九首 十一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('426ea595-2b9d-4c26-809b-146610c5cfd7', '續古二十九首 十二', '續古二十九首 十二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["秦家無廟略，遮虜續長城。","萬姓隴頭死，中原荆棘生。"]', '["秦家無廟略，遮虜續长城。","万姓隴头死，中原荆棘生。"]', '诗', 'shi', '', NULL, '續古二十九首 十二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9dea70c-4fde-4b0d-a572-f6796f57be54', '續古二十九首 十三', '續古二十九首 十三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["秦作東海橋，中州鬼辛苦。","縱得跨蓬萊，羣仙亦飛去。"]', '["秦作东海橋，中州鬼辛苦。","縱得跨蓬萊，羣仙亦飞去。"]', '诗', 'shi', '', NULL, '續古二十九首 十三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15f30552-4756-465e-ae1f-af59e8806ee2', '續古二十九首 十四', '續古二十九首 十四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["隋煬棄中國，龍舟巡海涯。","春風廣陵苑，不見秦宮花。"]', '["隋煬棄中国，龙舟巡海涯。","春风廣陵苑，不见秦宮花。"]', '诗', 'shi', '', NULL, '續古二十九首 十四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b253f96-c7c7-4e64-9fba-f19c81ad80c3', '續古二十九首 十五', '續古二十九首 十五', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["范子相句踐，滅吳成大勳。","雖然五湖去，終媿磻溪雲。"]', '["范子相句踐，滅吳成大勳。","雖然五湖去，終媿磻溪云。"]', '诗', 'shi', '', NULL, '續古二十九首 十五 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281304ee-bf77-4835-a772-ba2638d8d69c', '續古二十九首 十六', '續古二十九首 十六', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["麟鳳識翔蟄，聖賢明卷舒。","哀哉嵇叔夜，智不及鶢鶋。"]', '["麟鳳識翔蟄，聖賢明卷舒。","哀哉嵇叔夜，智不及鶢鶋。"]', '诗', 'shi', '', NULL, '續古二十九首 十六 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a2b495-c371-4c42-a225-e509ff278523', '續古二十九首 十七', '續古二十九首 十七', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["戰地三尺骨，將軍一身貴。","自古若弔冤，落花少於淚。"]', '["戰地三尺骨，將軍一身貴。","自古若弔冤，落花少於泪。"]', '诗', 'shi', '', NULL, '續古二十九首 十七 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77a5f5c4-3f13-4ce3-a183-eec1807e7e54', '續古二十九首 十八', '續古二十九首 十八', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["楚國千里旱，土龍日已多。","九穀竟枯死，好雲閑嵯峨。"]', '["楚国千里旱，土龙日已多。","九穀竟枯死，好云闲嵯峨。"]', '诗', 'shi', '', NULL, '續古二十九首 十八 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a83d732c-5483-4734-b9ca-7facba20ba77', '續古二十九首 十九', '續古二十九首 十九', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["漢家三殿色，恩澤若飄風。","今日黃金屋，明朝長信宮。"]', '["漢家三殿色，恩澤若飄风。","今日黄金屋，明朝长信宮。"]', '诗', 'shi', '', NULL, '續古二十九首 十九 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b0ef3a2-b9ca-4f33-b601-918d495e8ac5', '續古二十九首 二十', '續古二十九首 二十', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["南園杏花發，北渚梅花落。","吳女妒西施，容華日消鑠。"]', '["南园杏花發，北渚梅花落。","吳女妒西施，容华日消鑠。"]', '诗', 'shi', '', NULL, '續古二十九首 二十 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0bee7e-2991-4e86-9229-2b7846ddd928', '續古二十九首 二十一', '續古二十九首 二十一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["山雞理毛羽，自言勝烏鳶。","一朝逢鸑鷟，羞死南海邊。"]', '["山雞理毛羽，自言勝烏鳶。","一朝逢鸑鷟，羞死南海邊。"]', '诗', 'shi', '', NULL, '續古二十九首 二十一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d46ef1-a935-48a5-99d7-56c608c244ce', '續古二十九首 二十二', '續古二十九首 二十二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["秦家卷衣貴，本是倡家子。","金殿一承恩，貂蟬滿鄉里。"]', '["秦家卷衣貴，本是倡家子。","金殿一承恩，貂蟬满乡里。"]', '诗', 'shi', '', NULL, '續古二十九首 二十二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab36b040-b677-43f7-ba5e-2ad59bef9085', '續古二十九首 二十三', '續古二十九首 二十三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["魏宮薛家女，秀色傾三殿。","武帝鼎湖歸，一身似秋扇。"]', '["魏宮薛家女，秀色傾三殿。","武帝鼎湖归，一身似秋扇。"]', '诗', 'shi', '', NULL, '續古二十九首 二十三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c03343a4-9bb0-4ad2-96be-6c7f01101437', '續古二十九首 二十四', '續古二十九首 二十四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["嬋娟越機裏，織得雙棲鳳。","慰此殊世花，金梭忽停弄。"]', '["嬋娟越機裏，织得雙棲鳳。","慰此殊世花，金梭忽停弄。"]', '诗', 'shi', '', NULL, '續古二十九首 二十四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a21256c-f8ee-40e2-8058-95ef3dc4ed00', '續古二十九首 二十五', '續古二十九首 二十五', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["學古三十載，猶依白雲居。","每覽班超傳，令人慵讀書。"]', '["学古三十載，猶依白云居。","每覽班超傳，令人慵读书。"]', '诗', 'shi', '', NULL, '續古二十九首 二十五 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('753bc1ac-a6d3-4f67-b686-a0f6833db44e', '續古二十九首 二十六', '續古二十九首 二十六', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["雄劍久濩落，夜吟秋風起。","不是懶爲龍，此非延平水。"]', '["雄劍久濩落，夜吟秋风起。","不是懶爲龙，此非延平水。"]', '诗', 'shi', '', NULL, '續古二十九首 二十六 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f9344b-9aed-4357-ad73-0456ca47e8d6', '續古二十九首 二十七', '續古二十九首 二十七', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["朝爲楊柳色，暮作芙蓉好。","春風若有情，江山相逐老。"]', '["朝爲楊柳色，暮作芙蓉好。","春风若有情，江山相逐老。"]', '诗', 'shi', '', NULL, '續古二十九首 二十七 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd74774-cb3c-476d-a4cf-b1ad60c18b33', '續古二十九首 二十八', '續古二十九首 二十八', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["景龍臨太極，五鳳當庭舞。","誰信壁間梭，昇天作雲雨。"]', '["景龙臨太極，五鳳當庭舞。","誰信壁间梭，昇天作云雨。"]', '诗', 'shi', '', NULL, '續古二十九首 二十八 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44d482c5-a6ec-4549-8326-970a3b3759fe', '續古二十九首 二十九', '續古二十九首 二十九', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["曾夢諸侯笑，康囚議脫枷。","千根池底藕，一朵火中花。"]', '["曾梦諸侯笑，康囚議脫枷。","千根池底藕，一朵火中花。"]', '诗', 'shi', '', NULL, '續古二十九首 二十九 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f6f7e0d-65f2-43ac-bc66-082d5d9f64f3', '永嘉贈別', '永嘉贈別', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["芳草溫陽客，歸心浙水西。","臨風青桂檝，幾日白蘋溪。"]', '["芳草溫陽客，归心浙水西。","臨风青桂檝，幾日白蘋溪。"]', '诗', 'shi', '', NULL, '永嘉贈別 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca66ecd1-2f3d-40e9-b932-a8aa2ac9b1b0', '有所思', '有所思', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["欲唱玄雲曲，知音復誰是。","採掇情未來，臨池畫春水。"]', '["欲唱玄云曲，知音复誰是。","採掇情未来，臨池畫春水。"]', '诗', 'shi', '', NULL, '有所思 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2bc987d-79d7-42e8-bd5b-60872092f093', '吳苑思', '吳苑思', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["今人地藏古人骨，古人花爲今人發。","江南何處葬西施，謝豹空聞采香月。"]', '["今人地藏古人骨，古人花爲今人發。","江南何处葬西施，謝豹空闻采香月。"]', '诗', 'shi', '', NULL, '吳苑思 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c100875b-4803-497f-ad7b-00d681b02233', '古意', '古意', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["麻姑井邊一株杏，花開不如古時紅。","西鄰蔡家十歲女，年年二月賣東風。"]', '["麻姑井邊一株杏，花开不如古时紅。","西鄰蔡家十歲女，年年二月賣东风。"]', '诗', 'shi', '', NULL, '古意 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c1cf7e-6771-40db-804d-1e47fde0986d', '朝元引四首 一', '朝元引四首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["帝燭熒煌下九天，蓬萊宮曉玉爐煙。","無央鸞鳳隨金母，來賀熏風一萬年。"]', '["帝燭熒煌下九天，蓬萊宮晓玉爐煙。","無央鸾鳳隨金母，来賀熏风一万年。"]', '诗', 'shi', '', NULL, '朝元引四首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('962d499e-3155-4693-a58c-ed5d1b90b0e0', '朝元引四首 二', '朝元引四首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["正殿雲開露冕旒，下方珠翠壓鼇頭。","天雞唱罷南山曉，春色光輝十二樓。"]', '["正殿云开露冕旒，下方珠翠壓鼇头。","天雞唱罷南山晓，春色光輝十二楼。"]', '诗', 'shi', '', NULL, '朝元引四首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('446c2fc0-eb50-4728-9f15-5e8f870aee71', '朝元引四首 三', '朝元引四首 三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["萬宇靈祥擁帝居，東華元老薦屠蘇。","龍池遙望非烟拜，五色曈曨在玉壺。"]', '["万宇靈祥擁帝居，东华元老薦屠蘇。","龙池遙望非烟拜，五色曈曨在玉壺。"]', '诗', 'shi', '', NULL, '朝元引四首 三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af0c5bb4-e76f-4e19-b781-e1f4c17e257d', '朝元引四首 四', '朝元引四首 四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["寶祚河宮一向清，龜魚天篆益分明。","近臣誰獻登封草，五岳齊呼萬歲聲。"]', '["寶祚河宮一向清，龟鱼天篆益分明。","近臣誰獻登封草，五岳齊呼万歲声。"]', '诗', 'shi', '', NULL, '朝元引四首 四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7783ca-0abb-49d9-afcc-b842a3d3ed19', '宿天竺寺', '宿天竺寺', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["一宵何期此靈境，五粒松香金地冷。","西僧示我高隱心，月在中峰葛洪井。"]', '["一宵何期此靈境，五粒松香金地冷。","西僧示我高隐心，月在中峰葛洪井。"]', '诗', 'shi', '', NULL, '宿天竺寺 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a4a1c0-c657-42f2-bbd0-932999ce3dad', '賦得古蓮塘', '賦得古蓮塘', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["闔閭宮娃能采蓮，明珠作佩龍爲船。","三千巧笑不復見，江頭廢苑花年年。"]', '["闔閭宮娃能采蓮，明珠作佩龙爲船。","三千巧笑不复见，江头廢苑花年年。"]', '诗', 'shi', '', NULL, '賦得古蓮塘 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bfd6c93-c47c-4430-ab3a-3356aa46219c', '雙桂詠', '雙桂詠', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["青冥結根易傾倒，沃洲山中雙樹好。","瑠璃宮殿無斧聲，石上蕭蕭伴僧老。"]', '["青冥結根易傾倒，沃洲山中雙樹好。","瑠璃宮殿無斧声，石上蕭蕭伴僧老。"]', '诗', 'shi', '', NULL, '雙桂詠 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd22864-927d-4b6d-9e2e-fbac5626c41a', '夏日懷天台', '夏日懷天台', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["竹齋睡餘柘漿清，麟鳳誘我勞此生。","勿憶天台掩書坐，澗雲起盡紅崢嶸。"]', '["竹斋睡餘柘漿清，麟鳳誘我勞此生。","勿憶天台掩书坐，澗云起尽紅崢嶸。"]', '诗', 'shi', '', NULL, '夏日懷天台 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e6fae9a-272b-4fb8-ade1-65379d861b93', '臨風歎', '臨风歎', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["芙蓉樓中飲君酒，驪駒結言春楊柳。","豫章花落不見歸，一望東風堪白首。"]', '["芙蓉楼中饮君酒，驪駒結言春楊柳。","豫章花落不见归，一望东风堪白首。"]', '诗', 'shi', '', NULL, '臨風歎 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5957d67e-7497-46fb-9c8f-b4a2edec54f8', '春日行', '春日行', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["鶗鴂初鳴洲渚滿，龍蛇洗鱗春水暖。","病多欲問山寺僧，湖上人傳石橋斷。"]', '["鶗鴂初鳴洲渚满，龙蛇洗鱗春水暖。","病多欲问山寺僧，湖上人傳石橋斷。"]', '诗', 'shi', '', NULL, '春日行 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d15ef6-edf4-4297-9d08-e9d36b1a4ffa', '春歸去', '春归去', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["九十春光在何處，古人今人留不住。","年年白眼向黔婁，唯放蠐螬飛上樹。"]', '["九十春光在何处，古人今人留不住。","年年白眼向黔婁，唯放蠐螬飞上樹。"]', '诗', 'shi', '', NULL, '春歸去 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b17dd7f-c703-45ae-897f-ca62f0e03717', '蜀葵詠', '蜀葵詠', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["綠衣宛地紅倡倡，熏風似舞諸女郎。","南鄰蕩子婦無賴，錦機春夜成文章。"]', '["綠衣宛地紅倡倡，熏风似舞諸女郎。","南鄰蕩子婦無賴，錦機春夜成文章。"]', '诗', 'shi', '', NULL, '蜀葵詠 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('468e6368-00c2-422d-b1d4-8fd0ebb8acfb', '南昌道中', '南昌道中', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["古道夤緣蔓黃葛，桓伊冢西春水闊。","村翁莫倚橫浦罾，一半魚蝦屬鵜獺。"]', '["古道夤緣蔓黄葛，桓伊冢西春水闊。","村翁莫倚橫浦罾，一半鱼蝦屬鵜獺。"]', '诗', 'shi', '', NULL, '南昌道中 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307d42e3-2f95-4dfc-a469-4a08738ec82c', '子規思', '子規思', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["春山杜鵑來幾日，夜啼南家復北家。","野人聽此坐惆悵，恐畏踏落東園花。"]', '["春山杜鵑来幾日，夜啼南家复北家。","野人听此坐惆悵，恐畏踏落东园花。"]', '诗', 'shi', '', NULL, '子規思 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e3326e0-8b8e-4a0a-a162-cfbf3757f91b', '吳興秋思二首 一', '吳兴秋思二首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["不是苕溪厭看月，天涯有程雲樹涼。","何意汀洲剩風雨，白蘋今日似瀟湘。"]', '["不是苕溪厭看月，天涯有程云樹涼。","何意汀洲剩风雨，白蘋今日似瀟湘。"]', '诗', 'shi', '', NULL, '吳興秋思二首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29f7aed-5128-4463-b9c3-154e83e3a8d5', '吳興秋思二首 二', '吳兴秋思二首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["日夕鯤魚夢南國，苕陽水高迷渡頭。","故山秋風憶歸去，白雲又被王孫留。"]', '["日夕鯤鱼梦南国，苕陽水高迷渡头。","故山秋风憶归去，白云又被王孫留。"]', '诗', 'shi', '', NULL, '吳興秋思二首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea2935e-ab8e-4259-baae-efe098ef0dab', '閩川夢歸', '閩川梦归', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["千里潺湲建溪路，夢魂一夕西歸去。","龍舼欲上巴獸灘，越王金雞報天曙。"]', '["千里潺湲建溪路，梦魂一夕西归去。","龙舼欲上巴獸灘，越王金雞報天曙。"]', '诗', 'shi', '', NULL, '閩川夢歸 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7d9705a-0ec0-4945-8982-e6003d7d2d53', '竹十一首 一', '竹十一首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["不壓東溪綠玉君，天壇雙鳳有時聞。","一峰曉似朝仙處，青節森森倚絳雲。"]', '["不壓东溪綠玉君，天壇雙鳳有时闻。","一峰晓似朝仙处，青節森森倚絳云。"]', '诗', 'shi', '', NULL, '竹十一首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('927b6a6c-2b50-4ad1-8467-3cbcd680b5ca', '竹十一首 二', '竹十一首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["萬枝朝露學瀟湘，杳靄孤亭白石涼。","誰道乖龍不得雨，春雷入地馬鞭狂。"]', '["万枝朝露学瀟湘，杳靄孤亭白石涼。","誰道乖龙不得雨，春雷入地马鞭狂。"]', '诗', 'shi', '', NULL, '竹十一首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('282a3c77-babe-4c3c-8faf-c8b74f6cfc0a', '竹十一首 三', '竹十一首 三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["嘯入新篁一里行，萬竿如罋鎖龍泓。","驚巢翡翠無尋處，閑倚雲根刻姓名。"]', '["嘯入新篁一里行，万竿如罋鎖龙泓。","驚巢翡翠無尋处，闲倚云根刻姓名。"]', '诗', 'shi', '', NULL, '竹十一首 三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0efa1b33-f3dd-4afe-a127-6f534d505e4e', '竹十一首 四', '竹十一首 四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["青嵐箒亞思吾祖，綠潤偏多憶蔡邕。","長聽南園風雨夜，恐生鱗甲盡爲龍。"]', '["青嵐箒亞思吾祖，綠潤偏多憶蔡邕。","长听南园风雨夜，恐生鱗甲尽爲龙。"]', '诗', 'shi', '', NULL, '竹十一首 四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7244c0a3-6347-4072-9827-e5ae6f210271', '竹十一首 五', '竹十一首 五', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["迸玉閑抽上釣磯，翠苗番次脫霞衣。","山童泥乞青騘馬，騎過春泉掣手飛。"]', '["迸玉闲抽上釣磯，翠苗番次脫霞衣。","山童泥乞青騘马，騎過春泉掣手飞。"]', '诗', 'shi', '', NULL, '竹十一首 五 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ed4b38-b4f3-4c25-9ba7-caed367da7fa', '竹十一首 六', '竹十一首 六', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["須題內史琅玕塢，幾醉山陽瑟瑟村。","剩養萬莖將掃俗，莫教凡鳥鬧雲門。"]', '["須題內史琅玕塢，幾醉山陽瑟瑟村。","剩養万莖將掃俗，莫教凡鸟鬧云门。"]', '诗', 'shi', '', NULL, '竹十一首 六 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1a1b688-394b-438d-aca6-8b5d1340acd4', '竹十一首 七', '竹十一首 七', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["一溪雲母間靈花，似到封侯逸士家。","誰識雌雄九成律，子喬丹井在深涯。"]', '["一溪云母间靈花，似到封侯逸士家。","誰識雌雄九成律，子喬丹井在深涯。"]', '诗', 'shi', '', NULL, '竹十一首 七 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73eb005e-9b7d-4ac7-bc79-f64fe00a32e5', '竹十一首 八', '竹十一首 八', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["燕燕雛時紫米香，野溪羞色過東牆。","諸兒莫抝成蹊筍，從結高籠養鳳皇。"]', '["燕燕雛时紫米香，野溪羞色過东牆。","諸兒莫抝成蹊筍，從結高籠養鳳皇。"]', '诗', 'shi', '', NULL, '竹十一首 八 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bdd1400-4d17-41d5-9f67-af9aa60ac8e5', '竹十一首 九', '竹十一首 九', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["一節呼龍萬里秋，數莖垂海六鼇愁。","更須瀑布峰前種，雲裏闌干過子猷。"]', '["一節呼龙万里秋，數莖垂海六鼇愁。","更須瀑布峰前種，云裏闌干過子猷。"]', '诗', 'shi', '', NULL, '竹十一首 九 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b029d4a-62be-4843-a8c4-b84277348d40', '竹十一首 十', '竹十一首 十', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["丘壑誰堪話碧鮮，靜尋春譜認嬋娟。","會當小殺青瑤簡，圖寫龜魚把上天。"]', '["丘壑誰堪話碧鲜，静尋春譜認嬋娟。","會當小殺青瑤簡，圖寫龟鱼把上天。"]', '诗', 'shi', '', NULL, '竹十一首 十 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa00f328-a2b0-450f-8546-9b704b109107', '竹十一首 十一', '竹十一首 十一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["玄圃千春閉玉叢，湛陽一祖碧雲空。","不須騷屑愁江島，今日南枝在國風。"]', '["玄圃千春閉玉叢，湛陽一祖碧云空。","不須騷屑愁江島，今日南枝在国风。"]', '诗', 'shi', '', NULL, '竹十一首 十一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ef6853f-291b-42bd-ba56-2752e69bfa84', '鍾陵秋夜', '鍾陵秋夜', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["洪崖嶺上秋月明，野客枕底章江清。","蓬壺宮闕不可夢，一一入樓歸鴈聲。"]', '["洪崖嶺上秋月明，野客枕底章江清。","蓬壺宮闕不可梦，一一入楼归鴈声。"]', '诗', 'shi', '', NULL, '鍾陵秋夜 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a143ea08-7e5a-4bc0-af7f-1a6e363f3cfa', '江上逢故人', '江上逢故人', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["十年蓬轉金陵道，長哭青雲身不早。","故鄉逢盡白頭人，清江顏色何曾老。"]', '["十年蓬轉金陵道，长哭青云身不早。","故乡逢尽白头人，清江顏色何曾老。"]', '诗', 'shi', '', NULL, '江上逢故人 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17ca598a-b70d-47e2-b7b5-38db6f21dd74', '水調詞十首 一', '水調词十首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["黠虜迢迢未肯和，五陵年少重橫戈。","誰家不結空閨恨，玉筯闌干妾最多。"]', '["黠虜迢迢未肯和，五陵年少重橫戈。","誰家不結空閨恨，玉筯闌干妾最多。"]', '诗', 'shi', '', NULL, '水調詞十首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e5d1996-d54d-4fcb-b51e-692fa820d440', '水調詞十首 二', '水調词十首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["羽管慵調怨別離，西園新月伴愁眉。","容華不分隨年去，獨有妝樓明鏡知。"]', '["羽管慵調怨別離，西园新月伴愁眉。","容华不分隨年去，独有妝楼明镜知。"]', '诗', 'shi', '', NULL, '水調詞十首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('150cd2bb-38e1-4fc9-8765-8e827c91b2d4', '水調詞十首 三', '水調词十首 三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["憶餞良人玉塞行，棃花三見換啼鶯。","邊場豈得勝閨閣，莫逞琱弓過一生。"]', '["憶餞良人玉塞行，棃花三见換啼鶯。","邊場豈得勝閨閣，莫逞琱弓過一生。"]', '诗', 'shi', '', NULL, '水調詞十首 三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17933df-0000-4e1b-a251-b78a6a50abf3', '水調詞十首 四', '水調词十首 四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["惆悵江南早鴈飛，年年辛苦寄寒衣。","征人豈不思鄉國，只是皇恩未放歸。"]', '["惆悵江南早鴈飞，年年辛苦寄寒衣。","征人豈不思乡国，只是皇恩未放归。"]', '诗', 'shi', '', NULL, '水調詞十首 四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de1daef-ff04-456d-a58b-da43312bc732', '水調詞十首 五', '水調词十首 五', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["水閣蓮開燕引雛，朝朝攀折望金吾。","聞道磧西春不到，花時還憶故園無。"]', '["水閣蓮开燕引雛，朝朝攀折望金吾。","闻道磧西春不到，花时還憶故园無。"]', '诗', 'shi', '', NULL, '水調詞十首 五 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421de69e-52ea-4335-803a-3759b0820d2d', '水調詞十首 六', '水調词十首 六', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["自從清野戍遼東，舞袖香銷羅幌空。","幾度長安發梅柳，節旄零落不成功。"]', '["自從清野戍遼东，舞袖香銷羅幌空。","幾度长安發梅柳，節旄零落不成功。"]', '诗', 'shi', '', NULL, '水調詞十首 六 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0329df7f-c528-49dc-b4e9-bd43c0c7c0c5', '水調詞十首 七', '水調词十首 七', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["長夜孤眠倦錦衾，秦樓霜月苦邊心。","征衣一倍裝綿厚，猶慮交河雪凍深。"]', '["长夜孤眠倦錦衾，秦楼霜月苦邊心。","征衣一倍裝綿厚，猶慮交河雪凍深。"]', '诗', 'shi', '', NULL, '水調詞十首 七 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43277fa3-544d-4234-99f2-2ffbcba58f7f', '水調詞十首 八', '水調词十首 八', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["瀚海長征古別離，華山歸馬是何時。","仍聞萬乘尊猶屈，裝束千嬌嫁郅支。"]', '["瀚海长征古別離，华山归马是何时。","仍闻万乘尊猶屈，裝束千嬌嫁郅支。"]', '诗', 'shi', '', NULL, '水調詞十首 八 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8570e2f3-f42b-4f4d-80dc-650465140ffd', '水調詞十首 九', '水調词十首 九', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["沙塞依稀落日邊，寒宵魂夢怯山川。","離居漸覺笙歌懶，君逐嫖姚已十年。"]', '["沙塞依稀落日邊，寒宵魂梦怯山川。","離居漸覺笙歌懶，君逐嫖姚已十年。"]', '诗', 'shi', '', NULL, '水調詞十首 九 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9cbb5b2-6cbf-4f5d-8cac-afe5dba70822', '水調詞十首 十', '水調词十首 十', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["萬里輪臺音信稀，傳聞移帳護金微。","會須麟閣留蹤跡，不斬天驕莫議歸。"]', '["万里輪台音信稀，傳闻移帳護金微。","會須麟閣留蹤跡，不斬天驕莫議归。"]', '诗', 'shi', '', NULL, '水調詞十首 十 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c300c91-a5d4-46d4-9e9f-003cb400dabd', '送謝山人歸江夏', '送謝山人归江夏', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["黃鶴春風二千里，山人佳期碧江水。","攜琴一醉楊柳堤，日暮龍沙白雲起。"]', '["黄鹤春风二千里，山人佳期碧江水。","携琴一醉楊柳堤，日暮龙沙白云起。"]', '诗', 'shi', '', NULL, '送謝山人歸江夏 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb79f715-948c-4287-a8c0-9d0b285e3b98', '閑居雜興五首 一', '闲居杂兴五首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["虞韶九奏音猶在，只是巴童自棄遺。","閑臥清秋憶師曠，好風搖動古松枝。"]', '["虞韶九奏音猶在，只是巴童自棄遺。","闲臥清秋憶師曠，好风搖动古松枝。"]', '诗', 'shi', '', NULL, '閑居雜興五首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caee9b1e-6397-458f-93a8-3069581324c1', '閑居雜興五首 二', '闲居杂兴五首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["一顧成周力有餘，白雲閑釣五溪魚。","中原莫道無麟鳳，自是皇家結網疎。"]', '["一顧成周力有餘，白云闲釣五溪鱼。","中原莫道無麟鳳，自是皇家結網疎。"]', '诗', 'shi', '', NULL, '閑居雜興五首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45c7e6c8-287a-420c-904d-fef200fc159a', '閑居雜興五首 三', '闲居杂兴五首 三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["長愛真人王子喬，五松山月伴吹簫。","從他浮世悲生死，獨駕蒼鱗入九霄。"]', '["长愛真人王子喬，五松山月伴吹簫。","從他浮世悲生死，独駕蒼鱗入九霄。"]', '诗', 'shi', '', NULL, '閑居雜興五首 三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4004a19-5622-4570-bd82-216ae67df6e4', '閑居雜興五首 四', '闲居杂兴五首 四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["越里娃童錦作襦，豔歌聲壓郢中姝。","無人說向張京兆，一曲江南十斛珠。"]', '["越里娃童錦作襦，豔歌声壓郢中姝。","無人说向張京兆，一曲江南十斛珠。"]', '诗', 'shi', '', NULL, '閑居雜興五首 四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58c484bb-6592-4df4-91e1-42450ab1fc65', '閑居雜興五首 五', '闲居杂兴五首 五', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["雲堆西望賊連營，分閫何當舉義兵。","莫道羔裘無壯節，古來成事盡書生。"]', '["云堆西望賊連營，分閫何當舉義兵。","莫道羔裘無壯節，古来成事尽书生。"]', '诗', 'shi', '', NULL, '閑居雜興五首 五 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aebbfd4-cff2-48fe-8d1c-8ceaaddae5b9', '泉州刺桐花詠兼呈趙使君 一', '泉州刺桐花詠兼呈趙使君 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["髣髴三株植世間，風光滿地赤城閑。","無因秉燭看奇樹，長伴劉公醉玉山。"]', '["髣髴三株植世间，风光满地赤城闲。","無因秉燭看奇樹，长伴劉公醉玉山。"]', '诗', 'shi', '', NULL, '泉州刺桐花詠兼呈趙使君 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b30e1b3-7424-4c07-a036-8f01074a80a5', '泉州刺桐花詠兼呈趙使君 二', '泉州刺桐花詠兼呈趙使君 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["海曲春深滿郡霞，越人多種刺桐花。","可憐虎竹西樓色，錦帳三千阿母家。"]', '["海曲春深满郡霞，越人多種刺桐花。","可怜虎竹西楼色，錦帳三千阿母家。"]', '诗', 'shi', '', NULL, '泉州刺桐花詠兼呈趙使君 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bc9d85-5fd4-419e-a716-ee6e48fc0aa6', '泉州刺桐花詠兼呈趙使君 三', '泉州刺桐花詠兼呈趙使君 三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["石氏金園無此豔，南都舊賦乏靈材。","只因赤帝宮中樹，丹鳳新銜出世來。"]', '["石氏金园無此豔，南都旧賦乏靈材。","只因赤帝宮中樹，丹鳳新銜出世来。"]', '诗', 'shi', '', NULL, '泉州刺桐花詠兼呈趙使君 三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea8c55bb-8c45-44f5-b3de-0e91c79921bd', '泉州刺桐花詠兼呈趙使君 四', '泉州刺桐花詠兼呈趙使君 四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["猗猗小豔夾通衢，晴日熏風笑越姝。","只是紅芳移不得，刺桐屏幛滿中都。"]', '["猗猗小豔夾通衢，晴日熏风笑越姝。","只是紅芳移不得，刺桐屏幛满中都。"]', '诗', 'shi', '', NULL, '泉州刺桐花詠兼呈趙使君 四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69ad96df-3617-41e7-abf2-d40d59178208', '泉州刺桐花詠兼呈趙使君 五', '泉州刺桐花詠兼呈趙使君 五', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["不勝攀折悵年華，紅樹南看見海涯。","故國春風歸去盡，何人堪寄一枝花。"]', '["不勝攀折悵年华，紅樹南看见海涯。","故国春风归去尽，何人堪寄一枝花。"]', '诗', 'shi', '', NULL, '泉州刺桐花詠兼呈趙使君 五 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06905273-6acf-47e0-b981-b79cbc74375d', '泉州刺桐花詠兼呈趙使君 六', '泉州刺桐花詠兼呈趙使君 六', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["赤帝常聞海上遊，三千幢蓋擁炎州。","今來樹似離宮色，紅翠斜欹十二樓。"]', '["赤帝常闻海上游，三千幢蓋擁炎州。","今来樹似離宮色，紅翠斜欹十二楼。"]', '诗', 'shi', '', NULL, '泉州刺桐花詠兼呈趙使君 六 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a4e3c6-191f-4b0c-bc70-b759cec9b899', '投贈福建桂常侍二首 一', '投贈福建桂常侍二首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["後來台席更何人，都護朝天拜近臣。","長笑當時漢卿士，等閑恩澤畫麒麟。"]', '["後来台席更何人，都護朝天拜近臣。","长笑當时漢卿士，等闲恩澤畫麒麟。"]', '诗', 'shi', '', NULL, '投贈福建桂常侍二首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1507c5-38f2-4197-a267-450bc7fbc3ee', '投贈福建桂常侍二首 二', '投贈福建桂常侍二首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["匝地歌鐘鎮海隅，城池鞅掌舊名都。","不知珠履三千外，更許侯嬴寄食無。"]', '["匝地歌鐘鎮海隅，城池鞅掌旧名都。","不知珠履三千外，更許侯嬴寄食無。"]', '诗', 'shi', '', NULL, '投贈福建桂常侍二首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd6333b-4da3-4c12-ac0e-e8496e3ce941', '隴西行四首 一', '隴西行四首 一', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["漢主東封報太平，無人金闕議邊兵。","縱饒奪得林胡塞，磧地桑麻種不生。"]', '["漢主东封報太平，無人金闕議邊兵。","縱饒奪得林胡塞，磧地桑麻種不生。"]', '诗', 'shi', '', NULL, '隴西行四首 一 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde30eaa-9b2c-47ce-ba49-c1356353ac9a', '隴西行四首 二', '隴西行四首 二', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["誓掃匈奴不顧身，五千貂錦喪胡塵。","可憐無定河邊骨，猶是春閨夢裏人。"]', '["誓掃匈奴不顧身，五千貂錦喪胡塵。","可怜無定河邊骨，猶是春閨梦裏人。"]', '诗', 'shi', '', NULL, '隴西行四首 二 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47a6add6-70a4-48bd-be0c-cef3c025b291', '隴西行四首 三', '隴西行四首 三', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["隴戍三看塞草青，樓煩新替護羌兵。","同來死者傷離別，一夜孤魂哭舊營。"]', '["隴戍三看塞草青，楼煩新替護羌兵。","同来死者傷離別，一夜孤魂哭旧營。"]', '诗', 'shi', '', NULL, '隴西行四首 三 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c37f2a0-d347-4267-abaf-2a5d610f9f9e', '隴西行四首 四', '隴西行四首 四', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["黠虜生擒未有涯，黑山營陣識龍蛇。","自從貴主和親後，一半胡風似漢家。"]', '["黠虜生擒未有涯，黑山營陣識龙蛇。","自從貴主和親後，一半胡风似漢家。"]', '诗', 'shi', '', NULL, '隴西行四首 四 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f4e294-e059-4970-b148-ca3f8b6d6061', '荅蓮花妓', '荅蓮花妓', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["近來詩思清於水，老去風情薄似雲。","已向昇天得門戶，錦衾深愧卓文君。"]', '["近来诗思清於水，老去风情薄似云。","已向昇天得门戶，錦衾深愧卓文君。"]', '诗', 'shi', '', NULL, '荅蓮花妓 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5b8455-3306-40d6-8161-3dd415642daa', '鏡道中吹簫', '镜道中吹簫', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["金欄白的善篸𥰭，雙鳳夜伴江南棲。","十洲人聽玉樓曉，空向千山桃杏枝。"]', '["金欄白的善篸𥰭，雙鳳夜伴江南棲。","十洲人听玉楼晓，空向千山桃杏枝。"]', '诗', 'shi', '', NULL, '鏡道中吹簫 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4728edda-ba59-4e42-ba55-f9ab9d51fa15', '贈野老', '贈野老', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["何年種芝白雲裏，人傳先生老萊子。","消磨世上名利心，澹若巖間一流水。"]', '["何年種芝白云裏，人傳先生老萊子。","消磨世上名利心，澹若巖间一流水。"]', '诗', 'shi', '', NULL, '贈野老 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab5d9b00-4c62-412c-a07e-6e0ddb741c9d', '酬元亨上人', '酬元亨上人', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["一衲淨居雲夢合，秋來詩思祝融高。","何因知我津涯闊，遠寄東溟六巨鼇。"]', '["一衲淨居云梦合，秋来诗思祝融高。","何因知我津涯闊，远寄东溟六巨鼇。"]', '诗', 'shi', '', NULL, '酬元亨上人 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9295c20-e37c-4167-b2b9-d522b44f799c', '題徐穉湖亭', '題徐穉湖亭', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["伏龍山橫洲渚地，人如白蘋自生死。","洪崖成道二千年，唯有徐君播青史。"]', '["伏龙山橫洲渚地，人如白蘋自生死。","洪崖成道二千年，唯有徐君播青史。"]', '诗', 'shi', '', NULL, '題徐穉湖亭 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8831f675-bb4e-4181-ba52-cfa5f0fa39c4', '鄱陽秋夕', '鄱陽秋夕', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["憶昔鄱陽旅遊日，曾聽南家爭擣衣。","今夜重開舊砧杵，當時還見鴈南飛。"]', '["憶昔鄱陽旅游日，曾听南家爭擣衣。","今夜重开旧砧杵，當时還见鴈南飞。"]', '诗', 'shi', '', NULL, '鄱陽秋夕 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c219ff22-9a89-487c-bf10-7c2ecf7695f6', '飛龍引', '飞龙引', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["長洲茂苑朝夕池，映日含風結細漪。","坐當伏檻紅蓮披，雕軒洞戶青蘋吹。","輕幌芳煙鬱金馥，綺簷花簟桃李枝。","苕苕翡翠但相逐，桂樹鴛鴦恆並宿。"]', '["长洲茂苑朝夕池，映日含风結細漪。","坐當伏檻紅蓮披，雕軒洞戶青蘋吹。","轻幌芳煙鬱金馥，綺簷花簟桃李枝。","苕苕翡翠但相逐，桂樹鴛鴦恆並宿。"]', '诗', 'shi', '', NULL, '飛龍引 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a73950b-e10d-4f0e-a6d2-e8b2a560e746', '句', '句', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["蟬聲將月短，草色與秋長。","比屋歌黃竹，何人撼白榆。","好看如鏡夜，莫笑似弓時。","江湖水清淺，不足掉鯨尾。","飲水狼子瘦，思日鷓鴣寒。","一鼎雄雌金液火，十年寒暑鹿麑裘。","寄語東流任斑鬢，向隅終守鐵梭飛。","乾坤見了文章懶，龍虎成來印綬疎。","近來世上無徐庶，誰向桑麻識臥龍。"]', '["蟬声將月短，草色與秋长。","比屋歌黄竹，何人撼白榆。","好看如镜夜，莫笑似弓时。","江湖水清淺，不足掉鯨尾。","饮水狼子瘦，思日鷓鴣寒。","一鼎雄雌金液火，十年寒暑鹿麑裘。","寄語东流任斑鬢，向隅終守鐵梭飞。","乾坤见了文章懶，龙虎成来印綬疎。","近来世上無徐庶，誰向桑麻識臥龙。"]', '诗', 'shi', '', NULL, '句 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d9d6022-cc59-4c99-a140-9718a3564111', '春日作', '春日作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["和氣來無象，物情還暗新。","乾坤一夕雨，草木萬方春。","染水煙光媚，催花鳥語頻。","高臺曠望處，歌詠屬詩人。"]', '["和氣来無象，物情還暗新。","乾坤一夕雨，草木万方春。","染水煙光媚，催花鸟語頻。","高台曠望处，歌詠屬诗人。"]', '诗', 'shi', '', NULL, '春日作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f122a99-c36f-482c-b858-736b0b379986', '寒江暮泊寄左偃', '寒江暮泊寄左偃', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["維舟蘆荻岸，離恨若爲寬。","煙火人家遠，汀洲暮雨寒。","天涯孤夢去，篷底一燈殘。","不是憑騷雅，相思寫亦難。"]', '["維舟蘆荻岸，離恨若爲寬。","煙火人家远，汀洲暮雨寒。","天涯孤梦去，篷底一灯殘。","不是憑騷雅，相思寫亦难。"]', '诗', 'shi', '', NULL, '寒江暮泊寄左偃 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b221764c-043a-4751-be60-edc77edcb54a', '喜春雨有寄', '喜春雨有寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["青春終日雨，公子莫思晴。","任阻西園會，且觀南畝耕。","最憐滋壠麥，不恨濕林鶯。","父老應相賀，豐年兆已成。"]', '["青春終日雨，公子莫思晴。","任阻西园會，且观南畝耕。","最怜滋壠麦，不恨濕林鶯。","父老應相賀，豐年兆已成。"]', '诗', 'shi', '', NULL, '喜春雨有寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ccd7362-c8c9-42bb-9cda-f245b7889f9d', '魏夫人壇', '魏夫人壇', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["仙壇遺跡在，苔合落花明。","絳節何年返，白雲終日生。","旋新芳草色，依舊偃松聲。","欲問希夷事，音塵隔上清。"]', '["仙壇遺跡在，苔合落花明。","絳節何年返，白云終日生。","旋新芳草色，依旧偃松声。","欲问希夷事，音塵隔上清。"]', '诗', 'shi', '', NULL, '魏夫人壇 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4415254-a2b8-4414-80da-61128681f056', '訪洞神宮邵道者不遇', '訪洞神宮邵道者不遇', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["閑來仙觀問希夷，雲滿星壇水滿池。","羽客不知何處去，洞前花落立多時。"]', '["闲来仙观问希夷，云满星壇水满池。","羽客不知何处去，洞前花落立多时。"]', '诗', 'shi', '', NULL, '訪洞神宮邵道者不遇 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a390e28-35a6-488a-9106-1ec0943f2f49', '寄贈致仕沈彬郎中', '寄贈致仕沈彬郎中', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["鶴氅換朝服，逍遙雲水鄉。","有時乘一葉，載酒入三湘。","塵夢年來息，詩魔老亦狂。","蓴羮與鱸鱠，秋興最宜長。"]', '["鹤氅換朝服，逍遙云水乡。","有时乘一葉，載酒入三湘。","塵梦年来息，诗魔老亦狂。","蓴羮與鱸鱠，秋兴最宜长。"]', '诗', 'shi', '', NULL, '寄贈致仕沈彬郎中 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ede339-e728-4295-9601-0eb9133afabd', '贈別', '贈別', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["行杯酌罷歌聲歇，不覺前汀月又生。","自是離人魂易斷，落花芳草本無情。"]', '["行杯酌罷歌声歇，不覺前汀月又生。","自是離人魂易斷，落花芳草本無情。"]', '诗', 'shi', '', NULL, '贈別 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('326951cb-3876-48e1-9c58-fca644dbd242', '送劉恭遊廬山兼寄令上人', '送劉恭游廬山兼寄令上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["松桂煙霞蔽梵宮，詩流閑去訪支公。","石堂磬斷相逢夜，五老月生谿影空。"]', '["松桂煙霞蔽梵宮，诗流闲去訪支公。","石堂磬斷相逢夜，五老月生谿影空。"]', '诗', 'shi', '', NULL, '送劉恭遊廬山兼寄令上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e0909ff-7722-4fee-a06b-6f22a0737b10', '宿廬山白雲峰重道者院', '宿廬山白云峰重道者院', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["絕頂松堂喜暫遊，一宵玄論接浮丘。","雲開碧落星河近，月出滄溟世界秋。","塵裏年光何急急，夢中強弱自悠悠。","他時書劒酬恩了，願逐鸞車看十洲。"]', '["絕頂松堂喜暫游，一宵玄論接浮丘。","云开碧落星河近，月出滄溟世界秋。","塵裏年光何急急，梦中強弱自悠悠。","他时书劒酬恩了，願逐鸾车看十洲。"]', '诗', 'shi', '', NULL, '宿廬山白雲峰重道者院 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57201b7e-a19b-4000-b0ce-35caf1a24e36', '海上從事秋日書懷', '海上從事秋日书懷', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["悠悠旅宦役塵埃，舊業那堪信未迴。","千里夢隨殘月斷，一聲蟬送早秋來。","壺傾濁酒終難醉，匣鎖青萍久不開。","唯有搜吟遣懷抱，涼風時復上高臺。"]', '["悠悠旅宦役塵埃，旧業那堪信未迴。","千里梦隨殘月斷，一声蟬送早秋来。","壺傾濁酒終难醉，匣鎖青萍久不开。","唯有搜吟遣懷抱，涼风时复上高台。"]', '诗', 'shi', '', NULL, '海上從事秋日書懷 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f71391-62a3-4109-838a-1a2929903cfd', '訪蔡文慶處士留題', '訪蔡文慶处士留題', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["幽人棲息處，一到滌塵心。","蘚色花陰闊，棊聲竹徑深。","籬根眠野鹿，池面戲江禽。","多謝相留宿，開樽拂素琴。"]', '["幽人棲息处，一到滌塵心。","蘚色花陰闊，棊声竹徑深。","籬根眠野鹿，池面戲江禽。","多謝相留宿，开樽拂素琴。"]', '诗', 'shi', '', NULL, '訪蔡文慶處士留題 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ca0b05-ec92-4d99-b55e-eec235cfa8c2', '寄廬岳鑒上人', '寄廬岳鑒上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["岳寺棲缾錫，常人親亦難。","病披青衲重，晚剃白髭寒。","烘壁茶煙暗，填溝木葉乾。","昔年皆禮謁，頻到碧雲端。"]', '["岳寺棲缾錫，常人親亦难。","病披青衲重，晚剃白髭寒。","烘壁茶煙暗，填溝木葉乾。","昔年皆禮謁，頻到碧云端。"]', '诗', 'shi', '', NULL, '寄廬岳鑒上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a18ce54-699e-42c8-adb8-a7716113f39c', '書小齋壁', '书小斋壁', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["其誰肯見尋，冷淡少知音。","塵土侵閑榻，煙波隔故林。","竹風醒晚醉，窗月伴秋吟。","道在唯求己，明時豈陸沈。"]', '["其誰肯见尋，冷淡少知音。","塵土侵闲榻，煙波隔故林。","竹风醒晚醉，窗月伴秋吟。","道在唯求己，明时豈陸沈。"]', '诗', 'shi', '', NULL, '書小齋壁 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f06949-6535-4ea0-8e09-71e7a9f1eb64', '懷王道者', '懷王道者', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["閑思王道者，逸格世難羣。","何處眠青嶂，從來愛白雲。","酒沽應獨醉，藥熟許誰分。","正作趨名計，如何得見君。"]', '["闲思王道者，逸格世难羣。","何处眠青嶂，從来愛白云。","酒沽應独醉，藥熟許誰分。","正作趨名計，如何得见君。"]', '诗', 'shi', '', NULL, '懷王道者 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba3b8ff-fc8f-4510-b3da-0b1325c008b2', '桃花', '桃花', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["祗應紅杏是知音，灼灼偏宜間竹陰。","幾樹半開金谷曉，一溪齊綻武陵深。","豔舒百葉時皆重，子熟千年事莫尋。","誰步宋牆明月下，好香和影上衣襟。"]', '["祗應紅杏是知音，灼灼偏宜间竹陰。","幾樹半开金谷晓，一溪齊綻武陵深。","豔舒百葉时皆重，子熟千年事莫尋。","誰步宋牆明月下，好香和影上衣襟。"]', '诗', 'shi', '', NULL, '桃花 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087e93b6-7045-45b1-a710-46fadf31b395', '思舊遊有感', '思旧游有感', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["長憶銜杯處，酕醄尚未闌。","江南正煙雨，樓上恰春寒。","好樹藏鶯密，平蕪徹野寬。","如今無處覓，音信隔波瀾。"]', '["长憶銜杯处，酕醄尚未闌。","江南正煙雨，楼上恰春寒。","好樹藏鶯密，平蕪徹野寬。","如今無处覓，音信隔波瀾。"]', '诗', 'shi', '', NULL, '思舊遊有感 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccadb49b-2e8f-4209-8148-7c6feb7cfeaf', '依韻和智謙上人送李相公赴昭武軍', '依韻和智謙上人送李相公赴昭武軍', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["暫別廟堂上，雄藩去豁情。","秋風生鴈渚，晚霧濕龍旌。","吟裏過侯服，夢中歸帝城。","下車軍庶樂，千里月華清。"]', '["暫別廟堂上，雄藩去豁情。","秋风生鴈渚，晚霧濕龙旌。","吟裏過侯服，梦中归帝城。","下车軍庶乐，千里月华清。"]', '诗', 'shi', '', NULL, '依韻和智謙上人送李相公赴昭武軍 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3850ecb-48d0-4a9a-bef8-fd3721fdcb4f', '姑蘇懷古 一', '姑蘇懷古 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["闔閭興霸日，繁盛復風流。","歌舞一場夢，煙波千古愁。","樵人歸野徑，漁笛起[扁]舟。","觸目牽傷感，將行又駐留。"]', '["闔閭兴霸日，繁盛复风流。","歌舞一場梦，煙波千古愁。","樵人归野徑，漁笛起[扁]舟。","觸目牽傷感，將行又駐留。"]', '诗', 'shi', '', NULL, '姑蘇懷古 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('564bf05d-6b31-42c9-961a-c1bd4603dab1', '姑蘇懷古 二', '姑蘇懷古 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["蘇臺蹤跡在，曠望向江濱。","往事誰堪問，連空草自春。","花疑西子臉，濤想伍胥神。","吟盡情難盡，斜陽照路塵。"]', '["蘇台蹤跡在，曠望向江濱。","往事誰堪问，連空草自春。","花疑西子臉，濤想伍胥神。","吟尽情难尽，斜陽照路塵。"]', '诗', 'shi', '', NULL, '姑蘇懷古 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('385d667b-d46d-4342-ae30-01a8c2103899', '贈史虛白', '贈史虛白', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["致主嘉謀尚未伸，慨然深志與誰論。","喚迴古意琴開匣，陶出真情酒滿樽。","明月過溪吟釣艇，落花堆席睡僧軒。","九重夢卜時終在，莫向深雲獨閉門。"]', '["致主嘉謀尚未伸，慨然深志與誰論。","喚迴古意琴开匣，陶出真情酒满樽。","明月過溪吟釣艇，落花堆席睡僧軒。","九重梦卜时終在，莫向深云独閉门。"]', '诗', 'shi', '', NULL, '贈史虛白 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58130c76-fb35-4e5a-9b02-3c2e8e013969', '贈蒯亮處士', '贈蒯亮处士', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["著得新書義更幽，負琴何處不遨遊。","玄宮寄宿月華冷，羽客伴吟松韻秋。","滿戶煙霞思紫閣，一帆風雨憶滄洲。","吾君側席求賢切，未可懸瓢枕碧流。"]', '["著得新书義更幽，負琴何处不遨游。","玄宮寄宿月华冷，羽客伴吟松韻秋。","满戶煙霞思紫閣，一帆风雨憶滄洲。","吾君側席求賢切，未可懸瓢枕碧流。"]', '诗', 'shi', '', NULL, '贈蒯亮處士 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d378f562-482b-4345-87e9-d9b8fceaf79d', '春夕偶作', '春夕偶作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["早是春愁觸目生，那堪春夕酒初醒。","貫珠聲罷人歸去，半落桃花月在庭。"]', '["早是春愁觸目生，那堪春夕酒初醒。","貫珠声罷人归去，半落桃花月在庭。"]', '诗', 'shi', '', NULL, '春夕偶作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba1f32d-23ba-4602-ada9-faf6322613b5', '子規', '子規', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["暮春滴血一聲聲，花落年年不忍聽。","帶月莫啼江畔樹，酒醒遊子在離亭。"]', '["暮春滴血一声声，花落年年不忍听。","带月莫啼江畔樹，酒醒游子在離亭。"]', '诗', 'shi', '', NULL, '子規 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9ff0b2-cde3-4499-b61b-b0acae7e05ca', '書王秀才壁', '书王秀才壁', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["茅舍何寥落，門庭長綠蕪。","貧來賣書劒，病起憶江湖。","對枕暮山碧，伴吟涼月孤。","前賢多晚達，莫歎有霜鬚。"]', '["茅舍何寥落，门庭长綠蕪。","貧来賣书劒，病起憶江湖。","对枕暮山碧，伴吟涼月孤。","前賢多晚達，莫歎有霜鬚。"]', '诗', 'shi', '', NULL, '書王秀才壁 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2364b919-1af6-4e89-acd6-65b3268bca16', '春日途中作', '春日途中作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["干祿趨名者，迢迢別故林。","春風短亭路，芳草異鄉心。","雨過江山出，鶯啼村落深。"]', '["干祿趨名者，迢迢別故林。","春风短亭路，芳草異乡心。","雨過江山出，鶯啼村落深。"]', '诗', 'shi', '', NULL, '春日途中作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed0c988c-7aee-4259-98ae-18b61d1bbccd', '依韻和蠡澤王去微秀才見寄', '依韻和蠡澤王去微秀才见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["咫尺風騷客，難諧面繼酬。","相思對煙雨，一鴈下汀洲。","花影誰家塢，笛聲何處樓？","搘筇朗吟罷，搔首獨遲留。"]', '["咫尺风騷客，难諧面繼酬。","相思对煙雨，一鴈下汀洲。","花影誰家塢，笛声何处楼？","搘筇朗吟罷，搔首独遲留。"]', '诗', 'shi', '', NULL, '依韻和蠡澤王去微秀才見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057a7a01-89bd-4cc5-b568-dbcaac3b7872', '送孫孔二秀才遊廬山', '送孫孔二秀才游廬山', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["廬山多勝景，偏稱二君遊。","松徑蒼苔合，花陰碧澗流。","傾壺同坐石，搜句共登樓。","莫學天台客，逢山即駐留。"]', '["廬山多勝景，偏稱二君游。","松徑蒼苔合，花陰碧澗流。","傾壺同坐石，搜句共登楼。","莫学天台客，逢山即駐留。"]', '诗', 'shi', '', NULL, '送孫孔二秀才遊廬山 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2baacc-573d-4a84-8213-5938f70ce2c9', '春日野望懷故人', '春日野望懷故人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["野外登臨望，蒼蒼煙景昏。","暖風醫病草，甘雨洗荒村。","雲散天邊野，潮迴島上痕。","故人不可見，倚杖役吟魂。"]', '["野外登臨望，蒼蒼煙景昏。","暖风醫病草，甘雨洗荒村。","云散天邊野，潮迴島上痕。","故人不可见，倚杖役吟魂。"]', '诗', 'shi', '', NULL, '春日野望懷故人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40b291d-149d-422b-a966-799b191e039e', '遊玄真觀', '游玄真观', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["閑吟遊古觀，靜慮想神仙。","上景非難度，陰功不易全。","醮壇松作蓋，丹井蘚成錢。","浩浩紅塵裏，誰來叩自然。"]', '["闲吟游古观，静慮想神仙。","上景非难度，陰功不易全。","醮壇松作蓋，丹井蘚成錢。","浩浩紅塵裏，誰来叩自然。"]', '诗', 'shi', '', NULL, '遊玄真觀 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece79d50-b2fe-4092-bff5-a788bdbb90da', '劒客', '劒客', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["恩酬期必報，豈是輙輕生。","神劒沖霄去，誰爲平不平。"]', '["恩酬期必報，豈是輙轻生。","神劒沖霄去，誰爲平不平。"]', '诗', 'shi', '', NULL, '劒客 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46ae552f-e210-4e0a-91e0-b46e8333fd92', '鶴', '鹤', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["警露精神異，沖天羽翼新。","千年一歸日，誰識令威身。"]', '["警露精神異，沖天羽翼新。","千年一归日，誰識令威身。"]', '诗', 'shi', '', NULL, '鶴 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e0b3ff4-6f11-492a-96f1-414198993fa2', '送致仕沈彬郎中遊茅山', '送致仕沈彬郎中游茅山', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["掛却朝冠披鶴氅，羽人相伴恣遨遊。","忽因風月思茅嶺，便挈琴樽上葉舟。","野寺宿時魂夢冷，海門吟處水雲秋。","華陽洞府年光永，莫向仙鄉擬駐留。"]', '["掛却朝冠披鹤氅，羽人相伴恣遨游。","忽因风月思茅嶺，便挈琴樽上葉舟。","野寺宿时魂梦冷，海门吟处水云秋。","华陽洞府年光永，莫向仙乡擬駐留。"]', '诗', 'shi', '', NULL, '送致仕沈彬郎中遊茅山 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c544431-6f42-415c-aaa2-e4b454c421f5', '題廬山東寺遠大師影堂', '題廬山东寺远大師影堂', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["遠公遺跡在東林，往事名存動苦吟。","杉檜已依靈塔老，煙霞空鎖影堂深。","入簾輕吹催香印，落石幽泉雜磬音。","十八賢人消息斷，蓮池千載月沈沈。"]', '["远公遺跡在东林，往事名存动苦吟。","杉檜已依靈塔老，煙霞空鎖影堂深。","入簾轻吹催香印，落石幽泉杂磬音。","十八賢人消息斷，蓮池千載月沈沈。"]', '诗', 'shi', '', NULL, '題廬山東寺遠大師影堂 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654a7a8f-f73c-4ecb-865c-56695d216920', '庭葦', '庭葦', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["品格清於竹，詩家景最幽。","從栽向池沼，長似在汀洲。","玩好招溪叟，棲堪待野鷗。","影疎當夕照，花亂正深秋。","韻細堪清耳，根牢好繫舟。","故溪高岸上，冷淡有誰遊。"]', '["品格清於竹，诗家景最幽。","從栽向池沼，长似在汀洲。","玩好招溪叟，棲堪待野鷗。","影疎當夕照，花亂正深秋。","韻細堪清耳，根牢好繫舟。","故溪高岸上，冷淡有誰游。"]', '诗', 'shi', '', NULL, '庭葦 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26ff256-4b77-4163-abb9-7437b9015850', '寄左偃', '寄左偃', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["每病風騷路，荒涼人莫遊。","惟君還似我，成癖未能休。","捨寐緣孤月，忘形爲九秋。","垂名如不朽，那恨雪生頭。"]', '["每病风騷路，荒涼人莫游。","惟君還似我，成癖未能休。","捨寐緣孤月，忘形爲九秋。","垂名如不朽，那恨雪生头。"]', '诗', 'shi', '', NULL, '寄左偃 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28e95d92-c9c6-49aa-af9e-15b363fe9b00', '宿山店書懷寄東林令圖上人', '宿山店书懷寄东林令圖上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["一宿山前店，旅情安可窮。","猨聲鄉夢後，月影竹窗中。","南楚征途闊，東吳舊業空。","虎溪蓮社客，應笑此飄蓬。"]', '["一宿山前店，旅情安可窮。","猨声乡梦後，月影竹窗中。","南楚征途闊，东吳旧業空。","虎溪蓮社客，應笑此飄蓬。"]', '诗', 'shi', '', NULL, '宿山店書懷寄東林令圖上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81966d11-a11b-450a-81e1-8ca64ac084e5', '途中聞子規', '途中闻子規', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["春殘杜宇愁，越客思悠悠。","雨歇孤村裏，花飛遠水頭。","微風聲漸咽，高樹血應流。","因此頻迴首，家山隔幾州。"]', '["春殘杜宇愁，越客思悠悠。","雨歇孤村裏，花飞远水头。","微风声漸咽，高樹血應流。","因此頻迴首，家山隔幾州。"]', '诗', 'shi', '', NULL, '途中聞子規 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07605b9b-e844-4dbd-be7f-0ca67982cee1', '春日書懷', '春日书懷', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["千峰雪盡鳥聲春，日永孤吟野水濱。","霄漢路岐昇未得，花時空拂滿衣塵。"]', '["千峰雪尽鸟声春，日永孤吟野水濱。","霄漢路岐昇未得，花时空拂满衣塵。"]', '诗', 'shi', '', NULL, '春日書懷 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d27526-c32c-48e5-8860-3c1e908c83ee', '所思代人', '所思代人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["巫峽雲深湘水遙，更無消息夢空勞。","夢迴深夜不成寐，起立閑庭花月高。"]', '["巫峽云深湘水遙，更無消息梦空勞。","梦迴深夜不成寐，起立闲庭花月高。"]', '诗', 'shi', '', NULL, '所思代人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b87a0fd7-5456-4809-9a1b-3efea7aa99ca', '春晚過明氏閑居', '春晚過明氏闲居', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["寥寥陋巷獨扃門，自樂清虛不厭貧。","數局棊中消永日，一罇酒裏送殘春。","雨催綠蘚鋪三徑，風送飛花入四鄰。","羨爾朗吟無外事，滄洲何必去垂綸。"]', '["寥寥陋巷独扃门，自乐清虛不厭貧。","數局棊中消永日，一罇酒裏送殘春。","雨催綠蘚鋪三徑，风送飞花入四鄰。","羨爾朗吟無外事，滄洲何必去垂綸。"]', '诗', 'shi', '', NULL, '春晚過明氏閑居 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf97d8c-0a1e-46d4-981d-0587c828aaad', '贈重安寂道者', '贈重安寂道者', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["寒松肌骨鶴心情，混俗陶陶隱姓名。","白髮只聞悲短景，紅塵誰解信長生。","壺中日月存心近，島外煙霞入夢清。","每許相親應計分，琴餘常見話蓬瀛。"]', '["寒松肌骨鹤心情，混俗陶陶隐姓名。","白髮只闻悲短景，紅塵誰解信长生。","壺中日月存心近，島外煙霞入梦清。","每許相親應計分，琴餘常见話蓬瀛。"]', '诗', 'shi', '', NULL, '贈重安寂道者 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98b7045-9c3e-453a-ad36-1cafab573603', '江邊吟', '江邊吟', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["風暖汀洲吟興生，遠山如畫雨新晴。","殘陽影裏水東注，芳草煙中人獨行。","閃閃酒帘招醉客，深深綠樹隱啼鶯。","盤桓漁舍忘歸去，雲靜高空月又明。"]', '["风暖汀洲吟兴生，远山如畫雨新晴。","殘陽影裏水东注，芳草煙中人独行。","閃閃酒帘招醉客，深深綠樹隐啼鶯。","盤桓漁舍忘归去，云静高空月又明。"]', '诗', 'shi', '', NULL, '江邊吟 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d683232d-58d8-4fd6-a299-472c97e7327c', '獻張義方常侍', '獻張義方常侍', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["雄飛看是逼嵓廊，逸思常聞不暫忘。","公署靜眠思水石，古屏閑展看瀟湘。","老來酒病雖然減，秋杪詩魔更是狂。","乘興有時招羽客，橫琴移月啓茅堂。"]', '["雄飞看是逼嵓廊，逸思常闻不暫忘。","公署静眠思水石，古屏闲展看瀟湘。","老来酒病雖然減，秋杪诗魔更是狂。","乘兴有时招羽客，橫琴移月啓茅堂。"]', '诗', 'shi', '', NULL, '獻張義方常侍 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('180e250e-042f-4674-afa0-cccde92ee6a2', '贈永真杜作翺少府', '贈永真杜作翺少府', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["藍袍竹簡佐琴堂，縣僻人稀覺日長。","愛靜不嫌官況冷，苦吟從聽鬢毛蒼。","閑尋野寺聽秋水，寄睡僧窗到夕陽。","騫翥會應霄漢去，漁竿休更戀滄浪。"]', '["藍袍竹簡佐琴堂，縣僻人稀覺日长。","愛静不嫌官況冷，苦吟從听鬢毛蒼。","闲尋野寺听秋水，寄睡僧窗到夕陽。","騫翥會應霄漢去，漁竿休更戀滄浪。"]', '诗', 'shi', '', NULL, '贈永真杜作翺少府 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0d318a3-6083-4ec9-adf5-9cbe7363ad79', '獻中書韓舍人', '獻中书韓舍人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["丹墀朝退後，靜院即冥搜。","盡日捲簾坐，前峰當檻秋。","烹茶留野客，展畫看滄洲。","見說東林夜，尋常秉燭遊。"]', '["丹墀朝退後，静院即冥搜。","尽日捲簾坐，前峰當檻秋。","烹茶留野客，展畫看滄洲。","见说东林夜，尋常秉燭游。"]', '诗', 'shi', '', NULL, '獻中書韓舍人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7191dd38-8aec-47c1-b27e-598dcaa2c5a5', '獻徐舍人', '獻徐舍人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["清名喧四海，何止並南金。","奧學羣英伏，多才萬乘欽。","秩參金殿峻，步歷紫微深。","顧聞承中旨，絲綸演帝心。","褒雄饒義路，賈馬避詞林。","下直無他事，開門對遠岑。","軒窗來晚吹，池沼歇秋霖。","蘚點生棊石，茶煙過竹陰。","希夷元已達，躁競豈能侵。","羽客閑陪飲，詩人伴靜吟。","自漸爲滯物，多幸辱虛襟。","此日重遭遇，心期出陸沈。"]', '["清名喧四海，何止並南金。","奧学羣英伏，多才万乘欽。","秩參金殿峻，步歷紫微深。","顧闻承中旨，絲綸演帝心。","褒雄饒義路，賈马避词林。","下直無他事，开门对远岑。","軒窗来晚吹，池沼歇秋霖。","蘚点生棊石，茶煙過竹陰。","希夷元已達，躁競豈能侵。","羽客闲陪饮，诗人伴静吟。","自漸爲滯物，多幸辱虛襟。","此日重遭遇，心期出陸沈。"]', '诗', 'shi', '', NULL, '獻徐舍人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e899591d-bb7a-4209-bf1a-7c5c55749926', '新秋有感', '新秋有感', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["門巷涼秋至，高梧一葉驚。","漸添衾簟爽，頓覺夢魂清。","暗促蓮開豔，乍催蟬發聲。","雨降炎氣減，竹引冷煙生。","戍客添歸思，行人怯遠程。","未逢征鴈下，漸聽夜砧鳴。","張翰思鱸興，班姬詠扇情。","音塵兩難問，蛩砌月空明。"]', '["门巷涼秋至，高梧一葉驚。","漸添衾簟爽，頓覺梦魂清。","暗促蓮开豔，乍催蟬發声。","雨降炎氣減，竹引冷煙生。","戍客添归思，行人怯远程。","未逢征鴈下，漸听夜砧鳴。","張翰思鱸兴，班姬詠扇情。","音塵兩难问，蛩砌月空明。"]', '诗', 'shi', '', NULL, '新秋有感 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d26194-7393-4297-a650-78bfcedc8a58', '秋雨', '秋雨', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["竟日散如絲，吟看半掩扉。","秋聲在梧葉，潤氣逼書幃。","曲澗泉承去，危簷燕帶歸。","寒蛩悲旅壁，亂蘚滑漁磯。","爽欲除幽簟，涼須換熟衣。","疎篷誰夢斷，荒徑獨遊稀。","偏稱江湖景，不妨鷗鷺飛。","最憐爲瑞處，南畝稻苗肥。"]', '["竟日散如絲，吟看半掩扉。","秋声在梧葉，潤氣逼书幃。","曲澗泉承去，危簷燕带归。","寒蛩悲旅壁，亂蘚滑漁磯。","爽欲除幽簟，涼須換熟衣。","疎篷誰梦斷，荒徑独游稀。","偏稱江湖景，不妨鷗鷺飞。","最怜爲瑞处，南畝稻苗肥。"]', '诗', 'shi', '', NULL, '秋雨 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b03fb1-6e91-4985-9c15-755aff294298', '寄廬山白大師', '寄廬山白大師', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["長憶尋師處，東林寓泊時。","一秋同看月，無夜不論詩。","泉美茶香異，堂深磬韻遲。","鹿馴眠蘚徑，猨苦叫霜枝。","別後音塵隔，年來鬢髮衰。","趨名方汲汲，未果再遊期。"]', '["长憶尋師处，东林寓泊时。","一秋同看月，無夜不論诗。","泉美茶香異，堂深磬韻遲。","鹿馴眠蘚徑，猨苦叫霜枝。","別後音塵隔，年来鬢髮衰。","趨名方汲汲，未果再游期。"]', '诗', 'shi', '', NULL, '寄廬山白大師 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('075bf3b1-2edf-4ed9-9960-4e9fba1ef812', '訪龍光智謙上人', '訪龙光智謙上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["忽起尋師興，穿雲不覺勞。","相留看山雪，盡日論風騷。","竹影搖禪榻，茶煙上毳袍。","夢魂曾去否，舊國阻波濤。"]', '["忽起尋師兴，穿云不覺勞。","相留看山雪，尽日論风騷。","竹影搖禪榻，茶煙上毳袍。","梦魂曾去否，旧国阻波濤。"]', '诗', 'shi', '', NULL, '訪龍光智謙上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac8f18a0-1079-4027-9ebb-46f8a1bb081e', '送仙客', '送仙客', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["危言危行是男兒，倚伏相牽豈足悲。","莫向汀洲時獨立，悠悠斜日照江蘺。"]', '["危言危行是男兒，倚伏相牽豈足悲。","莫向汀洲时独立，悠悠斜日照江蘺。"]', '诗', 'shi', '', NULL, '送仙客 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51f0cb3f-2d07-4e95-9159-f29296cf300a', '祀風師迎神曲', '祀风師迎神曲', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["太皥御氣，勾芒肇功。","蒼龍青旗，爰候祥風。","律以和應，□以感通。","鼎徂修蠁，時惟禮崇。"]', '["太皥御氣，勾芒肇功。","蒼龙青旗，爰候祥风。","律以和應，□以感通。","鼎徂修蠁，时惟禮崇。"]', '诗', 'shi', '', NULL, '祀風師迎神曲 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdde833e-af18-453a-9aa5-7a3c31ba5441', '柳二首 一', '柳二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["春來無樹不青青，似共東風別有情。","閑憶舊居湓水畔，數枝煙雨屬啼鶯。"]', '["春来無樹不青青，似共东风別有情。","闲憶旧居湓水畔，數枝煙雨屬啼鶯。"]', '诗', 'shi', '', NULL, '柳二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e5592b5-c16d-4fa7-aab3-69205bfe86b8', '柳二首 二', '柳二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["最愛青青水國中，莫愁門外間花紅。","纖纖無力勝春色，撼起啼鶯恨晚風。"]', '["最愛青青水国中，莫愁门外间花紅。","纖纖無力勝春色，撼起啼鶯恨晚风。"]', '诗', 'shi', '', NULL, '柳二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b150d27-5ccf-4408-833e-5301874e4651', '送廬阜僧歸山陽', '送廬阜僧归山陽', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["山陽舊社終經夢，容易言歸不可留。","瓶貯瀑泉離五老，錫搖江雨上孤舟。","魚行細浪分沙觜，鴈逆高風下葦洲。","遙想枚臯宅邊寺，不知涼月共誰遊。"]', '["山陽旧社終經梦，容易言归不可留。","瓶貯瀑泉離五老，錫搖江雨上孤舟。","鱼行細浪分沙觜，鴈逆高风下葦洲。","遙想枚臯宅邊寺，不知涼月共誰游。"]', '诗', 'shi', '', NULL, '送廬阜僧歸山陽 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e37f28fb-f90e-4c51-a43b-5bd15968d645', '投所知', '投所知', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["孤琴塵翳劒慵磨，自顧泥蟠欲奈何。","千里交親消息斷，一庭風雨夢魂多。","題橋未展相如志，叩角誰憐寧戚歌。","唯賴明公憐道在，敢攜蓑笠釣煙波。"]', '["孤琴塵翳劒慵磨，自顧泥蟠欲奈何。","千里交親消息斷，一庭风雨梦魂多。","題橋未展相如志，叩角誰怜寧戚歌。","唯賴明公怜道在，敢携蓑笠釣煙波。"]', '诗', 'shi', '', NULL, '投所知 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ada3a445-dc80-4cd4-8177-62975a5a6c1b', '寄左偃', '寄左偃', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["蕭條陋巷綠苔侵，何事君心似我心。","貧戶懶開元愛靜，病身纔起便思吟。","閑留好鳥庭柯密，暗養鳴蛩砌草深。","況是清朝重文物，無愁當路少知音。"]', '["蕭條陋巷綠苔侵，何事君心似我心。","貧戶懶开元愛静，病身纔起便思吟。","闲留好鸟庭柯密，暗養鳴蛩砌草深。","況是清朝重文物，無愁當路少知音。"]', '诗', 'shi', '', NULL, '寄左偃 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1710d52b-de53-45be-8f3b-807537428373', '遊北山洞神宮', '游北山洞神宮', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["悶見塵中光景促，仙鄉來禮紫陽君。","人居淡寂應難老，道在虛無不可聞。","松檜穩棲三島鶴，樓臺閑鎖九霄雲。","羨師向此朝星斗，一炷清香午夜焚。"]', '["悶见塵中光景促，仙乡来禮紫陽君。","人居淡寂應难老，道在虛無不可闻。","松檜穩棲三島鹤，楼台闲鎖九霄云。","羨師向此朝星斗，一炷清香午夜焚。"]', '诗', 'shi', '', NULL, '遊北山洞神宮 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e60c82c2-a8e4-4811-ac95-f716a9eeb9ad', '思簡寂觀舊遊寄重道者', '思簡寂观旧游寄重道者', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["閑憶當年遊物外，羽人曾許駐仙鄉。","溪頭烘藥煙霞暖，花下圍棊日月長。","偷摘蟠桃思曼倩，化成蝴蝶學蒙莊。","俗緣未斷歸浮世，空望林泉意欲狂。"]', '["闲憶當年游物外，羽人曾許駐仙乡。","溪头烘藥煙霞暖，花下圍棊日月长。","偷摘蟠桃思曼倩，化成蝴蝶学蒙莊。","俗緣未斷归浮世，空望林泉意欲狂。"]', '诗', 'shi', '', NULL, '思簡寂觀舊遊寄重道者 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ac136e-fe16-40e0-8667-3bb99135c6d8', '雲', '云', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["悠悠離洞壑，冉冉上天津。","捧日終爲異，從龍自有因。","高行四海雨，暖拂萬山春。","靜與霞相近，閑將鶴最親。","帝鄉歸莫問，楚殿夢曾頻。","白向封中起，碧從詩裏新。","冷容橫釣浦，輕縷絆蟾輪。","不滯濃還淡，無心卷復伸。","非煙聊擬議，干呂在逡巡。","會作五般色，爲祥覆紫宸。"]', '["悠悠離洞壑，冉冉上天津。","捧日終爲異，從龙自有因。","高行四海雨，暖拂万山春。","静與霞相近，闲將鹤最親。","帝乡归莫问，楚殿梦曾頻。","白向封中起，碧從诗裏新。","冷容橫釣浦，轻縷絆蟾輪。","不滯濃還淡，無心卷复伸。","非煙聊擬議，干呂在逡巡。","會作五般色，爲祥覆紫宸。"]', '诗', 'shi', '', NULL, '雲 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69420666-078b-4180-bd7f-bfadeed5afe8', '徐司徒池亭', '徐司徒池亭', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["亭榭跨池塘，泓澄入座涼。","扶疎皆竹柏，冷淡似瀟湘。","萍嫩鋪波面，苔深鎖岸傍。","朝迴遊不厭，僧到賞難忘。","最稱收殘雨，偏宜帶夕陽。","吟堪期謝朓，醉好命嵇康。","奢侈心難及，清虛趣最長。","月明垂釣興，何必憶滄浪。"]', '["亭榭跨池塘，泓澄入座涼。","扶疎皆竹柏，冷淡似瀟湘。","萍嫩鋪波面，苔深鎖岸傍。","朝迴游不厭，僧到賞难忘。","最稱收殘雨，偏宜带夕陽。","吟堪期謝朓，醉好命嵇康。","奢侈心难及，清虛趣最长。","月明垂釣兴，何必憶滄浪。"]', '诗', 'shi', '', NULL, '徐司徒池亭 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82d7d19-a280-43f2-8238-f2d11b46c83f', '賦得江邊草', '賦得江邊草', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["岸春芳草合，幾處思纏綿。","向暮江蘺雨，初晴杜若煙。","靜宜幽鷺立，遠稱碧波連。","送別王孫處，萋萋南浦邊。"]', '["岸春芳草合，幾处思纏綿。","向暮江蘺雨，初晴杜若煙。","静宜幽鷺立，远稱碧波連。","送別王孫处，萋萋南浦邊。"]', '诗', 'shi', '', NULL, '賦得江邊草 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee82159-14a8-4071-a264-5f61e2f18a02', '江行夜泊', '江行夜泊', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["扁舟倦行役，寂寂宿江干。","半夜風雷過，一天星斗寒。","潮平沙觜沒，霜苦鴈聲殘。","漁父何疎逸，扣舷歌未闌。"]', '["扁舟倦行役，寂寂宿江干。","半夜风雷過，一天星斗寒。","潮平沙觜沒，霜苦鴈声殘。","漁父何疎逸，扣舷歌未闌。"]', '诗', 'shi', '', NULL, '江行夜泊 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c53976-e13f-4116-97e0-bd5acfa57f33', '訪山叟留題', '訪山叟留題', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["策杖尋幽客，相攜入竹扃。","野雲生晚砌，病鶴立秋庭。","茶美睡心爽，琴清塵慮醒。","輪蹄應少到，門巷草青青。"]', '["策杖尋幽客，相携入竹扃。","野云生晚砌，病鹤立秋庭。","茶美睡心爽，琴清塵慮醒。","輪蹄應少到，门巷草青青。"]', '诗', 'shi', '', NULL, '訪山叟留題 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90955f1-bc2f-48b7-900d-11699e3ea91a', '江行晚泊寄湓城知友', '江行晚泊寄湓城知友', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["孤舟相憶久，何處倍關情。","野渡帆初落，秋風蟬一聲。","江浮殘照闊，雲散亂山橫。","漸去湓城遠，那堪新月生。"]', '["孤舟相憶久，何处倍关情。","野渡帆初落，秋风蟬一声。","江浮殘照闊，云散亂山橫。","漸去湓城远，那堪新月生。"]', '诗', 'shi', '', NULL, '江行晚泊寄湓城知友 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c212a3-6152-4539-b4a9-9d777fe41448', '秋夕書懷', '秋夕书懷', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["功名未立誠非晚，骨肉分飛又入秋。","枕上不堪殘夢斷，壁蛩窗月夜悠悠。"]', '["功名未立誠非晚，骨肉分飞又入秋。","枕上不堪殘梦斷，壁蛩窗月夜悠悠。"]', '诗', 'shi', '', NULL, '秋夕書懷 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f462fed5-9e09-4044-aed1-4f7736e8de32', '感興', '感兴', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["漁休渭水興周日，龍起南陽相蜀時。","不遇文王與先主，經天才業擬何爲。"]', '["漁休渭水兴周日，龙起南陽相蜀时。","不遇文王與先主，經天才業擬何爲。"]', '诗', 'shi', '', NULL, '感興 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5c9279-e6a7-488c-ae85-7baaac8b1a53', '舟中望九華山', '舟中望九华山', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["排空蒼翠異，輟櫂看崔嵬。","一面雨初歇，九峰雲正開。","當時思水石，便欲上樓臺。","隱去心難遂，吟餘首懶迴。","僧休傳紫閣，屏歇寫天臺。","中有忘機者，逍遙不可陪。"]', '["排空蒼翠異，輟櫂看崔嵬。","一面雨初歇，九峰云正开。","當时思水石，便欲上楼台。","隐去心难遂，吟餘首懶迴。","僧休傳紫閣，屏歇寫天台。","中有忘機者，逍遙不可陪。"]', '诗', 'shi', '', NULL, '舟中望九華山 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f1438e5-ce57-40d6-9901-7c41e3332198', '漁父', '漁父', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["煙冷暮江濱，高歌散誕身。","移舟過蓼岸，待月正絲綸。","亦與樵翁約，同遊酒市春。","白頭雲水上，不識獨醒人。"]', '["煙冷暮江濱，高歌散誕身。","移舟過蓼岸，待月正絲綸。","亦與樵翁約，同游酒市春。","白头云水上，不識独醒人。"]', '诗', 'shi', '', NULL, '漁父 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc161291-baef-4440-babb-e4dd7fe9e928', '贈上都紫極宮劉日新先生', '贈上都紫極宮劉日新先生', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["道德吾君重，含貞本去華。","因知鍊神骨，何必在煙霞。","棊散庭花落，詩成海月斜。","瀛洲舊仙侶，應許寄丹砂。"]', '["道德吾君重，含貞本去华。","因知鍊神骨，何必在煙霞。","棊散庭花落，诗成海月斜。","瀛洲旧仙侶，應許寄丹砂。"]', '诗', 'shi', '', NULL, '贈上都紫極宮劉日新先生 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4181e4e9-d92e-4448-b0fd-990a1f2715fd', '勉同志', '勉同志', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["讀書與磨劒，旦夕但忘疲。","儻若功名立，那愁變化遲。","塵從侵硯席，苔任滿庭墀。","明代搜揚切，升沈莫問龜。"]', '["读书與磨劒，旦夕但忘疲。","儻若功名立，那愁变化遲。","塵從侵硯席，苔任满庭墀。","明代搜揚切，升沈莫问龟。"]', '诗', 'shi', '', NULL, '勉同志 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ecfa07-7344-4187-bd06-6b791ae38faa', '寄劉鈞秀才', '寄劉鈞秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["掩戶當春晝，知君志在詩。","閑花半落處，幽客未來時。","野鳥穿莎徑，江雪過竹籬。","會須明月夜，與子水邊期。"]', '["掩戶當春晝，知君志在诗。","闲花半落处，幽客未来时。","野鸟穿莎徑，江雪過竹籬。","會須明月夜，與子水邊期。"]', '诗', 'shi', '', NULL, '寄劉鈞秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5eb66a-aeb7-408b-8fc0-3c9568090eb3', '離亭前思有寄', '離亭前思有寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["酒醒江亭客，纏綿恨別離。","笙歌筵散後，風月夜長時。","耿耿看燈暗，悠悠結夢遲。","若無騷雅分，何計達相思。"]', '["酒醒江亭客，纏綿恨別離。","笙歌筵散後，风月夜长时。","耿耿看灯暗，悠悠結梦遲。","若無騷雅分，何計達相思。"]', '诗', 'shi', '', NULL, '離亭前思有寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee10d325-2277-43e7-a65e-6d7f344f673f', '贈上都先業大師', '贈上都先業大師', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["懶向人前著紫衣，虛堂閑倚一條藜。","雖承雨露居龍闕，終憶煙霞夢虎溪。","睡起曉窗風淅淅，病來深院草萋萋。","有時乘興尋師去，煮茗同吟到日西。"]', '["懶向人前著紫衣，虛堂闲倚一條藜。","雖承雨露居龙闕，終憶煙霞梦虎溪。","睡起晓窗风淅淅，病来深院草萋萋。","有时乘兴尋師去，煮茗同吟到日西。"]', '诗', 'shi', '', NULL, '贈上都先業大師 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa85d525-22b2-4b56-9e83-fa05b5b87dfa', '思九江舊居三首 一', '思九江旧居三首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["結茅曾在碧江隈，多病貧身養拙來。","雨歇汀洲垂釣去，月當門巷訪僧迴。","靜臨窗下開琴匣，悶向牀頭潑酒醅。","遊宦等閑千里隔，空餘魂夢到漁臺。"]', '["結茅曾在碧江隈，多病貧身養拙来。","雨歇汀洲垂釣去，月當门巷訪僧迴。","静臨窗下开琴匣，悶向牀头潑酒醅。","游宦等闲千里隔，空餘魂梦到漁台。"]', '诗', 'shi', '', NULL, '思九江舊居三首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55b5a29-376b-4431-a79b-039e74f56aee', '思九江舊居三首 二', '思九江旧居三首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["門前煙水似瀟湘，放曠優游興味長。","虛閣靜眠聽遠浪，扁舟閑上泛殘陽。","鶴翹碧蘚庭除冷，竹引清風枕簟涼。","犬吠疎籬明月上，隣翁攜酒到茅堂。"]', '["门前煙水似瀟湘，放曠優游兴味长。","虛閣静眠听远浪，扁舟闲上泛殘陽。","鹤翹碧蘚庭除冷，竹引清风枕簟涼。","犬吠疎籬明月上，隣翁携酒到茅堂。"]', '诗', 'shi', '', NULL, '思九江舊居三首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c23d117-3e00-438f-8a8b-2e74e53ddb08', '思九江舊居三首 三', '思九江旧居三首 三', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["無機終日狎沙鷗，得意高吟景且幽。","檻底江流偏稱月，簷前山朵最宜秋。","遙村處處吹橫笛，曲岸家家繫小舟。","別後再遊心未遂，設屏惟畫白蘋洲。"]', '["無機終日狎沙鷗，得意高吟景且幽。","檻底江流偏稱月，簷前山朵最宜秋。","遙村处处吹橫笛，曲岸家家繫小舟。","別後再游心未遂，設屏惟畫白蘋洲。"]', '诗', 'shi', '', NULL, '思九江舊居三首 三 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e540ebb-b2b4-4904-bb80-1e3f7330dfb8', '贈東林白大師', '贈东林白大師', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["虎溪久駐靈蹤，禪外詩魔尚濃。","卷宿吟銷永日，移牀坐對千峰。","蒼苔冷鏁幽徑，微風閑坐古松。","自說年來老病，出門漸覺疎慵。"]', '["虎溪久駐靈蹤，禪外诗魔尚濃。","卷宿吟銷永日，移牀坐对千峰。","蒼苔冷鏁幽徑，微风闲坐古松。","自说年来老病，出门漸覺疎慵。"]', '诗', 'shi', '', NULL, '贈東林白大師 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1860069-039a-458e-bc8f-a0145550a09d', '春曉', '春晓', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["殘燭猶存月尚明，幾家幃幌夢魂驚。","星河漸沒行人動，歷歷林梢百舌聲。"]', '["殘燭猶存月尚明，幾家幃幌梦魂驚。","星河漸沒行人动，歷歷林梢百舌声。"]', '诗', 'shi', '', NULL, '春曉 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68403fac-9c8e-4fbb-97db-47a14797a0a5', '聽鄭羽人彈琴', '听鄭羽人彈琴', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["仙鄉景已清，仙子啓琴聲。","秋月空山寂，淳風一夜生。","莎間蟲罷響，松頂鶴初驚。","因感浮華世，誰憐太古情。"]', '["仙乡景已清，仙子啓琴声。","秋月空山寂，淳风一夜生。","莎间蟲罷响，松頂鹤初驚。","因感浮华世，誰怜太古情。"]', '诗', 'shi', '', NULL, '聽鄭羽人彈琴 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91c1082e-26de-48d2-b57b-2694d1d855a1', '秋夕書事寄友人', '秋夕书事寄友人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["信斷關河遠，相思秋夜深。","砌蛩聲咽咽，簷月影沈沈。","未遂青雲志，那堪素髮侵。","吟餘成不寐，徹曙四鄰砧。"]', '["信斷关河远，相思秋夜深。","砌蛩声咽咽，簷月影沈沈。","未遂青云志，那堪素髮侵。","吟餘成不寐，徹曙四鄰砧。"]', '诗', 'shi', '', NULL, '秋夕書事寄友人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c42bd45-384b-4d9c-8b5a-0134b1e1025f', '秋日途中', '秋日途中', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["竹林已蕭索，客思正如讎。","舊業吳江外，新蟬楚驛頭。","遙天疎雨過，列岫亂雲收。","今夕誰家宿，孤吟月色秋。"]', '["竹林已蕭索，客思正如讎。","旧業吳江外，新蟬楚驛头。","遙天疎雨過，列岫亂云收。","今夕誰家宿，孤吟月色秋。"]', '诗', 'shi', '', NULL, '秋日途中 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd5e46cf-fc24-470d-8ad5-60beb540c03a', '秋夜吟寄左偃', '秋夜吟寄左偃', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["與君詩興素來狂，況入清秋夜景長。","溪閣共誰看好月，莎堦應獨聽寒螿。","卷中新句誠堪喜，身外浮名不足忙。","會約垂名繼前哲，任他玄髮盡如霜。"]', '["與君诗兴素来狂，況入清秋夜景长。","溪閣共誰看好月，莎堦應独听寒螿。","卷中新句誠堪喜，身外浮名不足忙。","會約垂名繼前哲，任他玄髮尽如霜。"]', '诗', 'shi', '', NULL, '秋夜吟寄左偃 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('382ddc78-be7b-4a41-be97-57a47ffc799f', '竹', '竹', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["森森移得自山莊，植向空庭野興長。","便有好風來枕簟，更無閑夢到瀟湘。","蔭來砌蘚經疎雨，引下溪禽帶夕陽。","閑約羽人同賞處，安排棊局就清涼。"]', '["森森移得自山莊，植向空庭野兴长。","便有好风来枕簟，更無闲梦到瀟湘。","蔭来砌蘚經疎雨，引下溪禽带夕陽。","闲約羽人同賞处，安排棊局就清涼。"]', '诗', 'shi', '', NULL, '竹 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('385fe1e5-c9e6-4dbc-8e1e-98aa55d9da29', '懷廬岳舊遊寄劉鈞因感鑒上人', '懷廬岳旧游寄劉鈞因感鑒上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["昔年廬岳閑遊日，乘興因尋物外僧。","寄宿愛聽松葉雨，論詩惟對竹窗燈。","各拘片祿尋分別，高謝浮名竟未能。","一念支公安可見，影堂何處暮雲凝。"]', '["昔年廬岳闲游日，乘兴因尋物外僧。","寄宿愛听松葉雨，論诗惟对竹窗灯。","各拘片祿尋分別，高謝浮名竟未能。","一念支公安可见，影堂何处暮云凝。"]', '诗', 'shi', '', NULL, '懷廬岳舊遊寄劉鈞因感鑒上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b7339dc-2851-4406-b5be-4a56d8f3ea3a', '依韻酬智謙上人見寄', '依韻酬智謙上人见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["性拙才非逸，同心友亦稀。","風昏秋病眼，霜濕夜吟衣。","鶯谷期猶負，蘭陔養不違。","吾師惠佳句，勝得楚金歸。"]', '["性拙才非逸，同心友亦稀。","风昏秋病眼，霜濕夜吟衣。","鶯谷期猶負，蘭陔養不違。","吾師惠佳句，勝得楚金归。"]', '诗', 'shi', '', NULL, '依韻酬智謙上人見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5dbfc4f-340d-4d0f-8c9d-050d9e7a1fdb', '落花', '落花', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["年年三月暮，無計惜殘紅。","酷恨西園雨，生憎南陌風。","片隨流水遠，色逐斷霞空。","悵望叢林下，悠悠飲興窮。"]', '["年年三月暮，無計惜殘紅。","酷恨西园雨，生憎南陌风。","片隨流水远，色逐斷霞空。","悵望叢林下，悠悠饮兴窮。"]', '诗', 'shi', '', NULL, '落花 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acdc5dd4-8c1e-461b-af08-9c770b204310', '題柳', '題柳', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["折向離亭畔，春光滿手生。","群花豈無豔，柔質自多情。","夾岸籠溪月，兼風撼野鶯。","隋堤三月暮，飛絮想縱橫。"]', '["折向離亭畔，春光满手生。","群花豈無豔，柔質自多情。","夾岸籠溪月，兼风撼野鶯。","隋堤三月暮，飞絮想縱橫。"]', '诗', 'shi', '', NULL, '題柳 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('859d6868-9564-4647-86eb-4e1d01c6a2e6', '贈謙明上人', '贈謙明上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["雖寄上都眠竹寺，逸情終憶白雲端。","閑登鍾阜林泉晚，夢去沃洲風雨寒。","新試茶經煎有興，舊嬰詩病捨終難。","常聞秋夕多無寐，月在高臺獨憑欄。"]', '["雖寄上都眠竹寺，逸情終憶白云端。","闲登鍾阜林泉晚，梦去沃洲风雨寒。","新試茶經煎有兴，旧嬰诗病捨終难。","常闻秋夕多無寐，月在高台独憑欄。"]', '诗', 'shi', '', NULL, '贈謙明上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23354138-d189-4592-bf08-de8da5be0079', '書蔡隱士壁', '书蔡隐士壁', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["病後霜髭出，衡門寂寞中。","蠹侵書帙損，塵覆酒罇空。","池暗菰蒲雨，徑香蘭蕙風。","幽閑已得趣，不見卜窮通。"]', '["病後霜髭出，衡门寂寞中。","蠹侵书帙損，塵覆酒罇空。","池暗菰蒲雨，徑香蘭蕙风。","幽闲已得趣，不见卜窮通。"]', '诗', 'shi', '', NULL, '書蔡隱士壁 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3efb6a51-c126-4b8a-ae99-4f767be6b742', '贈鍾尊師遊茅山', '贈鍾尊師游茅山', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["笻杖擔琴背俗塵，路尋茅嶺有誰群。","仙翁物外應相遇，靈藥壺中必許分。","香入肌膚花洞酒，冷侵魂夢石牀雲。","伊予亦有朝修志，異日遨遊願見君。"]', '["笻杖擔琴背俗塵，路尋茅嶺有誰群。","仙翁物外應相遇，靈藥壺中必許分。","香入肌膚花洞酒，冷侵魂梦石牀云。","伊予亦有朝修志，異日遨游願见君。"]', '诗', 'shi', '', NULL, '贈鍾尊師遊茅山 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05cbc260-5e6c-4292-88fd-86ade243a9cf', '訪徐長史留題水閣', '訪徐长史留題水閣', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["君家池閣靜，一到且淹留。","坐聽蒹葭雨，如看島嶼秋。","杯盤深有興，吟笑迥忘憂。","更愛幽奇處，雙雙下野鷗。"]', '["君家池閣静，一到且淹留。","坐听蒹葭雨，如看島嶼秋。","杯盤深有兴，吟笑迥忘憂。","更愛幽奇处，雙雙下野鷗。"]', '诗', 'shi', '', NULL, '訪徐長史留題水閣 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f7e39f-e7be-40e2-a5a9-ef9ec1f3853f', '夕陽', '夕陽', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["影未沈山水面紅，遙天雨過促征鴻。","魂銷舉子不回首，閑照槐花驛路中。"]', '["影未沈山水面紅，遙天雨過促征鴻。","魂銷舉子不回首，闲照槐花驛路中。"]', '诗', 'shi', '', NULL, '夕陽 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc67c87-2f60-4e50-be11-a5224ef2a467', '鸂鶒', '鸂鶒', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["流品是鴛鴦，翻飛雲水鄉。","風高離極浦，煙暝下方塘。","比鷺行藏別，穿荷羽翼香。","雙雙浴輕浪，誰見在瀟湘。"]', '["流品是鴛鴦，翻飞云水乡。","风高離極浦，煙暝下方塘。","比鷺行藏別，穿荷羽翼香。","雙雙浴轻浪，誰见在瀟湘。"]', '诗', 'shi', '', NULL, '鸂鶒 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b93af1-390e-4fd0-97eb-59ea42f24836', '所思', '所思', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["離思春來切，誰能慰寂寥。","花飛寒食過，雲重楚山遙。","耿耿夢徒往，悠悠鬢易凋。","那堪對明月，獨立水邊橋。"]', '["離思春来切，誰能慰寂寥。","花飞寒食過，云重楚山遙。","耿耿梦徒往，悠悠鬢易凋。","那堪对明月，独立水邊橋。"]', '诗', 'shi', '', NULL, '所思 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee682ad0-691f-4e26-8f4c-3fd869dfbec1', '春閨辭二首 一', '春閨辞二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["卷簾遲日暖，睡起思沈沈。","遼海音塵遠，春風旅館深。","疎篁留鳥語，曲砌轉花陰。","寄語長征客，流年不易禁。"]', '["卷簾遲日暖，睡起思沈沈。","遼海音塵远，春风旅館深。","疎篁留鸟語，曲砌轉花陰。","寄語长征客，流年不易禁。"]', '诗', 'shi', '', NULL, '春閨辭二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de537bc-72a1-4f7d-8379-48a4c4545359', '春閨辭二首 二', '春閨辞二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["不得遼陽信，春心何以安。","鳥啼窗樹曉，夢斷碧煙殘。","綠鑑開還懶，紅顏駐且難。","相思誰可訴，時取舊書看。"]', '["不得遼陽信，春心何以安。","鸟啼窗樹晓，梦斷碧煙殘。","綠鑑开還懶，紅顏駐且难。","相思誰可訴，时取旧书看。"]', '诗', 'shi', '', NULL, '春閨辭二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b546e502-2411-4b18-9780-5c186a025ece', '臘中作', '臘中作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["冬至雖云遠，渾疑朔漠中。","勁風吹大野，密雪翳高空。","泉凍如頑石，人藏類蟄蟲。","豪家應不覺，獸炭滿爐紅。"]', '["冬至雖云远，渾疑朔漠中。","勁风吹大野，密雪翳高空。","泉凍如頑石，人藏類蟄蟲。","豪家應不覺，獸炭满爐紅。"]', '诗', 'shi', '', NULL, '臘中作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe85b38-7481-4336-9388-a36be9491978', '海城秋日書懷寄朐山孫明府', '海城秋日书懷寄朐山孫明府', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["槐柳蟬聲起渡頭，海城孤客思悠悠。","青雲展志知何日，皓月牽吟又入秋。","鑑裏漸生潘岳鬢，風前猶著卜商裘。","鳴琴良宰揮毫士，應笑蹉跎身未酬。"]', '["槐柳蟬声起渡头，海城孤客思悠悠。","青云展志知何日，皓月牽吟又入秋。","鑑裏漸生潘岳鬢，风前猶著卜商裘。","鳴琴良宰揮毫士，應笑蹉跎身未酬。"]', '诗', 'shi', '', NULL, '海城秋日書懷寄朐山孫明府 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb27edc6-ae5c-450c-9424-3a5d743c6d14', '題柴司徒亭假山', '題柴司徒亭假山', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["疊石峨峨象翠微，遠山魂夢便應稀。","從教蘚長添峰色，好引泉來作瀑飛。","螢影夜攢疑燒起，茶煙朝出認雲歸。","知君創得茲幽致，公退吟看到落暉。"]', '["叠石峨峨象翠微，远山魂梦便應稀。","從教蘚长添峰色，好引泉来作瀑飞。","螢影夜攢疑燒起，茶煙朝出認云归。","知君創得茲幽致，公退吟看到落暉。"]', '诗', 'shi', '', NULL, '題柴司徒亭假山 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7e142fa-a1c5-407e-a6b7-73220b5f4de1', '都下寒食夜作', '都下寒食夜作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["香塵未歇暝煙收，城滿笙歌事勝遊。","自是離人睡長早，千家簾卷月當樓。"]', '["香塵未歇暝煙收，城满笙歌事勝游。","自是離人睡长早，千家簾卷月當楼。"]', '诗', 'shi', '', NULL, '都下寒食夜作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afd6e4a6-9e5c-408b-a8a0-a6cf16d7473b', '客中春思', '客中春思', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["又聽黃鳥綿蠻，目斷家鄉未還。","春水引將客夢，悠悠遶遍關山。"]', '["又听黄鸟綿蠻，目斷家乡未還。","春水引將客梦，悠悠遶遍关山。"]', '诗', 'shi', '', NULL, '客中春思 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e156b68c-3a29-4bee-843d-3fe1c67e79a4', '所思', '所思', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["門掩殘花寂寂，簾垂斜月悠悠。","縱有一庭萱草，何曾與我忘憂。"]', '["门掩殘花寂寂，簾垂斜月悠悠。","縱有一庭萱草，何曾與我忘憂。"]', '诗', 'shi', '', NULL, '所思 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('074149c1-4f6e-4686-996f-afacb1f76200', '江館秋思因成自勉', '江館秋思因成自勉', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["江邊候館幽，汀鳥暝煙收。","客思雖悲月，詩魔又愛秋。","聲名都是幻，窮達未能憂。","散逸憐漁父，波中漾小舟。"]', '["江邊候館幽，汀鸟暝煙收。","客思雖悲月，诗魔又愛秋。","声名都是幻，窮達未能憂。","散逸怜漁父，波中漾小舟。"]', '诗', 'shi', '', NULL, '江館秋思因成自勉 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('082661da-b8c9-4c39-898f-952aad6bf4ad', '贈朐山楊宰', '贈朐山楊宰', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["訟閑徴賦畢，吏散卷簾時。","聽雨入秋竹，留僧覆舊棋。","得詩書落葉，煮茗汲寒池。","化俗功成後，煙霄會有期。"]', '["訟闲徴賦畢，吏散卷簾时。","听雨入秋竹，留僧覆旧棋。","得诗书落葉，煮茗汲寒池。","化俗功成後，煙霄會有期。"]', '诗', 'shi', '', NULL, '贈朐山楊宰 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('360a269e-67a7-446e-9790-2ec78c01e437', '廬山', '廬山', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["控厭潯陽景，崔嵬古及今。","勢雄超地表，翠盛接天心。","湓浦春煙列，星灣晚景沈。","圖經宜細覽，題詠卒難任。","靖節門遙對，庾公樓俯臨。","參差含積雪，隱映見歸禽。","峭拔推雙劒，清虛數二林。","白蓮池宛在，翠輦事難尋。","天近星河冷，龍歸洞穴深。","谷春攢錦繡，石潤疊瓊琳。","玄鶴傳仙拜，青猨伴客吟。","泉通九江遠，雲出幾州陰。","冬有靈湯溢，夏無炎暑侵。","他年如遂隱，五老是知音。"]', '["控厭潯陽景，崔嵬古及今。","勢雄超地表，翠盛接天心。","湓浦春煙列，星灣晚景沈。","圖經宜細覽，題詠卒难任。","靖節门遙对，庾公楼俯臨。","參差含積雪，隐映见归禽。","峭拔推雙劒，清虛數二林。","白蓮池宛在，翠輦事难尋。","天近星河冷，龙归洞穴深。","谷春攢錦繡，石潤叠瓊琳。","玄鹤傳仙拜，青猨伴客吟。","泉通九江远，云出幾州陰。","冬有靈湯溢，夏無炎暑侵。","他年如遂隐，五老是知音。"]', '诗', 'shi', '', NULL, '廬山 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecf8f63c-9794-4e44-b907-e464a191e5ee', '送孫霽書記赴壽陽[辟]命', '送孫霽书記赴壽陽[辟]命', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["辟命羨君赴，其如愴別情。","酒闌汀樹晚，帆展野風生。","淮靜寒煙歛，村遙夜火明。","醉沈朐嶺夢，吟達壽春城。","舊友搖鞭接，元戎掃榻迎。","雪晴蓮幕啓，雲散桂山橫。","王粲從軍畫，陳琳草檄名。","知君提健筆，重振此嘉聲。"]', '["辟命羨君赴，其如愴別情。","酒闌汀樹晚，帆展野风生。","淮静寒煙歛，村遙夜火明。","醉沈朐嶺梦，吟達壽春城。","旧友搖鞭接，元戎掃榻迎。","雪晴蓮幕啓，云散桂山橫。","王粲從軍畫，陳琳草檄名。","知君提健笔，重振此嘉声。"]', '诗', 'shi', '', NULL, '送孫霽書記赴壽陽[辟]命 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9da3de6-98aa-4268-9468-749c5424e519', '聽蟬寄朐山孫明府', '听蟬寄朐山孫明府', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["忽聽新蟬發，客情其奈何。","西風起槐柳，故國阻煙波。","壠笛悲猶少，巴猨恨未多。","不知陶靖節，還動此心麽。"]', '["忽听新蟬發，客情其奈何。","西风起槐柳，故国阻煙波。","壠笛悲猶少，巴猨恨未多。","不知陶靖節，還动此心麽。"]', '诗', 'shi', '', NULL, '聽蟬寄朐山孫明府 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d3435f-70b0-440e-8d00-4063b73e3bad', '秋江夜泊寄劉鈞正字', '秋江夜泊寄劉鈞正字', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["閑憶詩人思倍勞，維舟清夜泥風騷。","魚龍不動澄江遠，雲霧皆收皎月高。","潮滿釣舟迷浦嶼，霜繁野樹叫猨猱。","此時吟苦君知否，雙鬢從他有二毛。"]', '["闲憶诗人思倍勞，維舟清夜泥风騷。","鱼龙不动澄江远，云霧皆收皎月高。","潮满釣舟迷浦嶼，霜繁野樹叫猨猱。","此时吟苦君知否，雙鬢從他有二毛。"]', '诗', 'shi', '', NULL, '秋江夜泊寄劉鈞正字 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab54698-2d93-4e9c-bb69-faf2613ce866', '贈朐山孫明府', '贈朐山孫明府', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["縣庭無事似山齋，滿砌青青旋長苔。","閑撫素琴曹吏散，自烹新茗海僧來。","買將病鶴勞心養，移得閑花用意栽。","幾度訪君留我醉，甕香皆值酒新開。"]', '["縣庭無事似山斋，满砌青青旋长苔。","闲撫素琴曹吏散，自烹新茗海僧来。","買將病鹤勞心養，移得闲花用意栽。","幾度訪君留我醉，甕香皆值酒新开。"]', '诗', 'shi', '', NULL, '贈朐山孫明府 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa466916-e6d5-450d-b1b6-c74121f808a7', '贈海上書記張濟員外', '贈海上书記張濟員外', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["鵬霄休歎志難伸，貧病雖縈道且存。","阮瑀不能專筆硯，嵇康唯要樂琴尊。","春風滿院空欹枕，芳草侵堦獨閉門。","劒有塵埃書有蠹，昔年心事共誰論。"]', '["鵬霄休歎志难伸，貧病雖縈道且存。","阮瑀不能專笔硯，嵇康唯要乐琴尊。","春风满院空欹枕，芳草侵堦独閉门。","劒有塵埃书有蠹，昔年心事共誰論。"]', '诗', 'shi', '', NULL, '贈海上書記張濟員外 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9e6eef-e993-40a2-95b8-57120e743649', '對竹', '对竹', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["懶穿幽徑衝鳴鳥，忍踏清陰損翠苔。","不似閉門欹枕聽，秋聲如雨入軒來。"]', '["懶穿幽徑衝鳴鸟，忍踏清陰損翠苔。","不似閉门欹枕听，秋声如雨入軒来。"]', '诗', 'shi', '', NULL, '對竹 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe2febb-e787-46db-87a8-b5bb7106cd82', '送朐山孫明府赴壽陽幕府辟命', '送朐山孫明府赴壽陽幕府辟命', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["堪羨元戎虛右席，便承綸綍起金臺。","菊叢憔悴陶潛去，蓮幕光輝阮瑀來。","好向尊罍陳妙畫，定應書檄播雄才。","預愁別後相思處，月入閑窗遠夢迴。"]', '["堪羨元戎虛右席，便承綸綍起金台。","菊叢憔悴陶潛去，蓮幕光輝阮瑀来。","好向尊罍陳妙畫，定應书檄播雄才。","預愁別後相思处，月入闲窗远梦迴。"]', '诗', 'shi', '', NULL, '送朐山孫明府赴壽陽幕府辟命 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c51847-2082-4b1d-8a8c-4599a72e2066', '經廢宅', '經廢宅', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["一夢奢華去不還，斷牆花發豈堪看。","玉纖素綆知何處，金井梧枯碧甃寒。"]', '["一梦奢华去不還，斷牆花發豈堪看。","玉纖素綆知何处，金井梧枯碧甃寒。"]', '诗', 'shi', '', NULL, '經廢宅 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e0cb06-986e-45b8-b08e-9084b7b2ede7', '溪邊吟', '溪邊吟', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["鸂鶒雙飛下碧流，蓼花蘋穗正含秋。","茜裙二八採蓮去，笑衝微雨上蘭舟。"]', '["鸂鶒雙飞下碧流，蓼花蘋穗正含秋。","茜裙二八採蓮去，笑衝微雨上蘭舟。"]', '诗', 'shi', '', NULL, '溪邊吟 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ebb91b-2ab3-494c-8e47-525cf34e00c7', '得故人消息', '得故人消息', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["多難分離久，相思每淚垂。","夢歸殘月曉，信到落花時。","未必乖良會，何當有後期。","那堪樓上望，煙水接天涯。"]', '["多难分離久，相思每泪垂。","梦归殘月晓，信到落花时。","未必乖良會，何當有後期。","那堪楼上望，煙水接天涯。"]', '诗', 'shi', '', NULL, '得故人消息 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a23b5687-ede7-40df-800c-6752b97e92a5', '芳草', '芳草', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["二月正綿綿，離情被爾牽。","四鄰初過雨，萬里正鋪煙。","眷戀殘花惹，留連醉客眠。","飄香是杜若，最憶楚江邊。"]', '["二月正綿綿，離情被爾牽。","四鄰初過雨，万里正鋪煙。","眷戀殘花惹，留連醉客眠。","飄香是杜若，最憶楚江邊。"]', '诗', 'shi', '', NULL, '芳草 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('813878c5-ac35-43d2-ab52-f78f151f787f', '江南春', '江南春', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["千家事勝遊，景物可忘憂。","水國樓臺晚，春郊煙雨收。","鷓鴣啼竹樹，杜若媚汀洲。","永巷歌聲遠，王孫會莫愁。"]', '["千家事勝游，景物可忘憂。","水国楼台晚，春郊煙雨收。","鷓鴣啼竹樹，杜若媚汀洲。","永巷歌声远，王孫會莫愁。"]', '诗', 'shi', '', NULL, '江南春 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceacacbe-09d1-4dca-879f-68dff66da9ca', '悼亡', '悼亡', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["巷深芳草細，門靜綠楊低。","室邇人何處，花殘月又西。","武陵期已負，巫峽夢終迷。","獨立銷魂久，雙雙好鳥啼。"]', '["巷深芳草細，门静綠楊低。","室邇人何处，花殘月又西。","武陵期已負，巫峽梦終迷。","独立銷魂久，雙雙好鸟啼。"]', '诗', 'shi', '', NULL, '悼亡 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3726937b-39c5-4332-9ddc-6e06beabaf26', '春晏寄從弟德潤', '春晏寄從弟德潤', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["相思禁煙近，樓上動吟魂。","水國春寒在，人家暮雨昏。","朱橋通竹樹，香徑匝蘭蓀。","安得吾宗會，高歌醉一尊。"]', '["相思禁煙近，楼上动吟魂。","水国春寒在，人家暮雨昏。","朱橋通竹樹，香徑匝蘭蓀。","安得吾宗會，高歌醉一尊。"]', '诗', 'shi', '', NULL, '春晏寄從弟德潤 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b00256-df12-4aed-9f3c-0b524453791e', '贈致仕沈彬郎中', '贈致仕沈彬郎中', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["自言婚嫁畢，塵事不關心。","老去詩魔在，春來酒病深。","山翁期採藥，海月伴鳴琴。","多謝維舟處，相留接靜吟。"]', '["自言婚嫁畢，塵事不关心。","老去诗魔在，春来酒病深。","山翁期採藥，海月伴鳴琴。","多謝維舟处，相留接静吟。"]', '诗', 'shi', '', NULL, '贈致仕沈彬郎中 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35a41ef-9353-496c-ba82-3f1ca96cfee5', '憶溪居', '憶溪居', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["竹軒臨水靜無塵，別後鳧鷖入夢頻。","杜若菰蒲煙雨歇，一溪春色屬何人。"]', '["竹軒臨水静無塵，別後鳧鷖入梦頻。","杜若菰蒲煙雨歇，一溪春色屬何人。"]', '诗', 'shi', '', NULL, '憶溪居 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b672cad4-f5a9-42dc-b900-66f61ccd1459', '登下蔡縣樓', '登下蔡縣楼', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["長涯煙水又含秋，吏散時時獨上樓。","信斷蘭臺鄉國遠，依稀王粲在荆州。"]', '["长涯煙水又含秋，吏散时时独上楼。","信斷蘭台乡国远，依稀王粲在荆州。"]', '诗', 'shi', '', NULL, '登下蔡縣樓 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14910201-84b1-45db-97bd-7f18e69211c1', '下蔡春偶作', '下蔡春偶作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["旅館飄飄類斷蓬，悠悠心緒有誰同。","一宵風雨花飛後，萬里鄉關夢自通。","多難不堪容鬢改，沃愁惟怕酒杯空。","採蘭扇沈何時遂，洗慮焚香叩上穹。"]', '["旅館飄飄類斷蓬，悠悠心緒有誰同。","一宵风雨花飞後，万里乡关梦自通。","多难不堪容鬢改，沃愁惟怕酒杯空。","採蘭扇沈何时遂，洗慮焚香叩上穹。"]', '诗', 'shi', '', NULL, '下蔡春偶作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('946a5389-3292-45b1-908a-ce05b8faeddc', '再遊洞神宮懷邵羽人有感', '再游洞神宮懷邵羽人有感', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["重向煙蘿省舊遊，因尋遺跡想浮丘。","峰頭鶴去三清遠，壇畔月明千古秋。","泉落小池清復咽，雲從高嶠起還收。","自慙未得沖虛術，白髮無情漸滿頭。"]', '["重向煙蘿省旧游，因尋遺跡想浮丘。","峰头鹤去三清远，壇畔月明千古秋。","泉落小池清复咽，云從高嶠起還收。","自慙未得沖虛術，白髮無情漸满头。"]', '诗', 'shi', '', NULL, '再遊洞神宮懷邵羽人有感 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b32e9626-d13d-4b2a-b68f-51bedad2cc22', '秋雨二首 一', '秋雨二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["飄灑當窮巷，苔深落葉鋪。","送寒來客館，滴夢在庭梧。","逼砌蛩聲斷，侵窗竹影孤。","遙思漁叟興，蓑笠在江湖。"]', '["飄灑當窮巷，苔深落葉鋪。","送寒来客館，滴梦在庭梧。","逼砌蛩声斷，侵窗竹影孤。","遙思漁叟兴，蓑笠在江湖。"]', '诗', 'shi', '', NULL, '秋雨二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c874de-e656-477e-b161-b038703f299d', '秋雨二首 二', '秋雨二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["竟日聲蕭颯，兼風不暫闌。","竹窗秋睡美，荻浦夜漁寒。","地僻苔生易，林疎鳥宿難。","誰知苦吟者，坐聽一燈殘。"]', '["竟日声蕭颯，兼风不暫闌。","竹窗秋睡美，荻浦夜漁寒。","地僻苔生易，林疎鸟宿难。","誰知苦吟者，坐听一灯殘。"]', '诗', 'shi', '', NULL, '秋雨二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd98737-85a0-414f-902f-d32bfc6f7781', '經古觀有感', '經古观有感', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["古觀寥寥枕碧溪，偶思前事立殘暉。","漆園化蝶名空在，柱史猶龍去不歸。","丹井泉枯苔鎖合，醮壇松折鶴來稀。","回頭因歎浮生事，夢裏光陰疾若飛。"]', '["古观寥寥枕碧溪，偶思前事立殘暉。","漆园化蝶名空在，柱史猶龙去不归。","丹井泉枯苔鎖合，醮壇松折鹤来稀。","回头因歎浮生事，梦裏光陰疾若飞。"]', '诗', 'shi', '', NULL, '經古觀有感 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7aa01c-455b-4df7-be88-0960436d40cb', '吉水春暮訪蔡文慶處士留題', '吉水春暮訪蔡文慶处士留題', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["無事無憂鬢任蒼，濁醪閑酌送韶光。","溟濛雨過池塘暖，狼藉花飛硯席香。","好古未嘗疎典冊，懸圖時要看瀟湘。","戀君清話難留處，歸路迢迢又夕陽。"]', '["無事無憂鬢任蒼，濁醪闲酌送韶光。","溟濛雨過池塘暖，狼藉花飞硯席香。","好古未嘗疎典冊，懸圖时要看瀟湘。","戀君清話难留处，归路迢迢又夕陽。"]', '诗', 'shi', '', NULL, '吉水春暮訪蔡文慶處士留題 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b75c92-9143-473e-8e9e-4c1b9971feb9', '烈祖孝高挽歌二首 一', '烈祖孝高挽歌二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["誰解叩乾關，音容去不還。","位方尊北極，壽忽殞南山。","鳳輦應難問，龍髯不可攀。","千秋遺恨處，雲物鎖橋山。"]', '["誰解叩乾关，音容去不還。","位方尊北極，壽忽殞南山。","鳳輦應难问，龙髯不可攀。","千秋遺恨处，云物鎖橋山。"]', '诗', 'shi', '', NULL, '烈祖孝高挽歌二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d6a327-561a-42c5-96eb-7704f8cb42e8', '烈祖孝高挽歌二首 二', '烈祖孝高挽歌二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["仙馭歸何處，蒼蒼問且難。","華夷喧道德，陵壠葬衣冠。","御水穿城咽，宮花泣露寒。","九疑消息斷，空望白雲端。"]', '["仙馭归何处，蒼蒼问且难。","华夷喧道德，陵壠葬衣冠。","御水穿城咽，宮花泣露寒。","九疑消息斷，空望白云端。"]', '诗', 'shi', '', NULL, '烈祖孝高挽歌二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('273da384-9ce2-4801-a771-70ce779e831c', '贈海上觀音院文依上人', '贈海上观音院文依上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["煙霞海邊寺，高臥出門慵。","白日少來客，清風生古松。","虛窗從燕入，壞屐任苔封。","幾度陪師話，相留到暮鍾。"]', '["煙霞海邊寺，高臥出门慵。","白日少来客，清风生古松。","虛窗從燕入，壞屐任苔封。","幾度陪師話，相留到暮鍾。"]', '诗', 'shi', '', NULL, '贈海上觀音院文依上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a6df57-392c-49d0-b14f-6ae0373189cc', '秋夕病中作', '秋夕病中作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["臥病當秋夕，悠悠枕上情。","不堪拋月色，無計避蟲聲。","煎藥惟憂澁，停燈又怕明。","曉臨清鑑裏，應有白髭生。"]', '["臥病當秋夕，悠悠枕上情。","不堪拋月色，無計避蟲声。","煎藥惟憂澁，停灯又怕明。","晓臨清鑑裏，應有白髭生。"]', '诗', 'shi', '', NULL, '秋夕病中作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4174f43-2ab1-449c-8fcc-1dc4deb27124', '寄黃鶚秀才', '寄黄鶚秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["長憶狂遊日，惜春心恰同。","預愁花片落，不遣酒壺空。","草軟眠難捨，鶯嬌聽莫窮。","如今千里隔，騷首對秋風。"]', '["长憶狂游日，惜春心恰同。","預愁花片落，不遣酒壺空。","草軟眠难捨，鶯嬌听莫窮。","如今千里隔，騷首对秋风。"]', '诗', 'shi', '', NULL, '寄黃鶚秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5bc934a-64fa-40cb-8978-9d94f2dfacdb', '春日書懷寄朐山孫明府', '春日书懷寄朐山孫明府', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["一作邊城客，閑門兩度春。","鶯花深院雨，書劒滿牀塵。","紫閣期終負，青雲道未伸。","猶憐陶靖節，詩酒每相親。"]', '["一作邊城客，闲门兩度春。","鶯花深院雨，书劒满牀塵。","紫閣期終負，青云道未伸。","猶怜陶靖節，诗酒每相親。"]', '诗', 'shi', '', NULL, '春日書懷寄朐山孫明府 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36ab51b-0cd7-433f-b68e-067042aaa53f', '柴司徒宅牡丹', '柴司徒宅牡丹', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["暮春欄檻有佳期，公子開顏乍拆時。","翠幄密籠鶯未識，好香難掩蝶先知。","願陪妓女爭調樂，欲賞賓朋預課詩。","只恐却隨雲雨去，隔年還是動相思。"]', '["暮春欄檻有佳期，公子开顏乍拆时。","翠幄密籠鶯未識，好香难掩蝶先知。","願陪妓女爭調乐，欲賞賓朋預課诗。","只恐却隨云雨去，隔年還是动相思。"]', '诗', 'shi', '', NULL, '柴司徒宅牡丹 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc8a87a7-611e-4773-bbbe-f7ac89e318bc', '贈王道者', '贈王道者', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["混俗從教鬢似銀，世人無分得相親。","槎流海上波濤闊，酒滿壺中天地春。","功就不看丹竈火，性閑時拂玉琴塵。","仙家變化誰能測，只恐洪崖是此身。"]', '["混俗從教鬢似銀，世人無分得相親。","槎流海上波濤闊，酒满壺中天地春。","功就不看丹竈火，性闲时拂玉琴塵。","仙家变化誰能測，只恐洪崖是此身。"]', '诗', 'shi', '', NULL, '贈王道者 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5728ceb6-d26a-43fe-a354-4c228c91a386', '春閨辭二首 一', '春閨辞二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["塵昏菱鑑懶修容，雙臉桃花落盡紅。","玉塞夢歸殘燭在，曉鶯窗外囀梧桐。"]', '["塵昏菱鑑懶修容，雙臉桃花落尽紅。","玉塞梦归殘燭在，晓鶯窗外囀梧桐。"]', '诗', 'shi', '', NULL, '春閨辭二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4243b281-f54f-423a-b018-608dd9a77efa', '春閨辭二首 二', '春閨辞二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["邊無音信暗消魂，茜袖香裙積淚痕。","海燕歸來門未掩，悠悠花落又黃昏。"]', '["邊無音信暗消魂，茜袖香裙積泪痕。","海燕归来门未掩，悠悠花落又黄昏。"]', '诗', 'shi', '', NULL, '春閨辭二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b3fdf19-ad86-4eba-83b9-131995950134', '暮春懷故人', '暮春懷故人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["池館寂寥三月盡，落花重疊蓋莓苔。","惜春眷戀不忍掃，感物心情無計開。","夢斷美人沈信息，目穿長路倚樓臺。","琅玕繡段安可得，流水浮雲共不迴。"]', '["池館寂寥三月尽，落花重叠蓋莓苔。","惜春眷戀不忍掃，感物心情無計开。","梦斷美人沈信息，目穿长路倚楼台。","琅玕繡段安可得，流水浮云共不迴。"]', '诗', 'shi', '', NULL, '暮春懷故人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ecfb57b-64d9-47d1-8bd4-a2f074c4a410', '秋日登潤州城樓', '秋日登潤州城楼', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["虛樓一望極封疆，積雨晴來野景長。","水接海門鋪遠色，稻連京口發秋香。","鳴蟬歷歷空相續，歸鳥翩翩自著行。","吟罷倚欄深有思，清風留我到斜陽。"]', '["虛楼一望極封疆，積雨晴来野景长。","水接海门鋪远色，稻連京口發秋香。","鳴蟬歷歷空相續，归鸟翩翩自著行。","吟罷倚欄深有思，清风留我到斜陽。"]', '诗', 'shi', '', NULL, '秋日登潤州城樓 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6acae7e6-08f9-4d3d-8583-c2176a1e7d91', '晚春客次偶吟', '晚春客次偶吟', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["暫駐征輪野店間，悠悠時節又春殘。","落花風急宿酲解，芳草雨昏春夢寒。","慙逐利名頭易白，欲眠雲水志猶難。","却憐村寺僧相引，閑上虛樓共倚欄。"]', '["暫駐征輪野店间，悠悠时節又春殘。","落花风急宿酲解，芳草雨昏春梦寒。","慙逐利名头易白，欲眠云水志猶难。","却怜村寺僧相引，闲上虛楼共倚欄。"]', '诗', 'shi', '', NULL, '晚春客次偶吟 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c440c023-a648-4596-a2ad-7b5b101709ed', '對雨寄朐山林番明府', '对雨寄朐山林番明府', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["竟日如絲不暫停，莎堦閑聽滴秋聲。","斜飄虛閣琴書潤，冷逼幽窗夢寐清。","開戶只添搜句味，看山還阻上樓情。","遙知公退琴堂靜，坐對蕭騷飲興生。"]', '["竟日如絲不暫停，莎堦闲听滴秋声。","斜飄虛閣琴书潤，冷逼幽窗梦寐清。","开戶只添搜句味，看山還阻上楼情。","遙知公退琴堂静，坐对蕭騷饮兴生。"]', '诗', 'shi', '', NULL, '對雨寄朐山林番明府 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f00378-fea5-4f11-a9f7-221b106d422f', '落花', '落花', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["殘紅引動詩魔，懷古牽情奈何。","半落銅臺月曉，亂飄金谷風多。","悠悠旋逐流水，片片輕黏短莎。","誰見長門深鎖，黃昏細雨相和。"]', '["殘紅引动诗魔，懷古牽情奈何。","半落銅台月晓，亂飄金谷风多。","悠悠旋逐流水，片片轻黏短莎。","誰见长门深鎖，黄昏細雨相和。"]', '诗', 'shi', '', NULL, '落花 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91643007-11c7-46ff-b178-27abc7fc0c8f', '燕', '燕', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["豪家五色泥香，銜得營巢太忙。","喧覺佳人晝夢，雙雙猶在雕梁。"]', '["豪家五色泥香，銜得營巢太忙。","喧覺佳人晝梦，雙雙猶在雕梁。"]', '诗', 'shi', '', NULL, '燕 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('523ca0c5-fd46-4ab7-bd37-38dbe0b42c33', '鶯', '鶯', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["羽毛特異諸禽，出谷堪聽好音。","薄暮欲棲何處，雨昏楊柳深深。"]', '["羽毛特異諸禽，出谷堪听好音。","薄暮欲棲何处，雨昏楊柳深深。"]', '诗', 'shi', '', NULL, '鶯 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130c6ef8-0816-4235-b7df-844c78d59c1c', '宿山中寺', '宿山中寺', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["寄宿深山寺，惟逢老病僧。","風吹幾世樹，雲暗暮秋燈。","瞑目忘塵慮，談空入上乘。","明晨返名路，何計戀南能。"]', '["寄宿深山寺，惟逢老病僧。","风吹幾世樹，云暗暮秋灯。","瞑目忘塵慮，談空入上乘。","明晨返名路，何計戀南能。"]', '诗', 'shi', '', NULL, '宿山中寺 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('020110e9-fdd2-49a4-9c49-9c0b6e76efa6', '海上載筆依韻酬左偃見寄', '海上載笔依韻酬左偃见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["都城分別後，海嶠夢魂迷。","吟興疎煙月，邊情起鼓鼙。","戍旗風颭小，營柳霧籠低。","草檄無餘刃，難將阮瑀齊。"]', '["都城分別後，海嶠梦魂迷。","吟兴疎煙月，邊情起鼓鼙。","戍旗风颭小，營柳霧籠低。","草檄無餘刃，难將阮瑀齊。"]', '诗', 'shi', '', NULL, '海上載筆依韻酬左偃見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c99e62-f25d-41f5-802d-b292c930f9ef', '春晚招魯從事', '春晚招魯從事', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["衮衮利名役，常嗟聚會稀。","有心遊好景，無術駐殘暉。","南陌草爭茂，西園花亂飛。","期君舉杯酒，不醉莫言歸。"]', '["衮衮利名役，常嗟聚會稀。","有心游好景，無術駐殘暉。","南陌草爭茂，西园花亂飞。","期君舉杯酒，不醉莫言归。"]', '诗', 'shi', '', NULL, '春晚招魯從事 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b7dfb70-c85d-4543-8461-cf258bae0e81', '和易秀才春日見寄', '和易秀才春日见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["每恨多流落，吾徒不易親。","相逢千里客，共醉百花春。","小檻山當面，閑堦柳拂塵。","何時卜西上，明月桂枝新。"]', '["每恨多流落，吾徒不易親。","相逢千里客，共醉百花春。","小檻山當面，闲堦柳拂塵。","何时卜西上，明月桂枝新。"]', '诗', 'shi', '', NULL, '和易秀才春日見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('317b790e-780e-44e5-a131-990b36c16088', '送黃秀才', '送黄秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["雨餘飛絮亂，相別思難任。","酒罷河橋晚，帆開煙水深。","蟾宮須展志，漁艇莫牽心。","岐路從茲遠，雙魚信勿沈。"]', '["雨餘飞絮亂，相別思难任。","酒罷河橋晚，帆开煙水深。","蟾宮須展志，漁艇莫牽心。","岐路從茲远，雙鱼信勿沈。"]', '诗', 'shi', '', NULL, '送黃秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0860da79-2b6f-485e-ba23-775d5bf9dbb5', '庭竹', '庭竹', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["偶自山僧院，移歸傍砌栽。","好風終日起，幽鳥有時來。","篩月牽詩興，籠煙伴酒杯。","南窗睡輕起，蕭颯雨聲迴。"]', '["偶自山僧院，移归傍砌栽。","好风終日起，幽鸟有时来。","篩月牽诗兴，籠煙伴酒杯。","南窗睡轻起，蕭颯雨声迴。"]', '诗', 'shi', '', NULL, '庭竹 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4601f286-cad7-4f76-86d9-79fd39578aec', '送戴秀才', '送戴秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["已是殊鄉客，送君重慘然。","河橋乍分首，槐柳正鳴蟬。","短櫂離幽浦，孤帆觸遠煙。","清朝重文物，變化莫遷延。"]', '["已是殊乡客，送君重慘然。","河橋乍分首，槐柳正鳴蟬。","短櫂離幽浦，孤帆觸远煙。","清朝重文物，变化莫遷延。"]', '诗', 'shi', '', NULL, '送戴秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c41d63e5-7f9b-45df-a6cf-e5e8e9b38b38', '病中作', '病中作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["閑齋病初起，心緒復悠悠。","開篋羣書蠹，聽蟬滿樹秋。","詩魔還漸動，藥債未能酬。","爲憶前山色，扶持上小樓。"]', '["闲斋病初起，心緒复悠悠。","开篋羣书蠹，听蟬满樹秋。","诗魔還漸动，藥債未能酬。","爲憶前山色，扶持上小楼。"]', '诗', 'shi', '', NULL, '病中作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a965aa6-241d-41d3-8a27-0904efde8e04', '離家', '離家', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["送別人歸春日斜，獨鞭羸馬指天涯。","月生江上鄉心動，投宿怱忙近酒家。"]', '["送別人归春日斜，独鞭羸马指天涯。","月生江上乡心动，投宿怱忙近酒家。"]', '诗', 'shi', '', NULL, '離家 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5cbbb6-8494-4c89-ae8c-73e141ba540e', '村行', '村行', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["極目青青壠麥齊，野塘波闊下鳧鷖。","陽烏景暖林桑密，獨立閑聽戴勝啼。"]', '["極目青青壠麦齊，野塘波闊下鳧鷖。","陽烏景暖林桑密，独立闲听戴勝啼。"]', '诗', 'shi', '', NULL, '村行 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75feca6f-3ff9-4b84-bcff-6994bfe04285', '獻喬侍郎', '獻喬侍郎', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["位望誰能並，當年志已伸。","人間傳鳳藻，天上演龍綸。","賈馬才無敵，褒雄譽益臻。","除奸深繫念，致主迥忘身。","諫疏縱橫上，危言果敢陳。","忠貞雖貫世，消長豈由人。","慷慨辭朝闕，迢遙涉路塵。","千山明夕照，孤櫂渡長津。","杜宇聲方切，江蘺色正新。","卷舒唯合道，喜慍不勞神。","蟬客陪清論，漁翁作近鄰。","靜吟窮野景，狂醉養天真。","格論思名士，輿情渴直臣。","九霄恩復降，比戶意皆忻。","却入鴛鸞序，終身顧問頻。","漏殘丹禁曉，日暖玉墀春。","鑒物心如水，憂時鬢若銀。","惟期康庶事，永要敘彝倫。","貴賤知無間，孤寒必許親。","幾多沈滯者，拭目望陶鈞。"]', '["位望誰能並，當年志已伸。","人间傳鳳藻，天上演龙綸。","賈马才無敵，褒雄譽益臻。","除奸深繫念，致主迥忘身。","諫疏縱橫上，危言果敢陳。","忠貞雖貫世，消长豈由人。","慷慨辞朝闕，迢遙涉路塵。","千山明夕照，孤櫂渡长津。","杜宇声方切，江蘺色正新。","卷舒唯合道，喜慍不勞神。","蟬客陪清論，漁翁作近鄰。","静吟窮野景，狂醉養天真。","格論思名士，輿情渴直臣。","九霄恩复降，比戶意皆忻。","却入鴛鸾序，終身顧问頻。","漏殘丹禁晓，日暖玉墀春。","鑒物心如水，憂时鬢若銀。","惟期康庶事，永要敘彝倫。","貴賤知無间，孤寒必許親。","幾多沈滯者，拭目望陶鈞。"]', '诗', 'shi', '', NULL, '獻喬侍郎 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9712bc02-6680-4144-957d-5fe368cca038', '獻中書張舍人', '獻中书張舍人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["仙桂從攀後，人間播大名。","飛騰諧素志，霄漢是前程。","持憲威聲振，司言品秩清。","簾開春酒醒，月上草麻成。","丹陛凌晨對，青雲逐步生。","照人裴玉瑩，鑒物憲陂明。","下直無他事，閑遊恣逸情。","林僧開戶接，溪叟掃苔迎。","煮茗山房冷，垂綸野艇輕。","神清宜放曠，詩苦益縱橫。","餘刃時皆仰，嘉謀衆佇行。","四方觀啓沃，畢竟念孤平。"]', '["仙桂從攀後，人间播大名。","飞腾諧素志，霄漢是前程。","持憲威声振，司言品秩清。","簾开春酒醒，月上草麻成。","丹陛凌晨对，青云逐步生。","照人裴玉瑩，鑒物憲陂明。","下直無他事，闲游恣逸情。","林僧开戶接，溪叟掃苔迎。","煮茗山房冷，垂綸野艇轻。","神清宜放曠，诗苦益縱橫。","餘刃时皆仰，嘉謀衆佇行。","四方观啓沃，畢竟念孤平。"]', '诗', 'shi', '', NULL, '獻中書張舍人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c2b5bb-ac00-4332-8fa8-f2860fc22b82', '海上和郎戩員外赴倅職', '海上和郎戩員外赴倅職', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["宋玉逢秋何起悲，新恩委寄好開眉。","班升鴛鷺頻經歲，任佐龔黃必暫時。","乍對煙霞吟海嶠，應思蘋蓼夢江湄。","一朝鳳詔仲徵入，鵬化那教尺鷃知。"]', '["宋玉逢秋何起悲，新恩委寄好开眉。","班升鴛鷺頻經歲，任佐龔黄必暫时。","乍对煙霞吟海嶠，應思蘋蓼梦江湄。","一朝鳳詔仲徵入，鵬化那教尺鷃知。"]', '诗', 'shi', '', NULL, '海上和郎戩員外赴倅職 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5323719b-d795-402b-886c-1c005dd2ab09', '又送赴關', '又送赴关', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["心似白雲歸帝鄉，暫停良畫別龔黃。","煙波乍曉浮蘭櫂，魂夢先飛近御香。","一路伴吟汀草綠，幾程清思水風涼。","想應敷對忠言後，不放鄉雲離太陽。"]', '["心似白云归帝乡，暫停良畫別龔黄。","煙波乍晓浮蘭櫂，魂梦先飞近御香。","一路伴吟汀草綠，幾程清思水风涼。","想應敷对忠言後，不放乡云離太陽。"]', '诗', 'shi', '', NULL, '又送赴關 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b0a2c4-06da-491c-a216-76a249fd7b45', '書郭判官幽齋壁', '书郭判官幽斋壁', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["不妨公退尚清虛，剏得幽齋興有餘。","要引好風清戶牖，旋栽新竹滿庭除。","傾壺待客花開後，煮茗留僧月上初。","更有野情堪愛處，石牀苔蘚似匡廬。"]', '["不妨公退尚清虛，剏得幽斋兴有餘。","要引好风清戶牖，旋栽新竹满庭除。","傾壺待客花开後，煮茗留僧月上初。","更有野情堪愛处，石牀苔蘚似匡廬。"]', '诗', 'shi', '', NULL, '書郭判官幽齋壁 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ae3e0a-e3c1-4224-b386-6f7e8d5dc075', '石棊局獻時宰', '石棊局獻时宰', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["得從岳叟誠堪重，却獻臯夔事更宜。","公退啓枰書院靜，日斜收子竹陰移。","適情豈待樵柯爛，罷局還應屐齒隳。","預想幽窗風雨夜，一燈閑照覆圖時。"]', '["得從岳叟誠堪重，却獻臯夔事更宜。","公退啓枰书院静，日斜收子竹陰移。","適情豈待樵柯爛，罷局還應屐齒隳。","預想幽窗风雨夜，一灯闲照覆圖时。"]', '诗', 'shi', '', NULL, '石棊局獻時宰 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('394b6d18-0f4e-46af-ae57-6570d6ee8004', '海城秋夕寄懷舍弟', '海城秋夕寄懷舍弟', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["鳥棲庭樹夜悠悠，枕上誰知淚暗流。","千里夢魂迷舊業，一城砧杵搗殘秋。","窗閑寂寂燈猶在，簾外蕭蕭雨未休。","早晚萊衣同著去，免悲流落在邊州。"]', '["鸟棲庭樹夜悠悠，枕上誰知泪暗流。","千里梦魂迷旧業，一城砧杵捣殘秋。","窗闲寂寂灯猶在，簾外蕭蕭雨未休。","早晚萊衣同著去，免悲流落在邊州。"]', '诗', 'shi', '', NULL, '海城秋夕寄懷舍弟 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ca9b822-94d4-4adb-b733-a8fd96a022c5', '和夏侯秀才春日見寄', '和夏侯秀才春日见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["綿蠻黃鳥不堪聽，觸目離愁怕酒醒。","雲散碧山當晚檻，雨催青蘚匝春庭。","尋芳懶向桃花塢，垂釣空思杜若汀。","晝夢不成吟有興，揮毫書在枕邊屏。"]', '["綿蠻黄鸟不堪听，觸目離愁怕酒醒。","云散碧山當晚檻，雨催青蘚匝春庭。","尋芳懶向桃花塢，垂釣空思杜若汀。","晝梦不成吟有兴，揮毫书在枕邊屏。"]', '诗', 'shi', '', NULL, '和夏侯秀才春日見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4eaa4e-97ac-4cb6-aa6b-1444a0fa2096', '送夏侯秀才', '送夏侯秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["江村搖落暮蟬鳴，執手臨岐動別情。","古岸相看殘照在，片帆難駐好風生。","牽吟一路逢山色，醒睡長汀對月明。","況是清朝至公在，預知喬木定遷鶯。"]', '["江村搖落暮蟬鳴，執手臨岐动別情。","古岸相看殘照在，片帆难駐好风生。","牽吟一路逢山色，醒睡长汀对月明。","況是清朝至公在，預知喬木定遷鶯。"]', '诗', 'shi', '', NULL, '送夏侯秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('032bf400-f1fc-4d70-88d4-1387e993700f', '江南重會友人感舊二首 一', '江南重會友人感旧二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["江南重會面，聊話十年心。","共立黃花畔，空驚素髮侵。","斜陽浮遠水，歸鳥下疎林。","牽動詩魔處，涼風村落砧。"]', '["江南重會面，聊話十年心。","共立黄花畔，空驚素髮侵。","斜陽浮远水，归鸟下疎林。","牽动诗魔处，涼风村落砧。"]', '诗', 'shi', '', NULL, '江南重會友人感舊二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a34e3a94-f1c5-478d-b135-f5d276a6492d', '江南重會友人感舊二首 二', '江南重會友人感旧二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["長江落照天，物景似當年。","憶昔攜村酒，相將上釣船。","狂歌紅蓼岸，驚起白鷗眠。","今日趨名急，臨風一黯然。"]', '["长江落照天，物景似當年。","憶昔携村酒，相將上釣船。","狂歌紅蓼岸，驚起白鷗眠。","今日趨名急，臨风一黯然。"]', '诗', 'shi', '', NULL, '江南重會友人感舊二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a9991a-6ddc-4c0b-aa5f-5e53adcda83a', '己未歲冬捧宣頭離下蔡', '己未歲冬捧宣头離下蔡', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["詔下如春煦，巢南志不違。","空將感恩淚，滴盡冒寒衣。","覆載元容善，形骸果得歸。","無心漸季路，負米覲親闈。"]', '["詔下如春煦，巢南志不違。","空將感恩泪，滴尽冒寒衣。","覆載元容善，形骸果得归。","無心漸季路，負米覲親闈。"]', '诗', 'shi', '', NULL, '己未歲冬捧宣頭離下蔡 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c183c0-58c9-4f83-9cd6-7323965eed5c', '哭舍弟二首 一', '哭舍弟二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["鴻鴈離群後，成行憶日存。","誰知歸故里，只得奠吟魂。","蟲蠹書盈篋，人稀草擁門。","從茲長慟後，獨自奉晨昏。"]', '["鴻鴈離群後，成行憶日存。","誰知归故里，只得奠吟魂。","蟲蠹书盈篋，人稀草擁门。","從茲长慟後，独自奉晨昏。"]', '诗', 'shi', '', NULL, '哭舍弟二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a32e2219-4ebd-46fc-a6a4-5507b53af8f5', '哭舍弟二首 二', '哭舍弟二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["浮生多夭枉，惟爾最堪悲。","同氣未歸日，慈親臨老時。","舊詩傳海嶠，新塚枕江湄。","遺稚嗚嗚處，黃昏繞穗帷。"]', '["浮生多夭枉，惟爾最堪悲。","同氣未归日，慈親臨老时。","旧诗傳海嶠，新塚枕江湄。","遺稚嗚嗚处，黄昏繞穗帷。"]', '诗', 'shi', '', NULL, '哭舍弟二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e756a61-a7c4-41ff-8ba8-9d4d3a4ba130', '書情寄詩友', '书情寄诗友', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["默默誰知我，裴回野水邊。","詩情長若舊，吾事更無先。","芳草人稀地，殘陽鴈過天。","靜思吟友外，此意復誰憐。"]', '["默默誰知我，裴回野水邊。","诗情长若旧，吾事更無先。","芳草人稀地，殘陽鴈過天。","静思吟友外，此意复誰怜。"]', '诗', 'shi', '', NULL, '書情寄詩友 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb39184-b01c-4577-bbcb-f1471ee8de3a', '讀蜀志', '读蜀志', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["鼎分天地日，先主力元微。","魚水從相得，山河遂有歸。","任賢無間忌，報國盡神機。","草昧爭雄者，君臣似此稀。"]', '["鼎分天地日，先主力元微。","鱼水從相得，山河遂有归。","任賢無间忌，報国尽神機。","草昧爭雄者，君臣似此稀。"]', '诗', 'shi', '', NULL, '讀蜀志 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c924da38-8916-427b-8a4c-287f0918585b', '獻張拾遺', '獻張拾遺', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["官資清貴近丹墀，性格孤高世所稀。","金殿日開親鳳扆，古幈時展看漁磯。","酒醒虛閣秋簾捲，吟對疎篁夕鳥歸。","獻替頻陳忠譽播，鵬霄萬里展雄飛。"]', '["官資清貴近丹墀，性格孤高世所稀。","金殿日开親鳳扆，古幈时展看漁磯。","酒醒虛閣秋簾捲，吟对疎篁夕鸟归。","獻替頻陳忠譽播，鵬霄万里展雄飞。"]', '诗', 'shi', '', NULL, '獻張拾遺 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c60dde-c7ce-4fd7-9ae3-d2f79371d650', '獻中書湯舍人', '獻中书湯舍人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["慶雲呈瑞爲明時，演暢絲綸在紫微。","鑾殿對時親舜日，鯉庭過處著萊衣。","閑尋竹寺聽啼鳥，吟倚江樓戀落暉。","隔座銀屏看是設，一門清貴古今稀。"]', '["慶云呈瑞爲明时，演暢絲綸在紫微。","鑾殿对时親舜日，鯉庭過处著萊衣。","闲尋竹寺听啼鸟，吟倚江楼戀落暉。","隔座銀屏看是設，一门清貴古今稀。"]', '诗', 'shi', '', NULL, '獻中書湯舍人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62192e5b-f928-4529-9a04-7e630463914d', '海上太守新剏東亭', '海上太守新剏东亭', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["使君心智杳難同，選勝開亭景莫窮。","高敞軒窗迎海月，預栽花木待春風。","靜披典籍堪師古，醉擁笙歌不礙公。","滿徑苔紋疎雨後，入簷山色夕陽中。","偏宜下榻延徐孺，最稱登門禮孔融。","事簡豈妨頻賞翫，況當爲政有餘功。"]', '["使君心智杳难同，選勝开亭景莫窮。","高敞軒窗迎海月，預栽花木待春风。","静披典籍堪師古，醉擁笙歌不礙公。","满徑苔紋疎雨後，入簷山色夕陽中。","偏宜下榻延徐孺，最稱登门禮孔融。","事簡豈妨頻賞翫，況當爲政有餘功。"]', '诗', 'shi', '', NULL, '海上太守新剏東亭 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7818bc9f-74d9-44cb-a591-cc6416d08820', '宮詞二首 一', '宮词二首 一', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["門鏁簾垂月影斜，翠華咫尺隔天涯。","香鋪羅幌不成夢，背壁銀缸落盡花。"]', '["门鏁簾垂月影斜，翠华咫尺隔天涯。","香鋪羅幌不成梦，背壁銀缸落尽花。"]', '诗', 'shi', '', NULL, '宮詞二首 一 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71f6c4bc-776d-4674-8785-e72e5578526b', '宮詞二首 二', '宮词二首 二', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["金波寒透水精簾，燒盡沈檀手自添。","風遞笙歌門已掩，翠華何處夜厭厭。"]', '["金波寒透水精簾，燒尽沈檀手自添。","风遞笙歌门已掩，翠华何处夜厭厭。"]', '诗', 'shi', '', NULL, '宮詞二首 二 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731a03c8-516e-40cf-b1b4-4cfabf372004', '採蓮女', '採蓮女', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["晚涼含笑上蘭舟，波底紅妝影欲浮。","陌上少年休植足，荷香深處不迴頭。"]', '["晚涼含笑上蘭舟，波底紅妝影欲浮。","陌上少年休植足，荷香深处不迴头。"]', '诗', 'shi', '', NULL, '採蓮女 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70bc1882-b13a-4a6e-8777-6cdad5b7de1e', '鍾陵春思', '鍾陵春思', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["沈沈樓影月當午，冉冉風香花正開。","芳草迢迢滿南陌，王孫何處不歸來。"]', '["沈沈楼影月當午，冉冉风香花正开。","芳草迢迢满南陌，王孫何处不归来。"]', '诗', 'shi', '', NULL, '鍾陵春思 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4f57884-539d-485f-86e6-8ac3170b4f04', '贈夏秀才', '贈夏秀才', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["軒車紫陌競尋春，獨掩衡門病起身。","步月怕傷三徑蘚，取琴因拂一牀塵。","明時儻有丹枝分，青鑑從他素髮新。","況是青雲知己在，原思生計莫憂貧。"]', '["軒车紫陌競尋春，独掩衡门病起身。","步月怕傷三徑蘚，取琴因拂一牀塵。","明时儻有丹枝分，青鑑從他素髮新。","況是青云知己在，原思生計莫憂貧。"]', '诗', 'shi', '', NULL, '贈夏秀才 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acabd0b0-1481-4e50-ac71-1ecc45781175', '夏日書依上人壁', '夏日书依上人壁', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["門外塵飛暑氣濃，院中蕭索似山中。","最憐煮茗相留處，疎竹當軒一榻風。"]', '["门外塵飞暑氣濃，院中蕭索似山中。","最怜煮茗相留处，疎竹當軒一榻风。"]', '诗', 'shi', '', NULL, '夏日書依上人壁 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a1115b-822a-4c0d-9f10-8ef55ce1cb5e', '下蔡春暮旅懷', '下蔡春暮旅懷', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["柳過春霖絮亂飛，旅中懷抱獨[悽悽]。","月生淮上雲初散，家在江南夢去迷。","髮白每慙清鑑啓，心孤長怯子規啼。","拜恩爲養慈親急，願向明朝捧紫泥。"]', '["柳過春霖絮亂飞，旅中懷抱独[悽悽]。","月生淮上云初散，家在江南梦去迷。","髮白每慙清鑑啓，心孤长怯子規啼。","拜恩爲養慈親急，願向明朝捧紫泥。"]', '诗', 'shi', '', NULL, '下蔡春暮旅懷 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed35690-e5c7-461f-a861-21e837ec4aca', '捧宣頭許歸侍養', '捧宣头許归侍養', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["泥書捧處聖恩新，許覲庭闈養二親。","螻蟻至微寧足數，未知何處答穹旻。"]', '["泥书捧处聖恩新，許覲庭闈養二親。","螻蟻至微寧足數，未知何处答穹旻。"]', '诗', 'shi', '', NULL, '捧宣頭許歸侍養 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e10585-0f8e-4b1f-ab52-babf9dbfdf44', '途中作', '途中作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["煙波涉歷指家林，欲到家林懼却深。","得信慈親痾瘵減，當時寬勉採蘭心。"]', '["煙波涉歷指家林，欲到家林懼却深。","得信慈親痾瘵減，當时寬勉採蘭心。"]', '诗', 'shi', '', NULL, '途中作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecbf9aaf-f31d-4314-94dc-d4adf4bb6ffc', '都下再會友人', '都下再會友人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["誰言多難後，重會喜淹留。","欲話關河夢，先驚鬢髮秋。","浮雲空冉冉，遠水自悠悠。","多謝開青眼，攜壺共上樓。"]', '["誰言多难後，重會喜淹留。","欲話关河梦，先驚鬢髮秋。","浮云空冉冉，远水自悠悠。","多謝开青眼，携壺共上楼。"]', '诗', 'shi', '', NULL, '都下再會友人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc30e9f-8e01-442d-b633-e35b71f97027', '登毘陵青山樓', '登毘陵青山楼', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["高樓閑上對晴空，豁目開襟半日中。","千里吳山清不斷，一邊遼海浸無窮。","人生歌笑開花霧，世界興亡落葉風。","吟罷倚欄何限意，回頭城郭暮煙籠。"]', '["高楼闲上对晴空，豁目开襟半日中。","千里吳山清不斷，一邊遼海浸無窮。","人生歌笑开花霧，世界兴亡落葉风。","吟罷倚欄何限意，回头城郭暮煙籠。"]', '诗', 'shi', '', NULL, '登毘陵青山樓 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d0c6032-a0dd-4ac0-b63b-45ea9edf60e5', '晉陵罷任寓居依韻和陳銳秀才見寄', '晉陵罷任寓居依韻和陳銳秀才见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["掩門三徑莓苔綠，車馬誰來陋巷間。","臥棄琴書公幹病，笑迎風月步兵閑。","當秋每謝蛬清耳，漸老多慙酒借顏。","濟物未能伸一術，敢於明代愛青山。"]', '["掩门三徑莓苔綠，车马誰来陋巷间。","臥棄琴书公幹病，笑迎风月步兵闲。","當秋每謝蛬清耳，漸老多慙酒借顏。","濟物未能伸一術，敢於明代愛青山。"]', '诗', 'shi', '', NULL, '晉陵罷任寓居依韻和陳銳秀才見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8448017-073f-4d7a-a1c4-8b5f7e046acd', '春苔', '春苔', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["春霖催得鎖煙濃，竹院莎齋徑小通。","誰愛落花風味處，莫愁門巷襯殘紅。"]', '["春霖催得鎖煙濃，竹院莎斋徑小通。","誰愛落花风味处，莫愁门巷襯殘紅。"]', '诗', 'shi', '', NULL, '春苔 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('169c0859-84c4-4f68-a5cf-2523bef6bd36', '夏雲', '夏云', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["如峰形狀在西郊，未見從龍上泬寥。","多謝好風吹起後，化爲甘雨濟田苗。"]', '["如峰形狀在西郊，未见從龙上泬寥。","多謝好风吹起後，化爲甘雨濟田苗。"]', '诗', 'shi', '', NULL, '夏雲 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5ad7fb3-9f7f-4e7f-b6a5-de2a5974be09', '書夏秀才幽居壁', '书夏秀才幽居壁', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["永巷苔深戶半開，牀頭書劒積塵埃。","最憐小檻疎篁晩，幽鳥雙雙何處來。"]', '["永巷苔深戶半开，牀头书劒積塵埃。","最怜小檻疎篁晩，幽鸟雙雙何处来。"]', '诗', 'shi', '', NULL, '書夏秀才幽居壁 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e299667-0a16-48f2-8942-68ca2ecf5f33', '紅花', '紅花', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["紅花顏色掩千花，任是猩猩血未加。","染出輕羅莫相貴，古人崇儉誡奢華。"]', '["紅花顏色掩千花，任是猩猩血未加。","染出轻羅莫相貴，古人崇儉誡奢华。"]', '诗', 'shi', '', NULL, '紅花 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68f17e0-18b1-4d75-9f39-7035508d55a1', '安福縣秋吟寄陳銳秘書', '安福縣秋吟寄陳銳秘书', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["縣庭事簡得餘功，詩興秋來不可窮。","臥聽寒蛬莎砌月，行衝落葉水村風。","愁髭漸去人前白，醉面猶憐鑑裏紅。","苦恨交親多契闊，未知良會幾時同。"]', '["縣庭事簡得餘功，诗兴秋来不可窮。","臥听寒蛬莎砌月，行衝落葉水村风。","愁髭漸去人前白，醉面猶怜鑑裏紅。","苦恨交親多契闊，未知良會幾时同。"]', '诗', 'shi', '', NULL, '安福縣秋吟寄陳銳秘書 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2096f5c4-9908-4eef-b561-44bfe143e8de', '新喻縣酬王仲華少府見貽', '新喻縣酬王仲华少府见貽', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["事簡開樽有逸情，共忻官舍月華清。","每慙花欠河陽景，長愧琴無單父聲。","未泰黎元慚曠職，縱行謙直是虛名。","與君盡力行公道，敢向昌朝俟陟明。"]', '["事簡开樽有逸情，共忻官舍月华清。","每慙花欠河陽景，长愧琴無單父声。","未泰黎元慚曠職，縱行謙直是虛名。","與君尽力行公道，敢向昌朝俟陟明。"]', '诗', 'shi', '', NULL, '新喻縣酬王仲華少府見貽 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dfa1512-5774-4d8e-a07a-896fee7f4e6f', '暮春有感寄宋維員外', '暮春有感寄宋維員外', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["杜宇聲中老病心，此心無計駐光陰。","西園雨過好花盡，南陌人稀芳草深。","喧夢却嫌鶯語老，伴吟惟怕月輪沈。","明年才候東風至，結駟期君預去尋。"]', '["杜宇声中老病心，此心無計駐光陰。","西园雨過好花尽，南陌人稀芳草深。","喧梦却嫌鶯語老，伴吟惟怕月輪沈。","明年才候东风至，結駟期君預去尋。"]', '诗', 'shi', '', NULL, '暮春有感寄宋維員外 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('550020be-f537-4cac-aaa8-b9357a80e8bb', '題吉水縣廳前新栽小松', '題吉水縣廳前新栽小松', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["斸開幽澗蘚苔斑，移得孤根植砌前。","影小未遮官舍月，翠濃猶帶舊山煙。","群花解笑香寧久，衆木雖高節不堅。","輸我婆娑欄檻內，晚風蕭颯學幽泉。"]', '["斸开幽澗蘚苔斑，移得孤根植砌前。","影小未遮官舍月，翠濃猶带旧山煙。","群花解笑香寧久，衆木雖高節不堅。","輸我婆娑欄檻內，晚风蕭颯学幽泉。"]', '诗', 'shi', '', NULL, '題吉水縣廳前新栽小松 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f480ba-1979-4391-afaa-6d0b6b9de62f', '贈念法華經綬上人', '贈念法华經綬上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["五更初起掃松堂，瞑目先焚一炷香。","念徹蓮經誰得見，千峰巖外曉蒼蒼。"]', '["五更初起掃松堂，瞑目先焚一炷香。","念徹蓮經誰得见，千峰巖外晓蒼蒼。"]', '诗', 'shi', '', NULL, '贈念法華經綬上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3444baf4-08c8-41b8-b38e-c619e9218c35', '秋日途中', '秋日途中', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["信步騰騰野岸邊，離家都爲利名牽。","疎林一路斜陽裏，颯颯西風滿耳蟬。"]', '["信步腾腾野岸邊，離家都爲利名牽。","疎林一路斜陽裏，颯颯西风满耳蟬。"]', '诗', 'shi', '', NULL, '秋日途中 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee35c3a8-1979-433a-906e-86fee58de352', '宿韋校書幽居', '宿韋校书幽居', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["溪上高眠與鶴閑，開樽留我待柴關。","園林月白秋霖歇，一夜泉聲似故山。"]', '["溪上高眠與鹤闲，开樽留我待柴关。","园林月白秋霖歇，一夜泉声似故山。"]', '诗', 'shi', '', NULL, '宿韋校書幽居 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c1e838-7329-46bf-8e03-d63e765a6d9e', '依韻和友人秋夕見寄', '依韻和友人秋夕见寄', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["夕風庭葉落，誰見此時情。","不作關河夢，空聞砧杵聲。","會須求至理，何必歎無成。","好約高僧宿，同看海月生。"]', '["夕风庭葉落，誰见此时情。","不作关河梦，空闻砧杵声。","會須求至理，何必歎無成。","好約高僧宿，同看海月生。"]', '诗', 'shi', '', NULL, '依韻和友人秋夕見寄 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e3bd71c-9be5-48f1-a8b4-c03c93c2da03', '吉水作尉酬高援秀才見贈', '吉水作尉酬高援秀才见贈', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["佐邑慙無術，敢言貧與清。","風騷誰是主，煙月自關情。","卷箔當山色，開窗就竹聲。","憐君惠嘉句，資我欲垂名。"]', '["佐邑慙無術，敢言貧與清。","风騷誰是主，煙月自关情。","卷箔當山色，开窗就竹声。","怜君惠嘉句，資我欲垂名。"]', '诗', 'shi', '', NULL, '吉水作尉酬高援秀才見贈 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd4868f-9db9-4f92-945b-373cc4175315', '送智雄上人', '送智雄上人', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["忽起游方念，飄然不可留。","未知攜一錫，乘興向何州。","古岸春雲散，遙天晚雨收。","想應重會面，風月又清秋。"]', '["忽起游方念，飄然不可留。","未知携一錫，乘兴向何州。","古岸春云散，遙天晚雨收。","想應重會面，风月又清秋。"]', '诗', 'shi', '', NULL, '送智雄上人 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e2eb537-652c-4360-a279-ae724c397e4b', '覽友人卷', '覽友人卷', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["新詩開卷處，造化竭精英。","雪霽楚山碧，月高湘水清。","初吟塵慮息，再味古風生。","自此寰區內，喧騰二雅名。"]', '["新诗开卷处，造化竭精英。","雪霽楚山碧，月高湘水清。","初吟塵慮息，再味古风生。","自此寰區內，喧腾二雅名。"]', '诗', 'shi', '', NULL, '覽友人卷 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4084fee4-f461-4dad-a480-9244f0881c1e', '送人南遊', '送人南游', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["浪跡天涯去，南荒必動情。","草青虞帝廟，雲暗夜郎城。","越鳥驚鄉夢，蠻風解宿酲。","早思歸故里，華髮等閑生。"]', '["浪跡天涯去，南荒必动情。","草青虞帝廟，云暗夜郎城。","越鸟驚乡梦，蠻风解宿酲。","早思归故里，华髮等闲生。"]', '诗', 'shi', '', NULL, '送人南遊 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('074ad70b-18df-4e5b-be68-b157f190fd68', '晉陵縣夏日作', '晉陵縣夏日作', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["事簡公庭靜，開簾暑氣中。","依經煎綠茗，入竹就清風。","至論招禪客，忘機憶釣翁。","晚涼安枕簟，海月出牆東。"]', '["事簡公庭静，开簾暑氣中。","依經煎綠茗，入竹就清风。","至論招禪客，忘機憶釣翁。","晚涼安枕簟，海月出牆东。"]', '诗', 'shi', '', NULL, '晉陵縣夏日作 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d81037-1689-4f3a-bbc9-5e8c7b36a9bd', '郵亭早起', '郵亭早起', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["郵舍殘燈在，村林雞唱頻。","星河吟裏曉，川陸望中春。","舊友青雲貴，殊鄉素髮新。","悠悠念行計，難更駐征輪。"]', '["郵舍殘灯在，村林雞唱頻。","星河吟裏晓，川陸望中春。","旧友青云貴，殊乡素髮新。","悠悠念行計，难更駐征輪。"]', '诗', 'shi', '', NULL, '郵亭早起 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd98b72c-7c12-4ae1-8251-29833c96c97c', '客中寒食', '客中寒食', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["旅次經寒食，思鄉淚濕巾。","音書天外斷，桃李雨中春。","欲飲都無緒，唯吟似有因。","輸他郊郭外，多少踏青人。"]', '["旅次經寒食，思乡泪濕巾。","音书天外斷，桃李雨中春。","欲饮都無緒，唯吟似有因。","輸他郊郭外，多少踏青人。"]', '诗', 'shi', '', NULL, '客中寒食 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd5f366-8b04-4e93-a058-99ccaee4293b', '旅館秋夕', '旅館秋夕', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["寥寥山館裏，獨坐酒初醒。","舊業多年別，秋霖一夜聽。","砌蛬聲漸息，窗燭影猶停。","早晚無他事，休如泛水萍。"]', '["寥寥山館裏，独坐酒初醒。","旧業多年別，秋霖一夜听。","砌蛬声漸息，窗燭影猶停。","早晚無他事，休如泛水萍。"]', '诗', 'shi', '', NULL, '旅館秋夕 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f6c0ef-c65e-4dbc-a743-9dcbf65daafb', '宿青溪米處士幽居', '宿青溪米处士幽居', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["寄宿溪光裏，夜涼高士家。","養風窗外竹，叫月水中蛙。","靜慮同搜句，清神旋煮茶。","唯憂曉雞唱，塵裏事如麻。"]', '["寄宿溪光裏，夜涼高士家。","養风窗外竹，叫月水中蛙。","静慮同搜句，清神旋煮茶。","唯憂晓雞唱，塵裏事如麻。"]', '诗', 'shi', '', NULL, '宿青溪米處士幽居 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f576c02-c16d-4761-92fc-0603c815939c', '維舟秋浦逢故人張矩同泊', '維舟秋浦逢故人張矩同泊', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["卸帆清夜碧江濱，冉冉涼風動白蘋。","波上正吟新霽月，岸頭恰見故鄉人。","共驚別後霜侵鬢，互說年來疾逼身。","且飲一壺銷百恨，會須遭遇識通津。"]', '["卸帆清夜碧江濱，冉冉涼风动白蘋。","波上正吟新霽月，岸头恰见故乡人。","共驚別後霜侵鬢，互说年来疾逼身。","且饮一壺銷百恨，會須遭遇識通津。"]', '诗', 'shi', '', NULL, '維舟秋浦逢故人張矩同泊 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4006c711-2ee0-4a58-bc7d-55c85188c9cd', '代別', '代別', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["明日鳴鞭天一涯，悠悠此夕怯分離。","紅樓有恨金波轉，翠黛無言玉筯垂。","浮蟻不能迷遠意，迴紋從此寄相思。","花時定是慵開鑑，獨向春風忍掃眉。"]', '["明日鳴鞭天一涯，悠悠此夕怯分離。","紅楼有恨金波轉，翠黛無言玉筯垂。","浮蟻不能迷远意，迴紋從此寄相思。","花时定是慵开鑑，独向春风忍掃眉。"]', '诗', 'shi', '', NULL, '代別 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6bd0627-682a-4f53-957a-35930625c1df', '悼懷王喪妃', '悼懷王喪妃', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["花綻花開事可驚，暫來浮世返蓬瀛。","楚宮夢斷雲空在，洛浦神歸月自明。","香解返魂成浪語，膠能續斷是虛名。","音容寂寞春牢落，誰會樓中獨立情。"]', '["花綻花开事可驚，暫来浮世返蓬瀛。","楚宮梦斷云空在，洛浦神归月自明。","香解返魂成浪語，膠能續斷是虛名。","音容寂寞春牢落，誰會楼中独立情。"]', '诗', 'shi', '', NULL, '悼懷王喪妃 李中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c431cfd9-679d-4ab7-b8e2-716e4b50dbf7', '酒醒', '酒醒', '051b930e-3c22-4c7b-8373-ece2bed07031', '唐', '["睡覺花陰芳草軟，不知明月出牆東。","杯盤狼藉人何處，聚散空驚似夢中。"]', '["睡覺花陰芳草軟，不知明月出牆东。","杯盤狼藉人何处，聚散空驚似梦中。"]', '诗', 'shi', '', NULL, '酒醒 李中 shi');
